-- =============================================================================
-- Garba Nights — initial schema
--
-- Target: PostgreSQL 15+ on Neon. Apply with `npm run db:setup` or the
-- generated `docs/one-shot-schema.sql`; see `docs/neon-setup.md`.
--
-- Conventions used throughout:
--   * uuid primary keys with `gen_random_uuid()` (built into PG13+, no extension)
--   * `timestamptz` everywhere, defaulting to `now()`
--   * `updated_at` maintained by the `set_updated_at()` trigger, never by clients
--   * status columns are `text` + CHECK constraints (easier to evolve than enums)
--   * money is stored in whole rupees (`integer`); Razorpay amounts are derived
--     as `price_inr * 100` paise at order-creation time
-- =============================================================================


-- -----------------------------------------------------------------------------
-- Roles
--
-- Create the app's database roles when they are missing, so the migration works
-- on a fresh Neon or bare PostgreSQL instance without manual preparation.
-- -----------------------------------------------------------------------------
do $$
begin
  if not exists (select 1 from pg_roles where rolname = 'anon') then
    create role anon nologin noinherit;
  end if;

  if not exists (select 1 from pg_roles where rolname = 'authenticated') then
    create role authenticated nologin noinherit;
  end if;

  if not exists (select 1 from pg_roles where rolname = 'service_role') then
    create role service_role nologin noinherit bypassrls;
  end if;
end
$$;

grant usage on schema public to anon, authenticated, service_role;


-- -----------------------------------------------------------------------------
-- Shared helpers
-- -----------------------------------------------------------------------------

-- Keeps `updated_at` honest regardless of which client writes the row.
create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

comment on function public.set_updated_at() is
  'BEFORE UPDATE trigger: stamps updated_at with now(). Attached to every table that has the column.';

-- Human-readable booking reference, e.g. BK2609-00042.
create sequence if not exists public.booking_id_seq start with 1 increment by 1;

create or replace function public.generate_booking_id()
returns text
language sql
volatile
as $$
  select 'BK' || to_char(now(), 'YYMM') || '-' || lpad(nextval('public.booking_id_seq')::text, 5, '0');
$$;

comment on function public.generate_booking_id() is
  'Generates the customer-facing booking reference. Uniqueness is enforced by bookings.booking_id.';

-- Human-readable pass number, e.g. PS-000123.
create sequence if not exists public.pass_id_seq start with 1 increment by 1;

create or replace function public.generate_pass_id()
returns text
language sql
volatile
as $$
  select 'PS-' || lpad(nextval('public.pass_id_seq')::text, 6, '0');
$$;

comment on function public.generate_pass_id() is
  'Generates the customer-facing digital pass number. Uniqueness is enforced by digital_passes.pass_id.';


-- -----------------------------------------------------------------------------
-- 1. events
-- -----------------------------------------------------------------------------
create table if not exists public.events (
  id              uuid primary key default gen_random_uuid(),
  slug            text not null unique,
  name            text not null,
  tagline         text,
  description     text,
  venue_name      text not null,
  venue_address   text,
  city            text not null,
  state           text,
  maps_url        text,
  hero_image_url  text,
  contact_phone   text,
  contact_email   text,
  currency        text not null default 'INR' check (char_length(currency) = 3),
  status          text not null default 'draft'
                    check (status in ('draft', 'published', 'archived')),
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  constraint events_name_not_blank check (length(btrim(name)) > 0)
);

comment on table public.events is 'One Navratri/Dandiya festival. Public read access is limited to published events.';
comment on column public.events.status is 'draft = hidden from the public site, published = live, archived = kept for history.';

create index if not exists events_status_idx on public.events (status);
create index if not exists events_city_idx on public.events (city);

drop trigger if exists events_set_updated_at on public.events;
create trigger events_set_updated_at
  before update on public.events
  for each row execute function public.set_updated_at();


-- -----------------------------------------------------------------------------
-- 2. event_dates
-- -----------------------------------------------------------------------------
create table if not exists public.event_dates (
  id          uuid primary key default gen_random_uuid(),
  event_id    uuid not null references public.events (id) on delete cascade,
  event_date  date not null,
  start_time  time,
  end_time    time,
  capacity    integer not null default 1000 check (capacity > 0),
  status      text not null default 'scheduled'
                check (status in ('scheduled', 'sold_out', 'cancelled', 'completed')),
  notes       text,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  constraint event_dates_unique_night unique (event_id, event_date),
  constraint event_dates_time_order check (end_time is null or start_time is null or end_time > start_time)
);

comment on table public.event_dates is 'One row per night of the festival. Booking is always against a specific night.';
comment on column public.event_dates.capacity is 'Maximum number of people admitted on this night (sum of bookings.number_of_people).';

-- The unique (event_id, event_date) constraint already indexes event_id as a prefix.
create index if not exists event_dates_event_date_idx on public.event_dates (event_date);
create index if not exists event_dates_status_idx on public.event_dates (status);

drop trigger if exists event_dates_set_updated_at on public.event_dates;
create trigger event_dates_set_updated_at
  before update on public.event_dates
  for each row execute function public.set_updated_at();


-- -----------------------------------------------------------------------------
-- 3. pass_categories
-- -----------------------------------------------------------------------------
create table if not exists public.pass_categories (
  id                uuid primary key default gen_random_uuid(),
  event_id          uuid not null references public.events (id) on delete cascade,
  code              text not null,
  name              text not null,
  composition       text not null,
  description       text,
  price_inr         integer not null check (price_inr >= 0),
  number_of_people  integer not null check (number_of_people > 0),
  max_per_booking   integer not null default 10 check (max_per_booking > 0),
  is_active         boolean not null default true,
  sort_order        integer not null default 0,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  constraint pass_categories_unique_code unique (event_id, code)
);

comment on table public.pass_categories is 'Entry pass types sold for an event, e.g. "2 Girls — Rs 399". Prices live here, never in client code.';
comment on column public.pass_categories.price_inr is 'Whole rupees. Razorpay order amounts are price_inr * 100 (paise).';
comment on column public.pass_categories.number_of_people is 'People admitted by one pass; used for capacity maths.';

create index if not exists pass_categories_active_idx on public.pass_categories (event_id, sort_order) where is_active;

drop trigger if exists pass_categories_set_updated_at on public.pass_categories;
create trigger pass_categories_set_updated_at
  before update on public.pass_categories
  for each row execute function public.set_updated_at();


-- -----------------------------------------------------------------------------
-- 4. bookings
-- -----------------------------------------------------------------------------
create table if not exists public.bookings (
  id                  uuid primary key default gen_random_uuid(),
  booking_id          text not null unique default public.generate_booking_id(),
  customer_name       text not null,
  customer_mobile     text not null,
  customer_email      text not null,
  event_date_id       uuid not null references public.event_dates (id) on delete restrict,
  pass_category_id    uuid not null references public.pass_categories (id) on delete restrict,
  quantity            integer not null check (quantity > 0),
  number_of_people    integer not null check (number_of_people > 0),
  subtotal            integer not null check (subtotal >= 0),
  total_amount        integer not null check (total_amount >= 0),
  booking_status      text not null default 'pending'
                        check (booking_status in ('pending', 'confirmed', 'cancelled', 'expired', 'refunded')),
  payment_status      text not null default 'unpaid'
                        check (payment_status in ('unpaid', 'created', 'paid', 'failed', 'refunded')),
  razorpay_order_id   text unique,
  razorpay_payment_id text unique,
  notes               text,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  constraint bookings_customer_name_not_blank check (length(btrim(customer_name)) > 0),
  constraint bookings_mobile_format check (customer_mobile ~ '^\+?[0-9]{8,15}$'),
  constraint bookings_email_format check (customer_email ~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'),
  constraint bookings_total_within_subtotal check (total_amount <= subtotal)
);

comment on table public.bookings is 'One booking for one pass category on one event night. Amounts are always computed server-side.';
comment on column public.bookings.number_of_people is 'quantity * pass_categories.number_of_people, snapshotted at booking time for capacity maths.';
comment on column public.bookings.subtotal is 'quantity * pass_categories.price_inr at booking time. Derived by trigger, never trusted from the client.';
comment on column public.bookings.total_amount is 'Equals subtotal on insert. A lower value is only reachable through an authorised discount update.';
comment on column public.bookings.booking_status is 'Booking lifecycle, independent of payment_status.';
comment on column public.bookings.payment_status is 'Razorpay payment lifecycle. paid is only ever set after signature verification.';

create index if not exists bookings_event_date_idx on public.bookings (event_date_id);
create index if not exists bookings_pass_category_idx on public.bookings (pass_category_id);
create index if not exists bookings_booking_status_idx on public.bookings (booking_status);
create index if not exists bookings_payment_status_idx on public.bookings (payment_status);
create index if not exists bookings_created_at_idx on public.bookings (created_at desc);
create index if not exists bookings_customer_mobile_idx on public.bookings (customer_mobile);
create index if not exists bookings_customer_email_idx on public.bookings (lower(customer_email));

drop trigger if exists bookings_set_updated_at on public.bookings;
create trigger bookings_set_updated_at
  before update on public.bookings
  for each row execute function public.set_updated_at();

-- Amounts are derived from the pass category so a tampered client payload cannot
-- change the price. subtotal / number_of_people are always overwritten; a
-- total_amount may be supplied for a discount but can never exceed the subtotal.
create or replace function public.set_booking_amounts()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_price integer;
  v_people integer;
  v_max integer;
begin
  select price_inr, number_of_people, max_per_booking
    into v_price, v_people, v_max
  from public.pass_categories
  where id = new.pass_category_id;

  if v_price is null then
    raise exception 'pass_category_id % does not exist', new.pass_category_id
      using errcode = 'foreign_key_violation';
  end if;

  if new.quantity > v_max then
    raise exception 'quantity % exceeds max_per_booking % for this pass category', new.quantity, v_max
      using errcode = 'check_violation';
  end if;

  new.subtotal := new.quantity * v_price;
  new.number_of_people := new.quantity * v_people;

  if tg_op = 'INSERT' then
    -- total_amount is never taken from the caller on insert: the booking costs
    -- exactly what the database says it costs, so a tampered payload cannot
    -- underpay. Discounts are applied afterwards by authorized staff (below).
    new.total_amount := new.subtotal;
  else
    if new.total_amount is null then
      new.total_amount := new.subtotal;
    end if;

    if new.total_amount > new.subtotal then
      raise exception 'total_amount % cannot exceed subtotal %', new.total_amount, new.subtotal
        using errcode = 'check_violation';
    end if;
  end if;

  return new;
end;
$$;

comment on function public.set_booking_amounts() is
  'BEFORE INSERT OR UPDATE trigger: recomputes subtotal and number_of_people from pass_categories (prices can only come from the database) and forces total_amount = subtotal on insert. On update a lower total_amount is allowed for authorised discounts, but never more than the subtotal.';

drop trigger if exists bookings_set_amounts on public.bookings;
create trigger bookings_set_amounts
  before insert or update on public.bookings
  for each row execute function public.set_booking_amounts();


-- -----------------------------------------------------------------------------
-- 5. digital_passes
-- -----------------------------------------------------------------------------
create table if not exists public.digital_passes (
  id             uuid primary key default gen_random_uuid(),
  booking_id     uuid not null references public.bookings (id) on delete cascade,
  pass_id        text not null unique default public.generate_pass_id(),
  qr_token       text not null unique
                   default replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', ''),
  qr_code_url    text,
  valid_date     date not null,
  status         text not null default 'active'
                   check (status in ('active', 'used', 'cancelled', 'expired')),
  checked_in     boolean not null default false,
  checked_in_at  timestamptz,
  created_at     timestamptz not null default now(),
  constraint digital_passes_checked_in_consistency
    check (not checked_in or checked_in_at is not null)
);

comment on table public.digital_passes is 'One scannable pass per admitted group/person, issued after payment is verified.';
comment on column public.digital_passes.qr_token is 'Opaque random token encoded into the QR code. Defaults to 64 hex chars (two UUIDs).';
comment on column public.digital_passes.status is 'used is set together with checked_in/checked_in_at once the pass is scanned at the gate.';

create index if not exists digital_passes_booking_idx on public.digital_passes (booking_id);
create index if not exists digital_passes_valid_date_idx on public.digital_passes (valid_date);
create index if not exists digital_passes_status_idx on public.digital_passes (status);


-- -----------------------------------------------------------------------------
-- 6. gallery
-- -----------------------------------------------------------------------------
-- 'scanner' exists because gate staff need to check passes in without being able
-- to edit events, pricing or bookings.
create table if not exists public.admin_users (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null unique references auth.users (id) on delete cascade,
  email          text not null unique,
  full_name      text,
  role           text not null default 'admin'
                   check (role in ('owner', 'admin', 'manager', 'scanner')),
  is_active      boolean not null default true,
  last_login_at  timestamptz,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

comment on table public.admin_users is 'Legacy allow-list mapping auth users to admin roles. No public access whatsoever.';
comment on column public.admin_users.user_id is 'References auth.users(id); rows are created after the user signs up.';

create index if not exists admin_users_active_idx on public.admin_users (is_active);

drop trigger if exists admin_users_set_updated_at on public.admin_users;
create trigger admin_users_set_updated_at
  before update on public.admin_users
  for each row execute function public.set_updated_at();


-- -----------------------------------------------------------------------------
-- 7. admin_users
-- -----------------------------------------------------------------------------
create table if not exists public.check_ins (
  id               uuid primary key default gen_random_uuid(),
  digital_pass_id  uuid not null references public.digital_passes (id) on delete cascade,
  event_date_id    uuid not null references public.event_dates (id) on delete restrict,
  checked_in_at    timestamptz not null default now(),
  gate             text,
  checked_in_by    uuid references public.admin_users (id) on delete set null,
  notes            text,
  constraint check_ins_one_per_pass unique (digital_pass_id)
);

comment on table public.check_ins is 'Gate scan audit log. The unique constraint on digital_pass_id makes double entry impossible.';

create index if not exists check_ins_event_date_idx on public.check_ins (event_date_id);
create index if not exists check_ins_checked_in_at_idx on public.check_ins (checked_in_at desc);


-- -----------------------------------------------------------------------------
-- 8. check_ins
-- -----------------------------------------------------------------------------
create table if not exists public.gallery (
  id            uuid primary key default gen_random_uuid(),
  event_id      uuid references public.events (id) on delete cascade,
  album         text,
  title         text,
  description   text,
  media_type    text not null default 'image' check (media_type in ('image', 'video')),
  storage_path  text,
  url           text,
  thumbnail_url text,
  alt_text      text not null,
  captured_on   date,
  status        text not null default 'draft'
                  check (status in ('draft', 'published', 'archived')),
  sort_order    integer not null default 0,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  constraint gallery_has_source check (url is not null or storage_path is not null),
  constraint gallery_alt_text_not_blank check (length(btrim(alt_text)) > 0)
);

comment on table public.gallery is 'Event photos and videos. Gallery files are stored in Vercel Blob; this table holds their metadata.';
comment on column public.gallery.alt_text is 'Required: every published image needs descriptive alternative text for accessibility.';
comment on column public.gallery.event_id is 'Nullable so festival-wide media can exist outside a single event.';

create index if not exists gallery_event_idx on public.gallery (event_id);
create index if not exists gallery_status_sort_idx on public.gallery (status, sort_order);

drop trigger if exists gallery_set_updated_at on public.gallery;
create trigger gallery_set_updated_at
  before update on public.gallery
  for each row execute function public.set_updated_at();


-- -----------------------------------------------------------------------------
-- Table privileges
--
-- State these role grants explicitly so the intended public read surface is clear.
-- Row Level Security (see the next migration) restricts which rows each role can see.
-- -----------------------------------------------------------------------------
grant select on public.events, public.event_dates, public.pass_categories, public.gallery
  to anon, authenticated;

grant select, insert, update, delete on public.events, public.event_dates,
  public.pass_categories, public.gallery, public.admin_users to authenticated;

grant select, insert, update on public.bookings to authenticated;
grant select, insert, update on public.digital_passes to authenticated;
grant select, insert on public.check_ins to authenticated;

grant all on public.events, public.event_dates, public.pass_categories, public.bookings,
  public.digital_passes, public.check_ins, public.gallery, public.admin_users
  to service_role;

grant usage, select on all sequences in schema public to service_role;


-- ===========================================================================
-- 20260922090100_rls_policies.sql
-- ===========================================================================

-- =============================================================================
-- Garba Nights — Row Level Security
--
-- Model
--   anon           → may read published public content only (events, dates,
--                    pass categories, gallery). No access to bookings, passes,
--                    check-ins or admin users. Cannot create bookings at all.
--   authenticated  → same public read access as anon, plus admin powers when the
--                    user is present in admin_users with an active role.
--   service_role   → bypasses RLS. Used only in server code for writing
--                    bookings/passes and for Razorpay webhooks. Never shipped
--                    to the browser; all privileged queries stay server-side.
--
-- Helper functions are SECURITY DEFINER so an admin check on admin_users does not
-- recurse through that table's own policies.
-- =============================================================================

alter table public.events          enable row level security;
alter table public.event_dates     enable row level security;
alter table public.pass_categories enable row level security;
alter table public.bookings        enable row level security;
alter table public.digital_passes  enable row level security;
alter table public.check_ins       enable row level security;
alter table public.gallery         enable row level security;
alter table public.admin_users     enable row level security;


-- -----------------------------------------------------------------------------
-- Helpers
-- -----------------------------------------------------------------------------
create or replace function public.is_staff(p_user_id uuid default auth.uid())
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.admin_users
    where user_id = p_user_id
      and is_active
  );
$$;

comment on function public.is_staff(uuid) is
  'True when the given user is an active admin_users row (any role, including scanner).';

create or replace function public.is_admin(p_user_id uuid default auth.uid())
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.admin_users
    where user_id = p_user_id
      and is_active
      and role in ('owner', 'admin', 'manager')
  );
$$;

comment on function public.is_admin(uuid) is
  'True for owner/admin/manager. Scanners are excluded — they may only check passes in.';

create or replace function public.is_owner(p_user_id uuid default auth.uid())
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.admin_users
    where user_id = p_user_id
      and is_active
      and role = 'owner'
  );
$$;

comment on function public.is_owner(uuid) is
  'True only for the owner role — the only role allowed to manage admin_users rows.';

revoke execute on function public.is_staff(uuid) from public;
revoke execute on function public.is_admin(uuid) from public;
revoke execute on function public.is_owner(uuid) from public;
grant execute on function public.is_staff(uuid), public.is_admin(uuid), public.is_owner(uuid)
  to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- Public catalogue: events, event_dates, pass_categories, gallery
--
-- Readable by anon and by any signed-in user (published rows only);
-- fully manageable by admins.
-- -----------------------------------------------------------------------------

drop policy if exists events_anon_read on public.events;
create policy events_anon_read on public.events
  for select to anon
  using (status = 'published');

drop policy if exists events_authenticated_read on public.events;
create policy events_authenticated_read on public.events
  for select to authenticated
  using (status = 'published' or public.is_admin());

drop policy if exists events_admin_manage on public.events;
create policy events_admin_manage on public.events
  for all to authenticated
  using (public.is_admin())
  with check (public.is_admin());


drop policy if exists event_dates_anon_read on public.event_dates;
create policy event_dates_anon_read on public.event_dates
  for select to anon
  using (
    status <> 'cancelled'
    and exists (
      select 1 from public.events e
      where e.id = event_id and e.status = 'published'
    )
  );

drop policy if exists event_dates_authenticated_read on public.event_dates;
create policy event_dates_authenticated_read on public.event_dates
  for select to authenticated
  using (
    public.is_admin()
    or (
      status <> 'cancelled'
      and exists (
        select 1 from public.events e
        where e.id = event_id and e.status = 'published'
      )
    )
  );

drop policy if exists event_dates_admin_manage on public.event_dates;
create policy event_dates_admin_manage on public.event_dates
  for all to authenticated
  using (public.is_admin())
  with check (public.is_admin());


drop policy if exists pass_categories_anon_read on public.pass_categories;
create policy pass_categories_anon_read on public.pass_categories
  for select to anon
  using (
    is_active
    and exists (
      select 1 from public.events e
      where e.id = event_id and e.status = 'published'
    )
  );

drop policy if exists pass_categories_authenticated_read on public.pass_categories;
create policy pass_categories_authenticated_read on public.pass_categories
  for select to authenticated
  using (
    public.is_admin()
    or (
      is_active
      and exists (
        select 1 from public.events e
        where e.id = event_id and e.status = 'published'
      )
    )
  );

drop policy if exists pass_categories_admin_manage on public.pass_categories;
create policy pass_categories_admin_manage on public.pass_categories
  for all to authenticated
  using (public.is_admin())
  with check (public.is_admin());


drop policy if exists gallery_anon_read on public.gallery;
create policy gallery_anon_read on public.gallery
  for select to anon
  using (status = 'published');

drop policy if exists gallery_authenticated_read on public.gallery;
create policy gallery_authenticated_read on public.gallery
  for select to authenticated
  using (status = 'published' or public.is_admin());

drop policy if exists gallery_admin_manage on public.gallery;
create policy gallery_admin_manage on public.gallery
  for all to authenticated
  using (public.is_admin())
  with check (public.is_admin());


-- -----------------------------------------------------------------------------
-- Bookings — never readable or writable by the public.
--
-- There is deliberately no INSERT policy: bookings are created by server code
-- with the service role, after the amount has been recalculated from
-- pass_categories. Staff can read and correct them from the admin dashboard.
-- -----------------------------------------------------------------------------

drop policy if exists bookings_staff_read on public.bookings;
create policy bookings_staff_read on public.bookings
  for select to authenticated
  using (public.is_staff());

drop policy if exists bookings_staff_update on public.bookings;
create policy bookings_staff_update on public.bookings
  for update to authenticated
  using (public.is_staff())
  with check (public.is_staff());


-- -----------------------------------------------------------------------------
-- Digital passes — staff only.
-- -----------------------------------------------------------------------------

drop policy if exists digital_passes_staff_read on public.digital_passes;
create policy digital_passes_staff_read on public.digital_passes
  for select to authenticated
  using (public.is_staff());

drop policy if exists digital_passes_staff_update on public.digital_passes;
create policy digital_passes_staff_update on public.digital_passes
  for update to authenticated
  using (public.is_staff())
  with check (public.is_staff());


-- -----------------------------------------------------------------------------
-- Check-ins — gate staff read and append; nobody edits or deletes history.
-- -----------------------------------------------------------------------------

drop policy if exists check_ins_staff_read on public.check_ins;
create policy check_ins_staff_read on public.check_ins
  for select to authenticated
  using (public.is_staff());

drop policy if exists check_ins_staff_insert on public.check_ins;
create policy check_ins_staff_insert on public.check_ins
  for insert to authenticated
  with check (public.is_staff());


-- -----------------------------------------------------------------------------
-- Admin users — readable by admins, writable only by the owner.
-- -----------------------------------------------------------------------------

drop policy if exists admin_users_admin_read on public.admin_users;
create policy admin_users_admin_read on public.admin_users
  for select to authenticated
  using (public.is_admin());

drop policy if exists admin_users_owner_manage on public.admin_users;
create policy admin_users_owner_manage on public.admin_users
  for all to authenticated
  using (public.is_owner())
  with check (public.is_owner());


-- -----------------------------------------------------------------------------
-- Defence in depth: strip table privileges that no browser session should hold,
-- even if a future migration adds a permissive policy by mistake.
-- -----------------------------------------------------------------------------
revoke all on public.bookings, public.digital_passes, public.check_ins, public.admin_users
  from anon;

revoke insert, delete, truncate on public.bookings from authenticated;
revoke insert, delete, truncate on public.digital_passes from authenticated;
revoke update, delete, truncate on public.check_ins from authenticated;

-- Anonymous visitors must never be able to write to any table.
revoke insert, update, delete, truncate on all tables in schema public from anon;


-- ===========================================================================
-- 20260922090200_public_data_api.sql
-- ===========================================================================

-- =============================================================================
-- Garba Nights — public data API
--
-- Adds everything the public site needs to render entirely from the database:
--
--   1. public.get_event_night_availability() — per-night capacity/availability
--      without exposing a single row of the bookings table.
--   2. event_highlights — "what to expect" bullets, per event.
--   3. event_features   — production inclusions (anchor, DJ, drone…), per event.
--   4. A tweak to the event_dates read policy so cancelled nights are visible
--      (so the UI can say "cancelled" rather than silently hiding the night).
-- =============================================================================


-- -----------------------------------------------------------------------------
-- 1. Availability, aggregated server-side
--
-- Bookings are not readable by the public (see 20260922090100_rls_policies.sql),
-- and that stays true: this function is SECURITY DEFINER, returns only counts,
-- and is the *only* way an anonymous visitor can learn how full a night is.
--
-- Capacity rule: a night is fully booked when its organiser marked it
-- 'sold_out', or when the people already paid for it reach its capacity.
-- Unpaid ('created') orders do not hold capacity — they expire.
-- -----------------------------------------------------------------------------
create or replace function public.get_event_night_availability(p_event_id uuid)
returns table (
  event_date_id   uuid,
  event_date      date,
  start_time      time,
  end_time        time,
  night_status    text,
  capacity        integer,
  booked_people   integer,
  remaining       integer,
  is_fully_booked boolean,
  is_bookable     boolean
)
language sql
stable
security definer
set search_path = public
as $$
  with night as (
    select
      d.id,
      d.event_date,
      d.start_time,
      d.end_time,
      d.status,
      d.capacity,
      coalesce(
        sum(b.number_of_people) filter (where b.payment_status = 'paid'),
        0
      )::integer as booked_people
    from public.event_dates d
    left join public.bookings b on b.event_date_id = d.id
    where d.event_id = p_event_id
      and exists (
        select 1 from public.events e
        where e.id = p_event_id and e.status = 'published'
      )
    group by d.id, d.event_date, d.start_time, d.end_time, d.status, d.capacity
  )
  select
    n.id,
    n.event_date,
    n.start_time,
    n.end_time,
    n.status,
    n.capacity,
    n.booked_people,
    greatest(n.capacity - n.booked_people, 0),
    (n.status = 'sold_out' or n.booked_people >= n.capacity),
    (n.status = 'scheduled' and n.booked_people < n.capacity)
  from night n
  order by n.event_date;
$$;

comment on function public.get_event_night_availability(uuid) is
  'Public per-night availability (capacity, booked people, remaining, FULLY BOOKED flag) for a published event. Aggregates bookings without exposing them; the only capacity signal available to anon.';

revoke execute on function public.get_event_night_availability(uuid) from public;
grant execute on function public.get_event_night_availability(uuid) to anon, authenticated, service_role;


-- -----------------------------------------------------------------------------
-- 2. event_highlights
-- -----------------------------------------------------------------------------
create table if not exists public.event_highlights (
  id          uuid primary key default gen_random_uuid(),
  event_id    uuid not null references public.events (id) on delete cascade,
  title       text not null,
  description text,
  sort_order  integer not null default 0,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  constraint event_highlights_title_not_blank check (length(btrim(title)) > 0)
);

comment on table public.event_highlights is 'Per-event "what to expect" bullets shown on the home and about pages.';

create index if not exists event_highlights_event_idx on public.event_highlights (event_id, sort_order);

drop trigger if exists event_highlights_set_updated_at on public.event_highlights;
create trigger event_highlights_set_updated_at
  before update on public.event_highlights
  for each row execute function public.set_updated_at();


-- -----------------------------------------------------------------------------
-- 3. event_features
--
-- `code` is the stable key the UI maps to an icon; `label` and `description` are
-- editable by the organiser.
-- -----------------------------------------------------------------------------
create table if not exists public.event_features (
  id          uuid primary key default gen_random_uuid(),
  event_id    uuid not null references public.events (id) on delete cascade,
  code        text not null,
  label       text not null,
  description text,
  sort_order  integer not null default 0,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  constraint event_features_code_unique unique (event_id, code),
  constraint event_features_label_not_blank check (length(btrim(label)) > 0)
);

comment on table public.event_features is 'Production inclusions advertised for an event (anchor, DJ, drone…). `code` drives the icon in the UI.';

create index if not exists event_features_event_idx on public.event_features (event_id, sort_order);

drop trigger if exists event_features_set_updated_at on public.event_features;
create trigger event_features_set_updated_at
  before update on public.event_features
  for each row execute function public.set_updated_at();


-- -----------------------------------------------------------------------------
-- 4. Read access for the two new tables
-- -----------------------------------------------------------------------------
grant select on public.event_highlights, public.event_features to anon, authenticated;
grant select, insert, update, delete on public.event_highlights, public.event_features to authenticated;
grant all on public.event_highlights, public.event_features to service_role;

alter table public.event_highlights enable row level security;
alter table public.event_features enable row level security;

drop policy if exists event_highlights_anon_read on public.event_highlights;
create policy event_highlights_anon_read on public.event_highlights
  for select to anon
  using (
    exists (select 1 from public.events e where e.id = event_id and e.status = 'published')
  );

drop policy if exists event_highlights_authenticated_read on public.event_highlights;
create policy event_highlights_authenticated_read on public.event_highlights
  for select to authenticated
  using (
    public.is_admin()
    or exists (select 1 from public.events e where e.id = event_id and e.status = 'published')
  );

drop policy if exists event_highlights_admin_manage on public.event_highlights;
create policy event_highlights_admin_manage on public.event_highlights
  for all to authenticated
  using (public.is_admin())
  with check (public.is_admin());


drop policy if exists event_features_anon_read on public.event_features;
create policy event_features_anon_read on public.event_features
  for select to anon
  using (
    exists (select 1 from public.events e where e.id = event_id and e.status = 'published')
  );

drop policy if exists event_features_authenticated_read on public.event_features;
create policy event_features_authenticated_read on public.event_features
  for select to authenticated
  using (
    public.is_admin()
    or exists (select 1 from public.events e where e.id = event_id and e.status = 'published')
  );

drop policy if exists event_features_admin_manage on public.event_features;
create policy event_features_admin_manage on public.event_features
  for all to authenticated
  using (public.is_admin())
  with check (public.is_admin());


-- -----------------------------------------------------------------------------
-- 5. Show cancelled nights instead of hiding them
--
-- Previously anon could only read non-cancelled nights, which made a cancelled
-- night silently disappear from the site. Visitors should see that the night is
-- cancelled, so the filter moves to the UI: dates of a published event are
-- readable regardless of status (still no bookings, no draft events).
-- -----------------------------------------------------------------------------
drop policy if exists event_dates_anon_read on public.event_dates;
create policy event_dates_anon_read on public.event_dates
  for select to anon
  using (
    exists (select 1 from public.events e where e.id = event_id and e.status = 'published')
  );

drop policy if exists event_dates_authenticated_read on public.event_dates;
create policy event_dates_authenticated_read on public.event_dates
  for select to authenticated
  using (
    public.is_admin()
    or exists (select 1 from public.events e where e.id = event_id and e.status = 'published')
  );


-- ===========================================================================
-- 20260922090300_pass_catalogue_visibility.sql
-- ===========================================================================

-- =============================================================================
-- Garba Nights — pass catalogue visibility
--
-- The site must be able to show a pass that is *not on sale* (greyed out, with
-- the reason) instead of removing it: a visitor who was told about the family
-- pass should still find it and see why it cannot be booked.
--
-- Before this migration, anon could only read pass_categories rows with
-- is_active = true, so a disabled pass silently disappeared. The read policy now
-- exposes the whole catalogue of a published event and `is_active` becomes what
-- it was always meant to be: a flag consumed by the UI and enforced server-side
-- at booking time (bookings are only ever created with the service role).
--
-- No private data is involved — this is catalogue metadata (name, composition,
-- price), not customer or booking information.
-- =============================================================================

drop policy if exists pass_categories_anon_read on public.pass_categories;
create policy pass_categories_anon_read on public.pass_categories
  for select to anon
  using (
    exists (
      select 1 from public.events e
      where e.id = event_id and e.status = 'published'
    )
  );

drop policy if exists pass_categories_authenticated_read on public.pass_categories;
create policy pass_categories_authenticated_read on public.pass_categories
  for select to authenticated
  using (
    public.is_admin()
    or exists (
      select 1 from public.events e
      where e.id = event_id and e.status = 'published'
    )
  );

comment on column public.pass_categories.is_active is
  'Whether the pass can be booked. Inactive passes stay visible on the public site (shown as not on sale) but are rejected at booking time.';


-- ===========================================================================
-- 20260922090400_booking_flow.sql
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- Booking flow: customer-facing reference, duplicate protection, atomic create
--
-- The booking step has no payment yet. A booking is created with
--   booking_status = 'pending'  and  payment_status = 'unpaid'
-- ('unpaid' is the schema's "payment not made" state — see the column comment)
-- and is only ever moved to 'paid' after a verified Razorpay signature, which
-- does not exist yet. Nothing in this migration can mark a booking as paid.
--
-- Everything a customer submits is untrusted. Prices, the number of admitted
-- people, capacity and availability are all decided here in the database, so a
-- tampered request can never lower a price or oversell a night.
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 1. Customer-facing booking reference, e.g. DND202600001
-- ---------------------------------------------------------------------------
-- The sequence (`booking_id_seq`) already exists from the initial schema; only
-- the format changes, from BKYYMM-00001 to DND<year><5 digits>. Uniqueness is
-- enforced by bookings.booking_id.
create or replace function public.generate_booking_id()
returns text
language sql
volatile
as $$
  select 'DND'
    || to_char(now(), 'YYYY')
    || lpad(nextval('public.booking_id_seq')::text, 5, '0');
$$;

comment on function public.generate_booking_id() is
  'Customer-facing booking reference, e.g. DND202600001. Uniqueness is enforced by bookings.booking_id.';

-- ---------------------------------------------------------------------------
-- 2. Duplicate-submission protection
-- ---------------------------------------------------------------------------
-- Every checkout attempt carries a key generated by the browser. Re-sending the
-- same key (double click, retry after a timeout, two tabs) returns the booking
-- that already exists instead of creating a second one.
alter table public.bookings
  add column if not exists idempotency_key text;

comment on column public.bookings.idempotency_key is
  'Opaque key generated per checkout attempt. Unique, so a retried request can never create a second booking.';

create unique index if not exists bookings_idempotency_key_idx
  on public.bookings (idempotency_key)
  where idempotency_key is not null;

-- ---------------------------------------------------------------------------
-- 3. Atomic booking creation
-- ---------------------------------------------------------------------------
-- Called by server code only (service role). It is SECURITY DEFINER so it can
-- insert a booking while RLS still denies every browser insert, and it locks the
-- night row so two concurrent requests cannot both pass the capacity check.
--
-- Rules enforced here, in order:
--   * the night exists, belongs to the event and is 'scheduled'
--   * the pass category exists, belongs to the event and is on sale (is_active)
--   * quantity is a positive integer within the pass category's max_per_booking
--   * the submitted number of people matches quantity x people-per-pass
--   * the night still has capacity for that many people (paid bookings only,
--     exactly like get_event_night_availability)
--   * the price is read from pass_categories and multiplied here — never taken
--     from the caller
--
-- Error protocol for the API layer (SQLSTATE -> meaning):
--   PB001 capacity_unavailable  PB002 night_not_bookable  PB003 pass_not_available
--   PB004 quantity_invalid      PB005 people_mismatch     PB006 night_not_found
create or replace function public.create_pending_booking(
  p_event_id         uuid,
  p_event_date_id    uuid,
  p_pass_category_id uuid,
  p_customer_name    text,
  p_customer_mobile  text,
  p_customer_email   text,
  p_quantity         integer,
  p_number_of_people integer,
  p_idempotency_key  text default null
)
returns table (
  booking_uuid     uuid,
  booking_reference text,
  booking_status   text,
  payment_status   text,
  quantity         integer,
  number_of_people integer,
  subtotal         integer,
  total_amount     integer,
  event_id         uuid,
  event_date_id    uuid,
  event_date       date,
  start_time       time,
  end_time         time,
  pass_category_id uuid,
  pass_name        text,
  pass_composition text,
  currency         text,
  created_at       timestamptz,
  was_existing     boolean
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_night       record;
  v_pass        record;
  v_event       record;
  v_existing    record;
  v_booked      integer;
  v_remaining   integer;
  v_required    integer;
  v_booking_id  uuid;
  v_reference   text;
begin
  -- 3.1 Idempotency: has this attempt already produced a booking?
  if p_idempotency_key is not null and length(btrim(p_idempotency_key)) > 0 then
    select b.id into v_existing
    from public.bookings b
    where b.idempotency_key = btrim(p_idempotency_key);

    if found then
      return query
        select b.id, b.booking_id, b.booking_status, b.payment_status, b.quantity,
               b.number_of_people, b.subtotal, b.total_amount, d.event_id, d.id, d.event_date,
               d.start_time, d.end_time, p.id, p.name, p.composition, e.currency,
               b.created_at, true
        from public.bookings b
        join public.event_dates d on d.id = b.event_date_id
        join public.pass_categories p on p.id = b.pass_category_id
        join public.events e on e.id = d.event_id
        where b.id = v_existing.id;

      return;
    end if;
  end if;

  -- 3.2 Lock the night: concurrent attempts for the same night queue here, so
  -- the capacity read below cannot be stale.
  select d.id, d.event_id, d.event_date, d.status, d.capacity, d.start_time, d.end_time
    into v_night
  from public.event_dates d
  where d.id = p_event_date_id
  for update;

  if not found then
    raise exception 'night_not_found' using errcode = 'PB006';
  end if;

  if v_night.event_id <> p_event_id then
    raise exception 'night_not_found' using errcode = 'PB006';
  end if;

  select e.id, e.name, e.status, e.currency into v_event
  from public.events e
  where e.id = p_event_id;

  if not found or v_event.status <> 'published' then
    raise exception 'night_not_bookable' using errcode = 'PB002';
  end if;

  if v_night.status <> 'scheduled' then
    raise exception 'night_not_bookable' using errcode = 'PB002';
  end if;

  -- 3.3 The pass must belong to this event and be on sale.
  select p.id, p.name, p.composition, p.price_inr, p.number_of_people, p.max_per_booking, p.is_active
    into v_pass
  from public.pass_categories p
  where p.id = p_pass_category_id;

  if not found then
    raise exception 'pass_not_available' using errcode = 'PB003';
  end if;

  if v_pass.is_active is not true then
    raise exception 'pass_not_available' using errcode = 'PB003';
  end if;

  if not exists (
    select 1 from public.pass_categories p
    where p.id = p_pass_category_id and p.event_id = p_event_id
  ) then
    raise exception 'pass_not_available' using errcode = 'PB003';
  end if;

  -- 3.4 Quantity is a positive integer the pass category allows.
  if p_quantity is null or p_quantity < 1 or p_quantity > v_pass.max_per_booking then
    -- detail carries the limit, so the API can say what is allowed.
    raise exception 'quantity_invalid' using errcode = 'PB004', detail = v_pass.max_per_booking::text;
  end if;

  -- 3.5 A pass admits a fixed group, so the submitted head count must match it.
  v_required := p_quantity * v_pass.number_of_people;

  if p_number_of_people is null or p_number_of_people <> v_required then
    -- detail carries the head count this booking must cover.
    raise exception 'people_mismatch' using errcode = 'PB005', detail = v_required::text;
  end if;

  -- 3.6 Capacity, counted the same way as the public availability function:
  -- paid bookings only. A pending booking does not hold a place until it is paid.
  select coalesce(sum(b.number_of_people) filter (where b.payment_status = 'paid'), 0)::integer
    into v_booked
  from public.bookings b
  where b.event_date_id = p_event_date_id;

  v_remaining := greatest(v_night.capacity - v_booked, 0);

  if v_required > v_remaining then
    -- detail carries how many places are actually left.
    raise exception 'capacity_unavailable' using errcode = 'PB001', detail = v_remaining::text;
  end if;

  -- 3.7 Same content, brand-new key inside the double-submit window (a page
  -- reload loses the key): treat it as the same attempt instead of creating a
  -- second booking. Paid or older bookings are never reused.
  select b.id into v_existing
  from public.bookings b
  where b.event_date_id = p_event_date_id
    and b.pass_category_id = p_pass_category_id
    and b.customer_mobile = p_customer_mobile
    and b.quantity = p_quantity
    and b.booking_status = 'pending'
    and b.payment_status = 'unpaid'
    and b.created_at > now() - interval '15 minutes'
  order by b.created_at desc
  limit 1;

  if found then
    return query
      select b.id, b.booking_id, b.booking_status, b.payment_status, b.quantity,
             b.number_of_people, b.subtotal, b.total_amount, d.event_id, d.id, d.event_date,
             d.start_time, d.end_time, p.id, p.name, p.composition, e.currency,
             b.created_at, true
      from public.bookings b
      join public.event_dates d on d.id = b.event_date_id
      join public.pass_categories p on p.id = b.pass_category_id
      join public.events e on e.id = d.event_id
      where b.id = v_existing.id;

    return;
  end if;

  -- 3.8 Insert. number_of_people, subtotal and total_amount are deliberately not
  -- part of the INSERT column list: the set_booking_amounts() trigger computes
  -- all three from pass_categories before the row is written, so money can only
  -- ever come from the database and a price sent by the browser is ignored.
  insert into public.bookings (
    customer_name, customer_mobile, customer_email,
    event_date_id, pass_category_id,
    quantity, booking_status, payment_status, idempotency_key
  )
  values (
    btrim(p_customer_name), p_customer_mobile, p_customer_email,
    p_event_date_id, p_pass_category_id,
    p_quantity, 'pending', 'unpaid',
    nullif(btrim(coalesce(p_idempotency_key, '')), '')
  )
  returning id, bookings.booking_id into v_booking_id, v_reference;

  return query
    select b.id, b.booking_id, b.booking_status, b.payment_status, b.quantity,
           b.number_of_people, b.subtotal, b.total_amount, d.event_id, d.id, d.event_date,
           d.start_time, d.end_time, p.id, p.name, p.composition, e.currency,
           b.created_at, false
    from public.bookings b
    join public.event_dates d on d.id = b.event_date_id
    join public.pass_categories p on p.id = b.pass_category_id
    join public.events e on e.id = d.event_id
    where b.id = v_booking_id;
end;
$$;

comment on function public.create_pending_booking(uuid, uuid, uuid, text, text, text, integer, integer, text) is
  'Creates one pending/unpaid booking atomically: locks the night, re-reads capacity from paid bookings only, reads the price from pass_categories and ignores any client-supplied amount. Service role only — browsers cannot call it.';

revoke all on function public.create_pending_booking(uuid, uuid, uuid, text, text, text, integer, integer, text) from public;
revoke all on function public.create_pending_booking(uuid, uuid, uuid, text, text, text, integer, integer, text) from anon, authenticated;
grant execute on function public.create_pending_booking(uuid, uuid, uuid, text, text, text, integer, integer, text) to service_role;

comment on column public.bookings.payment_status is
  'Payment lifecycle: unpaid -> created (Razorpay order) -> paid | failed | refunded. paid is only ever set after signature verification.';


-- ===========================================================================
-- 20260922090500_payments.sql
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- Razorpay payments (test mode)
--
-- Money is confirmed by the server, never by the browser:
--   * an order is created for a booking whose amount the database already fixed
--   * the checkout signature is verified server-side with the key secret
--   * the payment is re-read from the Razorpay API and must match the booking's
--     order and amount
--   * only then does the booking become paid + confirmed and get its passes
--
-- Duplicate deliveries are harmless: `payment_events.event_id` is unique, the
-- confirmation function is idempotent per booking, and `razorpay_payment_id` is
-- unique so one payment can never be applied to two bookings.
--
-- Nothing here can mark a booking paid on its own: every path requires a
-- signature-verified payment id.
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 1. Public lookup token
-- ---------------------------------------------------------------------------
-- Lets the payment page show the customer their own booking after a refresh
-- without an account and without exposing booking rows: the token is a random
-- uuid, unguessable, and the lookup returns no personal data.
alter table public.bookings
  add column if not exists public_token uuid not null default gen_random_uuid();

create unique index if not exists bookings_public_token_idx on public.bookings (public_token);

comment on column public.bookings.public_token is
  'Random token that identifies one booking for its own customer (payment refresh/status). Never sequential, never returned in lists.';

-- ---------------------------------------------------------------------------
-- 2. Webhook delivery log (duplicate-processing guard)
-- ---------------------------------------------------------------------------
create table if not exists public.payment_events (
  id                 uuid primary key default gen_random_uuid(),
  event_id           text not null unique,
  event_type         text not null,
  razorpay_order_id  text,
  razorpay_payment_id text,
  amount_paise       integer,
  outcome            text not null default 'received',
  received_at        timestamptz not null default now(),
  processed_at       timestamptz
);

comment on table public.payment_events is
  'One row per Razorpay webhook delivery. event_id is unique, so a retried delivery can never be processed twice.';
comment on column public.payment_events.event_id is
  'x-razorpay-event-id when present, otherwise a SHA-256 hash of the raw body — both are stable across retries.';
comment on column public.payment_events.outcome is
  'confirmed | already_confirmed | failed | refunded | ignored | duplicate';

create index if not exists payment_events_order_idx on public.payment_events (razorpay_order_id);
create index if not exists payment_events_received_idx on public.payment_events (received_at desc);

alter table public.payment_events enable row level security;

-- No policies at all: nothing but the service role (which bypasses RLS) can read
-- or write this table.
revoke all on public.payment_events from anon, authenticated;
grant all on public.payment_events to service_role;

-- ---------------------------------------------------------------------------
-- 3. create_pending_booking: same rules, now also returns the lookup token
-- ---------------------------------------------------------------------------
-- The OUT columns changed, so the function is recreated. Its grants are re-applied
-- at the bottom of this migration.
drop function if exists public.create_pending_booking(uuid, uuid, uuid, text, text, text, integer, integer, text);

create or replace function public.create_pending_booking(
  p_event_id         uuid,
  p_event_date_id    uuid,
  p_pass_category_id uuid,
  p_customer_name    text,
  p_customer_mobile  text,
  p_customer_email   text,
  p_quantity         integer,
  p_number_of_people integer,
  p_idempotency_key  text default null
)
returns table (
  booking_uuid     uuid,
  booking_reference text,
  public_token     uuid,
  booking_status   text,
  payment_status   text,
  quantity         integer,
  number_of_people integer,
  subtotal         integer,
  total_amount     integer,
  event_id         uuid,
  event_date_id    uuid,
  event_date       date,
  start_time       time,
  end_time         time,
  pass_category_id uuid,
  pass_name        text,
  pass_composition text,
  currency         text,
  razorpay_order_id text,
  created_at       timestamptz,
  was_existing     boolean
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_night       record;
  v_pass        record;
  v_event       record;
  v_existing    record;
  v_booked      integer;
  v_remaining   integer;
  v_required    integer;
  v_booking_id  uuid;
  v_reference   text;
begin
  -- Idempotency: has this attempt already produced a booking?
  if p_idempotency_key is not null and length(btrim(p_idempotency_key)) > 0 then
    select b.id into v_existing
    from public.bookings b
    where b.idempotency_key = btrim(p_idempotency_key);

    if found then
      return query
        select b.id, b.booking_id, b.public_token, b.booking_status, b.payment_status, b.quantity,
               b.number_of_people, b.subtotal, b.total_amount, d.event_id, d.id, d.event_date,
               d.start_time, d.end_time, p.id, p.name, p.composition, e.currency,
               b.razorpay_order_id, b.created_at, true
        from public.bookings b
        join public.event_dates d on d.id = b.event_date_id
        join public.pass_categories p on p.id = b.pass_category_id
        join public.events e on e.id = d.event_id
        where b.id = v_existing.id;

      return;
    end if;
  end if;

  -- Lock the night: concurrent attempts for the same night queue here, so the
  -- capacity read below cannot be stale.
  select d.id, d.event_id, d.event_date, d.status, d.capacity, d.start_time, d.end_time
    into v_night
  from public.event_dates d
  where d.id = p_event_date_id
  for update;

  if not found then
    raise exception 'night_not_found' using errcode = 'PB006';
  end if;

  if v_night.event_id <> p_event_id then
    raise exception 'night_not_found' using errcode = 'PB006';
  end if;

  select e.id, e.name, e.status, e.currency into v_event
  from public.events e
  where e.id = p_event_id;

  if not found or v_event.status <> 'published' then
    raise exception 'night_not_bookable' using errcode = 'PB002';
  end if;

  if v_night.status <> 'scheduled' then
    raise exception 'night_not_bookable' using errcode = 'PB002';
  end if;

  select p.id, p.name, p.composition, p.price_inr, p.number_of_people, p.max_per_booking, p.is_active
    into v_pass
  from public.pass_categories p
  where p.id = p_pass_category_id;

  if not found or v_pass.is_active is not true then
    raise exception 'pass_not_available' using errcode = 'PB003';
  end if;

  if not exists (
    select 1 from public.pass_categories p
    where p.id = p_pass_category_id and p.event_id = p_event_id
  ) then
    raise exception 'pass_not_available' using errcode = 'PB003';
  end if;

  if p_quantity is null or p_quantity < 1 or p_quantity > v_pass.max_per_booking then
    raise exception 'quantity_invalid' using errcode = 'PB004', detail = v_pass.max_per_booking::text;
  end if;

  v_required := p_quantity * v_pass.number_of_people;

  if p_number_of_people is null or p_number_of_people <> v_required then
    raise exception 'people_mismatch' using errcode = 'PB005', detail = v_required::text;
  end if;

  -- Capacity, counted the same way as the public availability function: paid
  -- bookings only. A pending booking does not hold a place until it is paid.
  select coalesce(sum(b.number_of_people) filter (where b.payment_status = 'paid'), 0)::integer
    into v_booked
  from public.bookings b
  where b.event_date_id = p_event_date_id;

  v_remaining := greatest(v_night.capacity - v_booked, 0);

  if v_required > v_remaining then
    raise exception 'capacity_unavailable' using errcode = 'PB001', detail = v_remaining::text;
  end if;

  -- Same content, brand-new key inside the double-submit window (a page reload
  -- loses the key): treat it as the same attempt instead of creating a second
  -- booking. Paid or older bookings are never reused.
  select b.id into v_existing
  from public.bookings b
  where b.event_date_id = p_event_date_id
    and b.pass_category_id = p_pass_category_id
    and b.customer_mobile = p_customer_mobile
    and b.quantity = p_quantity
    and b.booking_status = 'pending'
    and b.payment_status = 'unpaid'
    and b.created_at > now() - interval '15 minutes'
  order by b.created_at desc
  limit 1;

  if found then
    return query
      select b.id, b.booking_id, b.public_token, b.booking_status, b.payment_status, b.quantity,
             b.number_of_people, b.subtotal, b.total_amount, d.event_id, d.id, d.event_date,
             d.start_time, d.end_time, p.id, p.name, p.composition, e.currency,
             b.razorpay_order_id, b.created_at, true
      from public.bookings b
      join public.event_dates d on d.id = b.event_date_id
      join public.pass_categories p on p.id = b.pass_category_id
      join public.events e on e.id = d.event_id
      where b.id = v_existing.id;

    return;
  end if;

  -- number_of_people, subtotal and total_amount are deliberately not part of the
  -- INSERT column list: the set_booking_amounts() trigger computes all three from
  -- pass_categories before the row is written.
  insert into public.bookings (
    customer_name, customer_mobile, customer_email,
    event_date_id, pass_category_id,
    quantity, booking_status, payment_status, idempotency_key
  )
  values (
    btrim(p_customer_name), p_customer_mobile, p_customer_email,
    p_event_date_id, p_pass_category_id,
    p_quantity, 'pending', 'unpaid',
    nullif(btrim(coalesce(p_idempotency_key, '')), '')
  )
  returning id, bookings.booking_id into v_booking_id, v_reference;

  return query
    select b.id, b.booking_id, b.public_token, b.booking_status, b.payment_status, b.quantity,
           b.number_of_people, b.subtotal, b.total_amount, d.event_id, d.id, d.event_date,
           d.start_time, d.end_time, p.id, p.name, p.composition, e.currency,
           b.razorpay_order_id, b.created_at, false
    from public.bookings b
    join public.event_dates d on d.id = b.event_date_id
    join public.pass_categories p on p.id = b.pass_category_id
    join public.events e on e.id = d.event_id
    where b.id = v_booking_id;
end;
$$;

comment on function public.create_pending_booking(uuid, uuid, uuid, text, text, text, integer, integer, text) is
  'Creates one pending/unpaid booking atomically: locks the night, re-reads capacity from paid bookings only, reads the price from pass_categories and ignores any client-supplied amount. Service role only.';

revoke all on function public.create_pending_booking(uuid, uuid, uuid, text, text, text, integer, integer, text) from public;
revoke all on function public.create_pending_booking(uuid, uuid, uuid, text, text, text, integer, integer, text) from anon, authenticated;
grant execute on function public.create_pending_booking(uuid, uuid, uuid, text, text, text, integer, integer, text) to service_role;

-- ---------------------------------------------------------------------------
-- 4. Attach a Razorpay order to a booking
-- ---------------------------------------------------------------------------
-- Written only when the booking does not have an order yet, so a double click
-- cannot quietly overwrite the order a customer is paying.
create or replace function public.attach_razorpay_order(
  p_booking_id       uuid,
  p_razorpay_order_id text
)
returns table (booking_uuid uuid, razorpay_order_id text, attached boolean)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_current text;
begin
  select b.razorpay_order_id into v_current
  from public.bookings b
  where b.id = p_booking_id
  for update;

  if not found then
    raise exception 'booking_not_found' using errcode = 'PC004';
  end if;

  if v_current is not null then
    return query select p_booking_id, v_current, false;
    return;
  end if;

  update public.bookings b
  set razorpay_order_id = p_razorpay_order_id
  where b.id = p_booking_id;

  return query select p_booking_id, p_razorpay_order_id, true;
end;
$$;

comment on function public.attach_razorpay_order(uuid, text) is
  'Stores the Razorpay order id on a booking once. Re-running returns the order that is already attached.';

-- ---------------------------------------------------------------------------
-- 5. Confirmation — the only path that can set payment_status = paid
-- ---------------------------------------------------------------------------
create or replace function public.confirm_booking_payment(
  p_razorpay_order_id  text,
  p_razorpay_payment_id text,
  p_amount_paise       integer default null
)
returns table (
  booking_uuid     uuid,
  booking_reference text,
  public_token     uuid,
  booking_status   text,
  payment_status   text,
  quantity         integer,
  number_of_people integer,
  subtotal         integer,
  total_amount     integer,
  event_id         uuid,
  event_date       date,
  start_time       time,
  end_time         time,
  pass_name        text,
  pass_composition text,
  currency         text,
  passes_issued    integer,
  already_confirmed boolean,
  capacity_note    text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking  record;
  v_holder   uuid;
  v_booked   integer;
  v_capacity integer;
  v_note     text;
begin
  select b.* into v_booking
  from public.bookings b
  where b.razorpay_order_id = p_razorpay_order_id
  for update;

  if not found then
    raise exception 'order_not_found' using errcode = 'PC001';
  end if;

  -- The amount must be what the database says the booking costs. A ₹1 payment
  -- cannot confirm a ₹998 booking.
  if p_amount_paise is not null and p_amount_paise <> v_booking.total_amount * 100 then
    raise exception 'amount_mismatch' using errcode = 'PC002';
  end if;

  -- One payment can only ever belong to one booking.
  select b.id into v_holder
  from public.bookings b
  where b.razorpay_payment_id = p_razorpay_payment_id
    and b.id <> v_booking.id;

  if found then
    raise exception 'payment_already_used' using errcode = 'PC003';
  end if;

  -- Already paid: a duplicate callback gets the same answer, and nothing is
  -- written again (no second set of passes).
  if v_booking.payment_status = 'paid' then
    return query
      select b.id, b.booking_id, b.public_token, b.booking_status, b.payment_status, b.quantity,
             b.number_of_people, b.subtotal, b.total_amount, d.event_id, d.event_date,
             d.start_time, d.end_time, p.name, p.composition, e.currency,
             (select count(*)::integer from public.digital_passes dp where dp.booking_id = b.id),
             true, b.notes
      from public.bookings b
      join public.event_dates d on d.id = b.event_date_id
      join public.pass_categories p on p.id = b.pass_category_id
      join public.events e on e.id = d.event_id
      where b.id = v_booking.id;

    return;
  end if;

  -- From here on the booking is being paid for the first time, so a payment id is
  -- mandatory: an event without one (`order.paid` on its own) is ignored by the
  -- dispatcher and the `payment.captured` delivery does the work instead.
  if p_razorpay_payment_id is null or length(btrim(p_razorpay_payment_id)) = 0 then
    raise exception 'payment_id_required' using errcode = 'PC005';
  end if;

  -- Capacity is checked again, but the customer has already paid: the booking is
  -- confirmed either way and an organiser flag is recorded instead of silently
  -- dropping a paid booking.
  select coalesce(sum(b.number_of_people) filter (where b.payment_status = 'paid'), 0)::integer
    into v_booked
  from public.bookings b
  where b.event_date_id = v_booking.event_date_id
    and b.id <> v_booking.id;

  select d.capacity into v_capacity
  from public.event_dates d
  where d.id = v_booking.event_date_id;

  if v_booked + v_booking.number_of_people > v_capacity then
    v_note := 'capacity exceeded when payment was confirmed — needs organiser review';
  end if;

  update public.bookings b
  set payment_status   = 'paid',
      booking_status   = 'confirmed',
      razorpay_payment_id = p_razorpay_payment_id,
      notes            = coalesce(v_note, b.notes)
  where b.id = v_booking.id;

  -- One scannable pass per purchased pass, issued only now that payment is
  -- verified. Guarded so a replay can never double the passes.
  insert into public.digital_passes (booking_id, valid_date, status)
  select v_booking.id, d.event_date, 'active'
  from public.event_dates d
  cross join generate_series(1, v_booking.quantity)
  where d.id = v_booking.event_date_id
    and not exists (select 1 from public.digital_passes dp where dp.booking_id = v_booking.id);

  return query
    select b.id, b.booking_id, b.public_token, b.booking_status, b.payment_status, b.quantity,
           b.number_of_people, b.subtotal, b.total_amount, d.event_id, d.event_date,
           d.start_time, d.end_time, p.name, p.composition, e.currency,
           (select count(*)::integer from public.digital_passes dp where dp.booking_id = b.id),
           false, b.notes
    from public.bookings b
    join public.event_dates d on d.id = b.event_date_id
    join public.pass_categories p on p.id = b.pass_category_id
    join public.events e on e.id = d.event_id
    where b.id = v_booking.id;
end;
$$;

comment on function public.confirm_booking_payment(text, text, integer) is
  'Marks a booking paid + confirmed after a server-verified payment, issues its digital passes, and is idempotent: a repeated call returns the same booking without writing anything.';

-- ---------------------------------------------------------------------------
-- 6. Failure and refund
-- ---------------------------------------------------------------------------
create or replace function public.fail_booking_payment(
  p_razorpay_order_id   text,
  p_razorpay_payment_id text default null
)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking record;
begin
  select b.* into v_booking
  from public.bookings b
  where b.razorpay_order_id = p_razorpay_order_id
  for update;

  if not found then
    return 'not_found';
  end if;

  -- A paid booking is never downgraded by a late failure event.
  if v_booking.payment_status = 'paid' then
    return 'already_paid';
  end if;

  update public.bookings b
  set payment_status = 'failed'
  where b.id = v_booking.id;

  return 'failed';
end;
$$;

comment on function public.fail_booking_payment(text, text) is
  'Records a failed payment attempt on a pending booking. Never downgrades a paid booking.';

create or replace function public.refund_booking_payment(
  p_razorpay_payment_id text
)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking record;
begin
  select b.* into v_booking
  from public.bookings b
  where b.razorpay_payment_id = p_razorpay_payment_id
  for update;

  if not found then
    return 'not_found';
  end if;

  if v_booking.payment_status = 'refunded' then
    return 'already_refunded';
  end if;

  update public.bookings b
  set payment_status = 'refunded',
      booking_status = 'refunded'
  where b.id = v_booking.id;

  update public.digital_passes dp
  set status = 'cancelled'
  where dp.booking_id = v_booking.id;

  return 'refunded';
end;
$$;

comment on function public.refund_booking_payment(text) is
  'Marks a refunded booking and cancels its digital passes (the unique check-in per pass still holds).';

-- ---------------------------------------------------------------------------
-- 7. Webhook dispatcher — claim, act, record, all in one transaction
-- ---------------------------------------------------------------------------
create or replace function public.apply_razorpay_event(
  p_event_id          text,
  p_event_type        text,
  p_razorpay_order_id text default null,
  p_razorpay_payment_id text default null,
  p_amount_paise      integer default null
)
returns table (
  duplicate         boolean,
  outcome           text,
  booking_reference text,
  passes_issued     integer
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_inserted  integer;
  v_outcome   text := 'ignored';
  v_reference text;
  v_passes    integer;
  v_result    record;
begin
  -- Claim the delivery. A retried webhook hits the unique constraint and stops
  -- here, so no side effect can happen twice.
  insert into public.payment_events (event_id, event_type, razorpay_order_id, razorpay_payment_id, amount_paise)
  values (p_event_id, p_event_type, p_razorpay_order_id, p_razorpay_payment_id, p_amount_paise)
  on conflict (event_id) do nothing;

  get diagnostics v_inserted = row_count;

  if v_inserted = 0 then
    return query select true, 'duplicate', null::text, null::integer;
    return;
  end if;

  if p_event_type in ('payment.captured', 'order.paid') then
    begin
      select * into v_result
      from public.confirm_booking_payment(p_razorpay_order_id, p_razorpay_payment_id, p_amount_paise);

      v_outcome := case when v_result.already_confirmed then 'already_confirmed' else 'confirmed' end;
      v_reference := v_result.booking_reference;
      v_passes := v_result.passes_issued;
    exception
      when sqlstate 'PC001' then
        -- An order we do not know about (another system, or a test delivery).
        v_outcome := 'ignored';
      when sqlstate 'PC005' then
        -- `order.paid` carries no payment id; the paired payment.captured event
        -- confirms the booking, so this delivery is recorded and ignored.
        v_outcome := 'ignored';
    end;
  elsif p_event_type = 'payment.failed' then
    v_outcome := public.fail_booking_payment(p_razorpay_order_id, p_razorpay_payment_id);
  elsif p_event_type in ('refund.processed', 'payment.refunded') then
    v_outcome := public.refund_booking_payment(p_razorpay_payment_id);
  end if;

  update public.payment_events pe
  set outcome = v_outcome, processed_at = now()
  where pe.event_id = p_event_id;

  return query select false, v_outcome, v_reference, v_passes;
end;
$$;

comment on function public.apply_razorpay_event(text, text, text, text, integer) is
  'Handles one webhook delivery: claims it (unique event id), dispatches captured/paid, failed and refund events, and records the outcome. Service role only.';

-- ---------------------------------------------------------------------------
-- 8. Customer-facing status lookup (by unguessable token)
-- ---------------------------------------------------------------------------
create or replace function public.get_booking_status(p_public_token uuid)
returns table (
  booking_reference text,
  booking_status   text,
  payment_status   text,
  quantity         integer,
  number_of_people integer,
  total_amount     integer,
  currency         text,
  event_name       text,
  event_date       date,
  start_time       time,
  end_time         time,
  venue_name       text,
  city             text,
  pass_name        text,
  pass_composition text,
  passes_issued    integer,
  created_at       timestamptz
)
language sql
stable
security definer
set search_path = public
as $$
  select
    b.booking_id,
    b.booking_status,
    b.payment_status,
    b.quantity,
    b.number_of_people,
    b.total_amount,
    e.currency,
    e.name,
    d.event_date,
    d.start_time,
    d.end_time,
    e.venue_name,
    e.city,
    p.name,
    p.composition,
    (select count(*)::integer from public.digital_passes dp where dp.booking_id = b.id),
    b.created_at
  from public.bookings b
  join public.event_dates d on d.id = b.event_date_id
  join public.pass_categories p on p.id = b.pass_category_id
  join public.events e on e.id = d.event_id
  where b.public_token = p_public_token;
$$;

comment on function public.get_booking_status(uuid) is
  'Returns one booking by its random public token for the customer''s own payment status. Deliberately contains no name, mobile or email.';

-- ---------------------------------------------------------------------------
-- 9. Privileges: every function above is service-role only
-- ---------------------------------------------------------------------------
revoke all on function public.attach_razorpay_order(uuid, text) from public, anon, authenticated;
revoke all on function public.confirm_booking_payment(text, text, integer) from public, anon, authenticated;
revoke all on function public.fail_booking_payment(text, text) from public, anon, authenticated;
revoke all on function public.refund_booking_payment(text) from public, anon, authenticated;
revoke all on function public.apply_razorpay_event(text, text, text, text, integer) from public, anon, authenticated;
revoke all on function public.get_booking_status(uuid) from public, anon, authenticated;

grant execute on function public.attach_razorpay_order(uuid, text) to service_role;
grant execute on function public.confirm_booking_payment(text, text, integer) to service_role;
grant execute on function public.fail_booking_payment(text, text) to service_role;
grant execute on function public.refund_booking_payment(text) to service_role;
grant execute on function public.apply_razorpay_event(text, text, text, text, integer) to service_role;
grant execute on function public.get_booking_status(uuid) to service_role;


-- ===========================================================================
-- 20260922090600_digital_pass.sql
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- 20260922090600_digital_pass.sql
--
-- Digital passes: a stable slot per pass, and the two read paths the website
-- needs to show one.
--
-- Passes are already issued exactly once, inside confirm_booking_payment(), at
-- the moment a payment is verified — nothing in the browser can create one, and
-- re-running the confirmation returns early without touching the table. This
-- migration makes that guarantee structural as well:
--
--   * digital_passes.pass_number numbers the passes of a booking (1..quantity);
--   * a unique index on (booking_id, pass_number) means the same slot can never
--     be filled twice, whatever a future code path does.
--
-- It also adds the two read functions the pages use. Both are service_role only:
-- the browser is never allowed to ask for a pass, it can only open a page that
-- asks the server for it.
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 1. One slot per pass
-- ---------------------------------------------------------------------------
alter table public.digital_passes
  add column if not exists pass_number integer;

-- Backfill for any pass issued before this migration: within a booking, order by
-- creation (then id, so the result is deterministic), and number them 1..n.
with numbered as (
  select id,
         row_number() over (partition by booking_id order by created_at, id) as slot
  from public.digital_passes
)
update public.digital_passes dp
set pass_number = numbered.slot
from numbered
where dp.id = numbered.id
  and dp.pass_number is distinct from numbered.slot;

alter table public.digital_passes
  alter column pass_number set not null;

alter table public.digital_passes
  drop constraint if exists digital_passes_pass_number_check;

alter table public.digital_passes
  add constraint digital_passes_pass_number_check check (pass_number >= 1);

comment on column public.digital_passes.pass_number is
  'Slot of this pass within its booking: 1..quantity. Unique per booking, so a booking can never end up with two pass 1s.';

-- The guarantee, in the database rather than in a code path.
create unique index if not exists digital_passes_booking_pass_number_idx
  on public.digital_passes (booking_id, pass_number);

-- ---------------------------------------------------------------------------
-- 2. Issue passes with their slot (same behaviour, one added column)
--
-- Recreated only so the insert can fill pass_number from the series that already
-- creates one row per purchased pass. Every rule from the previous definition is
-- unchanged: amount check, payment-reuse check, idempotent replay, capacity note.
-- ---------------------------------------------------------------------------
create or replace function public.confirm_booking_payment(
  p_razorpay_order_id  text,
  p_razorpay_payment_id text,
  p_amount_paise       integer default null
)
returns table (
  booking_uuid     uuid,
  booking_reference text,
  public_token     uuid,
  booking_status   text,
  payment_status   text,
  quantity         integer,
  number_of_people integer,
  subtotal         integer,
  total_amount     integer,
  event_id         uuid,
  event_date       date,
  start_time       time,
  end_time         time,
  pass_name        text,
  pass_composition text,
  currency         text,
  passes_issued    integer,
  already_confirmed boolean,
  capacity_note    text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking  record;
  v_holder   uuid;
  v_booked   integer;
  v_capacity integer;
  v_note     text;
begin
  select b.* into v_booking
  from public.bookings b
  where b.razorpay_order_id = p_razorpay_order_id
  for update;

  if not found then
    raise exception 'order_not_found' using errcode = 'PC001';
  end if;

  -- The amount must be what the database says the booking costs. A ₹1 payment
  -- cannot confirm a ₹998 booking.
  if p_amount_paise is not null and p_amount_paise <> v_booking.total_amount * 100 then
    raise exception 'amount_mismatch' using errcode = 'PC002';
  end if;

  -- One payment can only ever belong to one booking.
  select b.id into v_holder
  from public.bookings b
  where b.razorpay_payment_id = p_razorpay_payment_id
    and b.id <> v_booking.id;

  if found then
    raise exception 'payment_already_used' using errcode = 'PC003';
  end if;

  -- Already paid: a duplicate callback gets the same answer, and nothing is
  -- written again (no second set of passes).
  if v_booking.payment_status = 'paid' then
    return query
      select b.id, b.booking_id, b.public_token, b.booking_status, b.payment_status, b.quantity,
             b.number_of_people, b.subtotal, b.total_amount, d.event_id, d.event_date,
             d.start_time, d.end_time, p.name, p.composition, e.currency,
             (select count(*)::integer from public.digital_passes dp where dp.booking_id = b.id),
             true, b.notes
      from public.bookings b
      join public.event_dates d on d.id = b.event_date_id
      join public.pass_categories p on p.id = b.pass_category_id
      join public.events e on e.id = d.event_id
      where b.id = v_booking.id;

    return;
  end if;

  -- From here on the booking is being paid for the first time, so a payment id is
  -- mandatory: an event without one (`order.paid` on its own) is ignored by the
  -- dispatcher and the `payment.captured` delivery does the work instead.
  if p_razorpay_payment_id is null or length(btrim(p_razorpay_payment_id)) = 0 then
    raise exception 'payment_id_required' using errcode = 'PC005';
  end if;

  -- Capacity is checked again, but the customer has already paid: the booking is
  -- confirmed either way and an organiser flag is recorded instead of silently
  -- dropping a paid booking.
  select coalesce(sum(b.number_of_people) filter (where b.payment_status = 'paid'), 0)::integer
    into v_booked
  from public.bookings b
  where b.event_date_id = v_booking.event_date_id
    and b.id <> v_booking.id;

  select d.capacity into v_capacity
  from public.event_dates d
  where d.id = v_booking.event_date_id;

  if v_booked + v_booking.number_of_people > v_capacity then
    v_note := 'capacity exceeded when payment was confirmed — needs organiser review';
  end if;

  update public.bookings b
  set payment_status   = 'paid',
      booking_status   = 'confirmed',
      razorpay_payment_id = p_razorpay_payment_id,
      notes            = coalesce(v_note, b.notes)
  where b.id = v_booking.id;

  -- One scannable pass per purchased pass, issued only now that payment is
  -- verified. Guarded three ways: the replay above returns early, the not-exists
  -- check skips a booking that already has passes, and the unique
  -- (booking_id, pass_number) index makes a duplicate slot impossible.
  insert into public.digital_passes (booking_id, valid_date, pass_number, status)
  select v_booking.id, d.event_date, s.slot, 'active'
  from public.event_dates d
  cross join generate_series(1, v_booking.quantity) as s(slot)
  where d.id = v_booking.event_date_id
    and not exists (select 1 from public.digital_passes dp where dp.booking_id = v_booking.id)
  on conflict (booking_id, pass_number) do nothing;

  return query
    select b.id, b.booking_id, b.public_token, b.booking_status, b.payment_status, b.quantity,
           b.number_of_people, b.subtotal, b.total_amount, d.event_id, d.event_date,
           d.start_time, d.end_time, p.name, p.composition, e.currency,
           (select count(*)::integer from public.digital_passes dp where dp.booking_id = b.id),
           false, b.notes
    from public.bookings b
    join public.event_dates d on d.id = b.event_date_id
    join public.pass_categories p on p.id = b.pass_category_id
    join public.events e on e.id = d.event_id
    where b.id = v_booking.id;
end;
$$;

comment on function public.confirm_booking_payment(text, text, integer) is
  'Marks a booking paid + confirmed after a server-verified payment, issues one digital pass per purchased pass, and is idempotent: a repeated call returns the same booking without writing anything.';

-- ---------------------------------------------------------------------------
-- 3. The passes of one booking, for the customer's own success page
--
-- Called with the booking's random public_token, so it needs no session: the
-- token is the credential. Returns pass rows only — the page already has the
-- booking's own details — and never a mobile number or an email address.
-- ---------------------------------------------------------------------------
create or replace function public.get_booking_passes(p_public_token uuid)
returns table (
  pass_id       text,
  qr_token      text,
  pass_status   text,
  checked_in    boolean,
  checked_in_at timestamptz,
  valid_date    date,
  issued_at     timestamptz,
  pass_number   integer,
  pass_total    integer
)
language sql
stable
security definer
set search_path = public
as $$
  select
    dp.pass_id,
    dp.qr_token,
    dp.status,
    dp.checked_in,
    dp.checked_in_at,
    dp.valid_date,
    dp.created_at,
    dp.pass_number,
    (select count(*)::integer from public.digital_passes all_passes where all_passes.booking_id = b.id)
  from public.bookings b
  join public.digital_passes dp on dp.booking_id = b.id
  where b.public_token = p_public_token
  order by dp.pass_number;
$$;

comment on function public.get_booking_passes(uuid) is
  'Every pass of one booking, found by the booking''s random public token. Service role only; contains no mobile number or email address.';

-- ---------------------------------------------------------------------------
-- 4. One pass by its QR token — what the QR code points at
--
-- The QR encodes https://<site>/verify/<qr_token>. The token is 64 random hex
-- characters and is the only credential needed: no booking reference, no mobile
-- number and no customer id is in the QR, so a screenshot of a pass reveals
-- nothing that the pass does not already show.
-- ---------------------------------------------------------------------------
create or replace function public.get_pass_by_token(p_qr_token text)
returns table (
  pass_id          text,
  qr_token         text,
  pass_status      text,
  checked_in       boolean,
  checked_in_at    timestamptz,
  valid_date       date,
  issued_at        timestamptz,
  pass_number      integer,
  pass_total       integer,
  booking_reference text,
  booking_status   text,
  payment_status   text,
  customer_name    text,
  quantity         integer,
  total_amount     integer,
  currency         text,
  event_name       text,
  event_date       date,
  start_time       time,
  end_time         time,
  venue_name       text,
  venue_address    text,
  city             text,
  pass_name        text,
  pass_composition text
)
language sql
stable
security definer
set search_path = public
as $$
  select
    dp.pass_id,
    dp.qr_token,
    dp.status,
    dp.checked_in,
    dp.checked_in_at,
    dp.valid_date,
    dp.created_at,
    dp.pass_number,
    (select count(*)::integer from public.digital_passes all_passes where all_passes.booking_id = b.id),
    b.booking_id,
    b.booking_status,
    b.payment_status,
    b.customer_name,
    b.quantity,
    b.total_amount,
    e.currency,
    e.name,
    d.event_date,
    d.start_time,
    d.end_time,
    e.venue_name,
    e.venue_address,
    e.city,
    p.name,
    p.composition
  from public.digital_passes dp
  join public.bookings b on b.id = dp.booking_id
  join public.event_dates d on d.id = b.event_date_id
  join public.pass_categories p on p.id = b.pass_category_id
  join public.events e on e.id = d.event_id
  where dp.qr_token = p_qr_token;
$$;

comment on function public.get_pass_by_token(text) is
  'Resolves one digital pass from the token inside its QR code: the ticket and the gate verification page both use it. Service role only; contains no mobile number or email address.';

-- ---------------------------------------------------------------------------
-- 5. Privileges: the two read functions are service_role only
--
-- A pass is personal. The browser never queries these directly — the server
-- renders the page after checking that the caller holds the right token.
-- ---------------------------------------------------------------------------
revoke all on function public.get_booking_passes(uuid) from public, anon, authenticated;
revoke all on function public.get_pass_by_token(text) from public, anon, authenticated;

grant execute on function public.get_booking_passes(uuid) to service_role;
grant execute on function public.get_pass_by_token(text) to service_role;


-- ===========================================================================
-- 20260922090700_check_in.sql
-- ===========================================================================

-- =============================================================================
-- 20260922090700_check_in.sql
--
-- Gate entry: turning a scanned QR code into an admitted guest.
--
-- Everything that decides "may this person come in" happens here, in one
-- transaction, because the client is not trusted with any part of it:
--
--   * the token must be the 64-character shape the database itself mints;
--   * the pass, the booking, the night and the event must all exist (a single
--     inner join — a pass with no booking cannot be half-valid);
--   * the booking must be confirmed and paid, the pass active and unused, and the
--     pass must be for the night the gate is open (p_gate_date, computed by the
--     server from the venue's timezone, never sent by a browser);
--   * the person scanning must be an active staff member, checked against
--     admin_users inside the database — so a bug in the API layer alone can never
--     admit somebody;
--   * the write is a compare-and-swap (`where checked_in = false and status =
--     'active'`) after `for update` on the pass row, and check_ins has a unique
--     constraint on digital_pass_id. Two scanners pointed at the same code
--     therefore produce exactly one entry and one check_ins row, and the second
--     one is told the pass is already used.
--
-- `scan_pass` is the same verdict without writing: the scanner shows it, and the
-- CHECK IN button asks for the real thing.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- The implementation. Not callable by any role: the two wrappers below are the
-- only entry points, and they run it as the definer.
-- -----------------------------------------------------------------------------
create or replace function public.pass_entry(
  p_qr_token      text,
  p_gate_date     date,
  p_staff_user_id uuid,
  p_commit        boolean,
  p_gate          text default null
)
returns table (
  outcome           text,
  reason            text,
  pass_id           text,
  pass_status       text,
  checked_in        boolean,
  checked_in_at     timestamptz,
  pass_number       integer,
  pass_total        integer,
  customer_name     text,
  pass_name         text,
  pass_composition  text,
  booking_reference text,
  booking_status    text,
  payment_status    text,
  event_name        text,
  event_date        date,
  start_time        time,
  end_time          time,
  venue_name        text,
  venue_address     text,
  city              text,
  gate_date         date,
  staff_name        text,
  check_in_id       uuid
)
language plpgsql
security definer
set search_path = public
as $$
declare
  -- Scalars, not a record: the staff lookup is skipped entirely when no id is given,
  -- and an unassigned record cannot be tested for "not found".
  v_staff_id   uuid;
  v_staff_name text;
  v_pass    record;
  v_total   integer;
  v_updated integer;
  v_log_id  uuid;
begin
  -- 0. Who is holding the scanner? Check-in is a staff action, and the staff
  --    member is recorded on the check-in row.
  if p_staff_user_id is not null then
    select a.id, coalesce(nullif(btrim(a.full_name), ''), a.email)
      into v_staff_id, v_staff_name
    from public.admin_users a
    where a.user_id = p_staff_user_id
      and a.is_active
      and a.role in ('owner', 'admin', 'manager', 'scanner')
    limit 1;
  end if;

  if v_staff_id is null then
    return query select
      'not_authorised'::text,
      'Sign in as event staff to scan passes.'::text,
      null::text, null::text, null::boolean, null::timestamptz,
      null::integer, null::integer, null::text, null::text, null::text,
      null::text, null::text, null::text, null::text, null::date,
      null::time, null::time, null::text, null::text, null::text,
      p_gate_date, null::text, null::uuid;

    return;
  end if;

  -- 1. The shape first: a token that is not 64 hex characters cannot exist, so the
  --    lookup is skipped entirely (and a 1 MB "token" never reaches a query).
  if p_qr_token is null or p_qr_token !~ '^[0-9a-f]{64}$' then
    return query select
      'invalid'::text,
      'That code is not a pass for this event.'::text,
      null::text, null::text, null::boolean, null::timestamptz,
      null::integer, null::integer, null::text, null::text, null::text,
      null::text, null::text, null::text, null::text, null::date,
      null::time, null::time, null::text, null::text, null::text,
      p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  -- 2. Pass, booking, night and event, in one read. `for update of dp` locks the
  --    pass row: a second scanner waits here and then sees the committed result,
  --    which is what makes the compare-and-swap below impossible to lose.
  select dp.id,
         dp.pass_id,
         dp.status,
         dp.checked_in,
         dp.checked_in_at,
         dp.valid_date,
         b.event_date_id,
         dp.pass_number,
         b.booking_id as booking_reference,
         b.booking_status,
         b.payment_status,
         b.customer_name,
         pc.name as pass_name,
         pc.composition as pass_composition,
         e.name as event_name,
         e.venue_name,
         e.venue_address,
         e.city,
         e.status as event_status,
         d.status as night_status,
         d.start_time,
         d.end_time
    into v_pass
  from public.digital_passes dp
  join public.bookings b on b.id = dp.booking_id
  join public.event_dates d on d.id = b.event_date_id
  join public.events e on e.id = d.event_id
  join public.pass_categories pc on pc.id = b.pass_category_id
  where dp.qr_token = p_qr_token
  for update of dp;

  if not found then
    return query select
      'invalid'::text,
      'That code does not match any pass for this event.'::text,
      null::text, null::text, null::boolean, null::timestamptz,
      null::integer, null::integer, null::text, null::text, null::text,
      null::text, null::text, null::text, null::text, null::date,
      null::time, null::time, null::text, null::text, null::text,
      p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  select count(*)::integer
    into v_total
  from public.digital_passes dp
  where dp.booking_id = (select b.id from public.bookings b where b.booking_id = v_pass.booking_reference);

  -- 3. Verdict, worst first. Every branch returns the pass details it has, so the
  --    scanner can show who is standing there even when the answer is no.
  if v_pass.night_status = 'cancelled' or v_pass.event_status <> 'published' then
    return query select 'invalid'::text, 'That night is not taking place.'::text,
      v_pass.pass_id, v_pass.status, v_pass.checked_in, v_pass.checked_in_at,
      v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
      v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
      v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
      v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  if v_pass.status = 'cancelled'
     or v_pass.booking_status in ('refunded', 'cancelled')
     or v_pass.payment_status = 'refunded' then
    return query select 'refunded'::text, 'The booking behind this pass was cancelled or refunded.'::text,
      v_pass.pass_id, v_pass.status, v_pass.checked_in, v_pass.checked_in_at,
      v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
      v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
      v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
      v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  if v_pass.booking_status <> 'confirmed' or v_pass.payment_status <> 'paid' then
    return query select 'payment_not_verified'::text, 'No verified payment is recorded for this booking.'::text,
      v_pass.pass_id, v_pass.status, v_pass.checked_in, v_pass.checked_in_at,
      v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
      v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
      v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
      v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  if v_pass.checked_in or v_pass.status = 'used' then
    return query select 'already_used'::text, 'This pass was already scanned at the gate.'::text,
      v_pass.pass_id, v_pass.status, v_pass.checked_in, v_pass.checked_in_at,
      v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
      v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
      v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
      v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  if v_pass.status = 'expired' or v_pass.valid_date < p_gate_date then
    return query select 'expired'::text, 'This pass was for an earlier night.'::text,
      v_pass.pass_id, v_pass.status, v_pass.checked_in, v_pass.checked_in_at,
      v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
      v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
      v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
      v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  if v_pass.valid_date > p_gate_date then
    return query select 'not_yet_valid'::text, 'This pass is for a later night.'::text,
      v_pass.pass_id, v_pass.status, v_pass.checked_in, v_pass.checked_in_at,
      v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
      v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
      v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
      v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  if v_pass.status <> 'active' then
    return query select 'invalid'::text, 'This pass is no longer usable.'::text,
      v_pass.pass_id, v_pass.status, v_pass.checked_in, v_pass.checked_in_at,
      v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
      v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
      v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
      v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  -- 4. The guest may come in.
  if not p_commit then
    -- Preview only: the scanner shows this, and the button asks for the real thing.
    return query select 'valid'::text, null::text,
      v_pass.pass_id, v_pass.status, v_pass.checked_in, v_pass.checked_in_at,
      v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
      v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
      v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
      v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  -- Compare-and-swap: the row only flips if it is still unused and active. The
  -- `for update` above already serialises competing scanners; this makes the
  -- guarantee independent of lock timing, and a losing caller is told the truth
  -- instead of overwriting the first scan's timestamp.
  update public.digital_passes dp
  set checked_in = true,
      checked_in_at = now(),
      status = 'used'
  where dp.id = v_pass.id
    and dp.checked_in = false
    and dp.status = 'active';

  get diagnostics v_updated = row_count;

  if v_updated = 0 then
    return query select 'already_used'::text, 'This pass was already scanned at the gate.'::text,
      v_pass.pass_id, v_pass.status, true, v_pass.checked_in_at,
      v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
      v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
      v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
      v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  -- The audit row. `on conflict do nothing` means the unique constraint on
  -- digital_pass_id ends a race with a duplicate entry rather than an error, and
  -- `notes` keeps which gate (or device label) scanned the pass.
  insert into public.check_ins (digital_pass_id, event_date_id, gate, checked_in_by, notes)
  values (
    v_pass.id,
    v_pass.event_date_id,
    nullif(btrim(coalesce(p_gate, '')), ''),
    v_staff_id,
    'web scanner'
  )
  on conflict (digital_pass_id) do nothing
  returning id into v_log_id;

  return query select 'checked_in'::text, null::text,
    v_pass.pass_id, 'used'::text, true, now(),
    v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
    v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
    v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
    v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, v_log_id;
end;
$$;

comment on function public.pass_entry(text, date, uuid, boolean, text) is
  'Internal: the single implementation of the gate verdict. Call scan_pass to preview or check_in_pass to admit.';

-- -----------------------------------------------------------------------------
-- The two entry points.
-- -----------------------------------------------------------------------------
create or replace function public.scan_pass(
  p_qr_token      text,
  p_gate_date     date,
  p_staff_user_id uuid
)
returns table (
  outcome           text,
  reason            text,
  pass_id           text,
  pass_status       text,
  checked_in        boolean,
  checked_in_at     timestamptz,
  pass_number       integer,
  pass_total        integer,
  customer_name     text,
  pass_name         text,
  pass_composition  text,
  booking_reference text,
  booking_status    text,
  payment_status    text,
  event_name        text,
  event_date        date,
  start_time        time,
  end_time          time,
  venue_name        text,
  venue_address     text,
  city              text,
  gate_date         date,
  staff_name        text,
  check_in_id       uuid
)
language sql
security definer
set search_path = public
as $$
  select * from public.pass_entry(p_qr_token, p_gate_date, p_staff_user_id, false, null);
$$;

comment on function public.scan_pass(text, date, uuid) is
  'Gate verdict for one QR token, without writing anything. service_role only; the staff id is verified inside.';

create or replace function public.check_in_pass(
  p_qr_token      text,
  p_gate_date     date,
  p_staff_user_id uuid,
  p_gate          text default null
)
returns table (
  outcome           text,
  reason            text,
  pass_id           text,
  pass_status       text,
  checked_in        boolean,
  checked_in_at     timestamptz,
  pass_number       integer,
  pass_total        integer,
  customer_name     text,
  pass_name         text,
  pass_composition  text,
  booking_reference text,
  booking_status    text,
  payment_status    text,
  event_name        text,
  event_date        date,
  start_time        time,
  end_time          time,
  venue_name        text,
  venue_address     text,
  city              text,
  gate_date         date,
  staff_name        text,
  check_in_id       uuid
)
language sql
security definer
set search_path = public
as $$
  select * from public.pass_entry(p_qr_token, p_gate_date, p_staff_user_id, true, p_gate);
$$;

comment on function public.check_in_pass(text, date, uuid, text) is
  'Admits one guest: marks the pass used and writes one check_ins row, exactly once per pass. service_role only.';

-- -----------------------------------------------------------------------------
-- Grants: nothing here is reachable from a browser key. The staff session is
-- resolved by the server (src/lib/auth), and the staff id it passes is re-checked
-- against admin_users inside pass_entry.
-- -----------------------------------------------------------------------------
revoke all on function public.pass_entry(text, date, uuid, boolean, text)
  from public, anon, authenticated, service_role;
revoke all on function public.scan_pass(text, date, uuid) from public, anon, authenticated;
revoke all on function public.check_in_pass(text, date, uuid, text) from public, anon, authenticated;

grant execute on function public.scan_pass(text, date, uuid) to service_role;
grant execute on function public.check_in_pass(text, date, uuid, text) to service_role;


-- ===========================================================================
-- 20260922090800_admin_roles.sql
-- ===========================================================================

-- =============================================================================
-- 20260922090800_admin_roles.sql
--
-- Step 8 — admin authentication and role-based access control.
--
-- The allow-list gains a three-role model, and this migration is what makes those
-- three roles mean something *inside the database*, not just in the app:
--
--   super_admin  full access, including staff/role management
--   admin        bookings, payments, passes, dates, gallery, scanner, settings
--   staff        the scanner, check-ins, and a limited booking lookup
--
-- Three things change:
--
--   1. `admin_users.role` accepts exactly those three values. The old four
--      (owner / admin / manager / scanner) are mapped across first, in the same
--      migration, so no row is ever in a value the constraint would reject.
--   2. The role helpers are redefined: `is_staff()` is any active role, the new
--      `is_super_admin()` is the full-access role, and `is_admin()` is the
--      management role (super_admin or admin). Every RLS policy that used to ask
--      "is this an owner?" now asks "is this a super admin?".
--   3. Two service-role functions the admin area needs, so that the app never
--      counts or filters rows in the browser: `admin_lookup_bookings()` (with the
--      contact fields withheld when the caller may not see them) and
--      `admin_dashboard_stats()`.
--
-- The gate verdict in `pass_entry()` is re-created with the new role list — same
-- body, one line changed.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. owner → super_admin, manager → admin, scanner → staff.
--    The data moves before the constraint does, in one transaction, so the table
--    is never in a state that violates its own rules.
-- -----------------------------------------------------------------------------
alter table public.admin_users drop constraint if exists admin_users_role_check;

update public.admin_users
   set role = case role
                when 'owner'   then 'super_admin'
                when 'manager' then 'admin'
                when 'scanner' then 'staff'
                else role
              end
 where role in ('owner', 'manager', 'scanner');

-- Anything that was neither a known legacy value nor a known new one would now be
-- an invalid row; fail loudly here rather than at the constraint below, so the
-- message says which rows are wrong.
do $$
declare
  v_bad text;
begin
  select string_agg(distinct role, ', ') into v_bad
  from public.admin_users
  where role not in ('super_admin', 'admin', 'staff');

  if v_bad is not null then
    raise exception 'admin_users holds unrecognised roles after migration: %', v_bad;
  end if;
end;
$$;

alter table public.admin_users
  add constraint admin_users_role_check check (role in ('super_admin', 'admin', 'staff'));

alter table public.admin_users alter column role set default 'staff';

comment on column public.admin_users.role is
  'super_admin = full access (including staff/role management); admin = bookings, payments, passes, dates, gallery, scanner, settings; staff = scanner, check-ins and a limited booking lookup.';

-- -----------------------------------------------------------------------------
-- 2. Role helpers. SECURITY DEFINER for the same reason as before: a check against
--    admin_users must not recurse through that table's own policies.
-- -----------------------------------------------------------------------------
create or replace function public.is_staff(p_user_id uuid default auth.uid())
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
      from public.admin_users
     where user_id = p_user_id
       and is_active
       and role in ('super_admin', 'admin', 'staff')
  );
$$;

comment on function public.is_staff(uuid) is
  'True when the given user is an active admin_users row of any role (super_admin, admin or staff).';

create or replace function public.is_admin(p_user_id uuid default auth.uid())
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
      from public.admin_users
     where user_id = p_user_id
       and is_active
       and role in ('super_admin', 'admin')
  );
$$;

comment on function public.is_admin(uuid) is
  'True for super_admin and admin — the roles that may manage events, bookings and passes. Staff are excluded.';

create or replace function public.is_super_admin(p_user_id uuid default auth.uid())
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
      from public.admin_users
     where user_id = p_user_id
       and is_active
       and role = 'super_admin'
  );
$$;

comment on function public.is_super_admin(uuid) is
  'True only for the super_admin role — the only role allowed to manage admin_users rows.';

revoke execute on function public.is_staff(uuid) from public;
revoke execute on function public.is_admin(uuid) from public;
revoke execute on function public.is_super_admin(uuid) from public;
grant execute on function public.is_staff(uuid), public.is_admin(uuid), public.is_super_admin(uuid)
  to anon, authenticated, service_role;

-- The old owner-only name is gone rather than quietly redefined: two names for one
-- question is how a policy ends up asking the wrong one. The policy below is the
-- only thing that used it.
drop policy if exists admin_users_owner_manage on public.admin_users;
drop function if exists public.is_owner(uuid);

drop policy if exists admin_users_super_admin_manage on public.admin_users;
create policy admin_users_super_admin_manage on public.admin_users
  for all
  to authenticated
  using (public.is_super_admin())
  with check (public.is_super_admin());

-- Who is asking? The caller's own role, or null.
--
-- This exists for the edge: `src/proxy.ts` runs before a page is rendered and has to
-- answer "may this person open this section?" *before* anything streams, because a
-- redirect issued while a response is already streaming cannot change its status code.
-- It returns one word — never a row, never anybody else's role — and it is safe for
-- `anon` to call: there is no auth user, so the answer is simply null.
create or replace function public.current_staff_role()
returns text
language sql
stable
security definer
set search_path = public
as $$
  select role
    from public.admin_users
   where user_id = auth.uid()
     and is_active
   limit 1;
$$;

comment on function public.current_staff_role() is
  'The caller''s own admin_users role, or null. Used by the request hook to decide access before a response starts streaming.';

revoke execute on function public.current_staff_role() from public;
grant execute on function public.current_staff_role() to anon, authenticated, service_role;

-- -----------------------------------------------------------------------------
-- 3. The gate verdict, re-created with the new roles.
--    (An active row of any of the three roles may work the gate — a super admin
--    standing on the door is still a person who can check a pass in.)
-- -----------------------------------------------------------------------------
-- Re-created verbatim from 20260922090700_check_in.sql, with one change: the role
-- list now uses the three-role model. Everything else — the lock, the verdict
-- order, the compare-and-swap, the audit row — is byte-for-byte the same.
create or replace function public.pass_entry(
  p_qr_token      text,
  p_gate_date     date,
  p_staff_user_id uuid,
  p_commit        boolean,
  p_gate          text default null
)
returns table (
  outcome           text,
  reason            text,
  pass_id           text,
  pass_status       text,
  checked_in        boolean,
  checked_in_at     timestamptz,
  pass_number       integer,
  pass_total        integer,
  customer_name     text,
  pass_name         text,
  pass_composition  text,
  booking_reference text,
  booking_status    text,
  payment_status    text,
  event_name        text,
  event_date        date,
  start_time        time,
  end_time          time,
  venue_name        text,
  venue_address     text,
  city              text,
  gate_date         date,
  staff_name        text,
  check_in_id       uuid
)
language plpgsql
security definer
set search_path = public
as $$
declare
  -- Scalars, not a record: the staff lookup is skipped entirely when no id is given,
  -- and an unassigned record cannot be tested for "not found".
  v_staff_id   uuid;
  v_staff_name text;
  v_pass    record;
  v_total   integer;
  v_updated integer;
  v_log_id  uuid;
begin
  -- 0. Who is holding the scanner? Check-in is a staff action, and the staff
  --    member is recorded on the check-in row.
  if p_staff_user_id is not null then
    select a.id, coalesce(nullif(btrim(a.full_name), ''), a.email)
      into v_staff_id, v_staff_name
    from public.admin_users a
    where a.user_id = p_staff_user_id
      and a.is_active
      and a.role in ('super_admin', 'admin', 'staff')
    limit 1;
  end if;

  if v_staff_id is null then
    return query select
      'not_authorised'::text,
      'Sign in as event staff to scan passes.'::text,
      null::text, null::text, null::boolean, null::timestamptz,
      null::integer, null::integer, null::text, null::text, null::text,
      null::text, null::text, null::text, null::text, null::date,
      null::time, null::time, null::text, null::text, null::text,
      p_gate_date, null::text, null::uuid;

    return;
  end if;

  -- 1. The shape first: a token that is not 64 hex characters cannot exist, so the
  --    lookup is skipped entirely (and a 1 MB "token" never reaches a query).
  if p_qr_token is null or p_qr_token !~ '^[0-9a-f]{64}$' then
    return query select
      'invalid'::text,
      'That code is not a pass for this event.'::text,
      null::text, null::text, null::boolean, null::timestamptz,
      null::integer, null::integer, null::text, null::text, null::text,
      null::text, null::text, null::text, null::text, null::date,
      null::time, null::time, null::text, null::text, null::text,
      p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  -- 2. Pass, booking, night and event, in one read. `for update of dp` locks the
  --    pass row: a second scanner waits here and then sees the committed result,
  --    which is what makes the compare-and-swap below impossible to lose.
  select dp.id,
         dp.pass_id,
         dp.status,
         dp.checked_in,
         dp.checked_in_at,
         dp.valid_date,
         b.event_date_id,
         dp.pass_number,
         b.booking_id as booking_reference,
         b.booking_status,
         b.payment_status,
         b.customer_name,
         pc.name as pass_name,
         pc.composition as pass_composition,
         e.name as event_name,
         e.venue_name,
         e.venue_address,
         e.city,
         e.status as event_status,
         d.status as night_status,
         d.start_time,
         d.end_time
    into v_pass
  from public.digital_passes dp
  join public.bookings b on b.id = dp.booking_id
  join public.event_dates d on d.id = b.event_date_id
  join public.events e on e.id = d.event_id
  join public.pass_categories pc on pc.id = b.pass_category_id
  where dp.qr_token = p_qr_token
  for update of dp;

  if not found then
    return query select
      'invalid'::text,
      'That code does not match any pass for this event.'::text,
      null::text, null::text, null::boolean, null::timestamptz,
      null::integer, null::integer, null::text, null::text, null::text,
      null::text, null::text, null::text, null::text, null::date,
      null::time, null::time, null::text, null::text, null::text,
      p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  select count(*)::integer
    into v_total
  from public.digital_passes dp
  where dp.booking_id = (select b.id from public.bookings b where b.booking_id = v_pass.booking_reference);

  -- 3. Verdict, worst first. Every branch returns the pass details it has, so the
  --    scanner can show who is standing there even when the answer is no.
  if v_pass.night_status = 'cancelled' or v_pass.event_status <> 'published' then
    return query select 'invalid'::text, 'That night is not taking place.'::text,
      v_pass.pass_id, v_pass.status, v_pass.checked_in, v_pass.checked_in_at,
      v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
      v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
      v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
      v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  if v_pass.status = 'cancelled'
     or v_pass.booking_status in ('refunded', 'cancelled')
     or v_pass.payment_status = 'refunded' then
    return query select 'refunded'::text, 'The booking behind this pass was cancelled or refunded.'::text,
      v_pass.pass_id, v_pass.status, v_pass.checked_in, v_pass.checked_in_at,
      v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
      v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
      v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
      v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  if v_pass.booking_status <> 'confirmed' or v_pass.payment_status <> 'paid' then
    return query select 'payment_not_verified'::text, 'No verified payment is recorded for this booking.'::text,
      v_pass.pass_id, v_pass.status, v_pass.checked_in, v_pass.checked_in_at,
      v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
      v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
      v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
      v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  if v_pass.checked_in or v_pass.status = 'used' then
    return query select 'already_used'::text, 'This pass was already scanned at the gate.'::text,
      v_pass.pass_id, v_pass.status, v_pass.checked_in, v_pass.checked_in_at,
      v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
      v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
      v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
      v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  if v_pass.status = 'expired' or v_pass.valid_date < p_gate_date then
    return query select 'expired'::text, 'This pass was for an earlier night.'::text,
      v_pass.pass_id, v_pass.status, v_pass.checked_in, v_pass.checked_in_at,
      v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
      v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
      v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
      v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  if v_pass.valid_date > p_gate_date then
    return query select 'not_yet_valid'::text, 'This pass is for a later night.'::text,
      v_pass.pass_id, v_pass.status, v_pass.checked_in, v_pass.checked_in_at,
      v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
      v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
      v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
      v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  if v_pass.status <> 'active' then
    return query select 'invalid'::text, 'This pass is no longer usable.'::text,
      v_pass.pass_id, v_pass.status, v_pass.checked_in, v_pass.checked_in_at,
      v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
      v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
      v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
      v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  -- 4. The guest may come in.
  if not p_commit then
    -- Preview only: the scanner shows this, and the button asks for the real thing.
    return query select 'valid'::text, null::text,
      v_pass.pass_id, v_pass.status, v_pass.checked_in, v_pass.checked_in_at,
      v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
      v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
      v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
      v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  -- Compare-and-swap: the row only flips if it is still unused and active. The
  -- `for update` above already serialises competing scanners; this makes the
  -- guarantee independent of lock timing, and a losing caller is told the truth
  -- instead of overwriting the first scan's timestamp.
  update public.digital_passes dp
  set checked_in = true,
      checked_in_at = now(),
      status = 'used'
  where dp.id = v_pass.id
    and dp.checked_in = false
    and dp.status = 'active';

  get diagnostics v_updated = row_count;

  if v_updated = 0 then
    return query select 'already_used'::text, 'This pass was already scanned at the gate.'::text,
      v_pass.pass_id, v_pass.status, true, v_pass.checked_in_at,
      v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
      v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
      v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
      v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  -- The audit row. `on conflict do nothing` means the unique constraint on
  -- digital_pass_id ends a race with a duplicate entry rather than an error, and
  -- `notes` keeps which gate (or device label) scanned the pass.
  insert into public.check_ins (digital_pass_id, event_date_id, gate, checked_in_by, notes)
  values (
    v_pass.id,
    v_pass.event_date_id,
    nullif(btrim(coalesce(p_gate, '')), ''),
    v_staff_id,
    'web scanner'
  )
  on conflict (digital_pass_id) do nothing
  returning id into v_log_id;

  return query select 'checked_in'::text, null::text,
    v_pass.pass_id, 'used'::text, true, now(),
    v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
    v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
    v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
    v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, v_log_id;
end;
$$;

comment on function public.pass_entry(text, date, uuid, boolean, text) is
  'Internal: the single implementation of the gate verdict. Call scan_pass to preview or check_in_pass to admit.';

-- -----------------------------------------------------------------------------
-- 4. Admin lookups.
--
--    Both are service_role only: they read across bookings, passes and check-ins,
--    which no browser session may do. The app is the only caller, and it decides
--    *which* of its own staff may see the result — but the contact fields are
--    withheld here, in the same statement that reads them, so a mistake above this
--    line cannot put a customer's mobile number on a staff member's screen.
-- -----------------------------------------------------------------------------
create or replace function public.admin_lookup_bookings(
  p_query           text,
  p_include_contact boolean default true,
  p_limit           integer default 25
)
returns table (
  booking_uuid        uuid,
  booking_id          text,
  customer_name       text,
  customer_mobile     text,
  customer_email      text,
  event_name          text,
  event_slug          text,
  event_date          date,
  start_time          time,
  end_time            time,
  pass_name           text,
  pass_composition    text,
  quantity            integer,
  number_of_people    integer,
  total_amount        integer,
  currency            text,
  booking_status      text,
  payment_status      text,
  razorpay_order_id   text,
  created_at          timestamptz,
  passes_issued       integer,
  passes_checked_in   integer,
  check_in_times      timestamptz[]
)
language sql
stable
security definer
set search_path = public
as $$
  with matches as (
    select b.id
      from public.bookings b
     where p_query is not null
       and btrim(p_query) <> ''
       and (
         -- Booking reference, as printed on the confirmation: partial, case-free.
         b.booking_id ilike '%' || btrim(p_query) || '%'
         -- The guest's name, as they will say it at the door.
         or b.customer_name ilike '%' || btrim(p_query) || '%'
         -- The mobile number, however the staff member typed it (spaces, +91, a
         -- leading zero). Guarded by "the query has digits": matching an empty digit
         -- string against every number would return the whole table.
         or (
           regexp_replace(btrim(p_query), '\D', '', 'g') <> ''
           and regexp_replace(b.customer_mobile, '\D', '', 'g') like
               '%' || regexp_replace(btrim(p_query), '\D', '', 'g') || '%'
         )
       )
     order by b.created_at desc
     limit greatest(1, least(coalesce(p_limit, 25), 100))
  )
  select
    b.id,
    b.booking_id,
    b.customer_name,
    case when p_include_contact then b.customer_mobile end,
    case when p_include_contact then b.customer_email end,
    e.name,
    e.slug,
    d.event_date,
    d.start_time,
    d.end_time,
    p.name,
    p.composition,
    b.quantity,
    b.number_of_people,
    case when p_include_contact then b.total_amount end,
    e.currency,
    b.booking_status,
    b.payment_status,
    case when p_include_contact then b.razorpay_order_id end,
    b.created_at,
    coalesce(dp.issued, 0),
    coalesce(dp.checked_in, 0),
    dp.check_in_times
  from matches m
  join public.bookings b        on b.id = m.id
  join public.event_dates d     on d.id = b.event_date_id
  join public.events e          on e.id = d.event_id
  join public.pass_categories p on p.id = b.pass_category_id
  left join lateral (
    select count(*)::integer as issued,
           count(*) filter (where dp.checked_in)::integer as checked_in,
           array_remove(array_agg(dp.checked_in_at order by dp.pass_number), null) as check_in_times
      from public.digital_passes dp
     where dp.booking_id = b.id
  ) dp on true
  order by b.created_at desc;
$$;

comment on function public.admin_lookup_bookings(text, boolean, integer) is
  'Staff-side booking lookup: reference, mobile or name. Contact details, amounts and gateway ids come back null when p_include_contact is false (the limited view). service_role only.';

create or replace function public.admin_dashboard_stats(p_today date)
returns table (
  bookings_total     integer,
  bookings_paid      integer,
  bookings_pending   integer,
  bookings_refunded  integer,
  people_admitted    integer,
  passes_issued      integer,
  passes_active      integer,
  passes_used        integer,
  check_ins_today    integer,
  nights_total       integer,
  nights_upcoming    integer,
  gallery_published  integer,
  gallery_draft      integer,
  staff_active       integer,
  staff_total        integer
)
language sql
stable
security definer
set search_path = public
as $$
  select
    (select count(*)::integer from public.bookings),
    (select count(*)::integer from public.bookings where payment_status = 'paid'),
    (select count(*)::integer from public.bookings where payment_status = 'unpaid'),
    (select count(*)::integer from public.bookings where payment_status = 'refunded'),
    (select coalesce(sum(number_of_people), 0)::integer
       from public.bookings where payment_status = 'paid'),
    (select count(*)::integer from public.digital_passes),
    (select count(*)::integer from public.digital_passes where status = 'active' and not checked_in),
    (select count(*)::integer from public.digital_passes where checked_in),
    (select count(*)::integer from public.check_ins where checked_in_at::date = p_today),
    (select count(*)::integer from public.event_dates),
    (select count(*)::integer from public.event_dates where event_date >= p_today and status = 'scheduled'),
    (select count(*)::integer from public.gallery where status = 'published'),
    (select count(*)::integer from public.gallery where status <> 'published'),
    (select count(*)::integer from public.admin_users where is_active),
    (select count(*)::integer from public.admin_users);
$$;

comment on function public.admin_dashboard_stats(date) is
  'Live counts for the admin dashboard, counted in the database rather than in the app. Takes the venue''s today so "tonight" means the venue''s tonight. service_role only.';

revoke execute on function public.admin_lookup_bookings(text, boolean, integer) from public, anon, authenticated;
revoke execute on function public.admin_dashboard_stats(date) from public, anon, authenticated;
grant execute on function public.admin_lookup_bookings(text, boolean, integer) to service_role;
grant execute on function public.admin_dashboard_stats(date) to service_role;


-- ===========================================================================
-- 20260922090900_admin_dashboard.sql
-- ===========================================================================

-- =============================================================================
-- 20260922090900_admin_dashboard.sql
--
-- Step 9 — the statistics behind the admin dashboard.
--
-- Every number on /admin is counted here, in one query per panel, by the database.
-- Nothing is summed in the browser and nothing is summed in Node either: the admin
-- area asks for aggregates, which is the only way a statistic like "total revenue"
-- can be trusted to match the rows it claims to describe.
--
-- Four functions:
--
--   admin_dashboard_stats(today, tz, include_revenue)   one row of headline numbers
--   admin_booking_series(today, days, tz, include_revenue)  a day-by-day time series
--   admin_pass_breakdown(include_revenue)                distribution across pass types
--   admin_recent_bookings(limit, include_contact)        the latest bookings
--
-- Three deliberate conventions:
--
--   * **Days are the venue's days.** Every date calculation takes the timezone from
--     the caller (`p_tz`, which is `siteConfig.timezone`) rather than assuming UTC, so
--     a booking made at 1am in Jaipur lands on the night it was actually made.
--   * **Money is the caller's business.** `p_include_revenue` / `p_include_contact`
--     return NULL instead of a figure when a role may not see it, so a staff session
--     never receives an amount it has no business rendering. Same rule as the booking
--     lookup in the step-8 migration.
--   * **"Revenue" means paid, never refunded.** `payment_status = 'paid'` is the only
--     definition used here; a refunded booking stops counting the moment it is
--     refunded, which is why the tests can subtract one and watch the total move.
--
-- All four are `service_role` only, like every other admin read.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. Headline numbers.
--
--    The step-8 version (one parameter) is replaced rather than kept alongside: two
--    functions answering the same question is how a dashboard ends up disagreeing
--    with itself. The argument list grows, so the old signature is dropped first.
-- -----------------------------------------------------------------------------
drop function if exists public.admin_dashboard_stats(date);

create or replace function public.admin_dashboard_stats(
  p_today           date,
  p_tz              text default 'UTC',
  p_include_revenue boolean default true
)
returns table (
  -- bookings
  bookings_total      integer,
  bookings_confirmed  integer,
  bookings_paid       integer,
  bookings_pending    integer,
  bookings_refunded   integer,
  bookings_today      integer,
  -- money (null when the caller may not see it)
  revenue_total       integer,
  revenue_today       integer,
  revenue_refunded    integer,
  -- the gate
  check_ins_total     integer,
  check_ins_today     integer,
  -- passes
  passes_issued       integer,
  passes_active       integer,
  passes_used         integer,
  -- capacity, over the nights still to come. `capacity_taken` counts people on paid
  -- bookings; `people_paid` is the same figure across every night, past included.
  people_paid         integer,
  capacity_total      integer,
  capacity_taken      integer,
  capacity_available  integer,
  -- tonight specifically, when there is a night tonight
  tonight_date        date,
  tonight_capacity    integer,
  tonight_taken       integer,
  tonight_available   integer,
  -- everything else the dashboard shows
  nights_total        integer,
  nights_upcoming     integer,
  gallery_published   integer,
  gallery_draft       integer,
  staff_active        integer,
  staff_total         integer
)
language sql
stable
security definer
set search_path = public
as $$
  with booked as (
    select
      b.id,
      b.number_of_people,
      b.total_amount,
      b.booking_status,
      b.payment_status,
      (b.created_at at time zone p_tz)::date as booked_on,
      d.event_date,
      d.status as night_status
      from public.bookings b
      join public.event_dates d on d.id = b.event_date_id
  ),
  paid as (
    select * from booked where payment_status = 'paid'
  ),
  -- Capacity is a property of a *night*, so these are the nights themselves. Summing
  -- capacity over booking rows would count a busy night's capacity once per booking,
  -- which is the kind of wrong number that looks plausible on a dashboard.
  upcoming_nights as (
    select d.id, d.event_date, d.capacity
      from public.event_dates d
     where d.status = 'scheduled'
       and d.event_date >= p_today
  ),
  tonight_nights as (
    select * from upcoming_nights where event_date = p_today
  ),
  taken_upcoming as (
    select coalesce(sum(b.number_of_people), 0) as people
      from public.bookings b
      join public.event_dates d on d.id = b.event_date_id
     where b.payment_status = 'paid'
       and d.status = 'scheduled'
       and d.event_date >= p_today
  ),
  taken_tonight as (
    select coalesce(sum(b.number_of_people), 0) as people
      from public.bookings b
      join public.event_dates d on d.id = b.event_date_id
     where b.payment_status = 'paid'
       and d.status = 'scheduled'
       and d.event_date = p_today
  )
  select
    (select count(*)::integer from booked),
    (select count(*)::integer from booked where booking_status = 'confirmed'),
    (select count(*)::integer from booked where payment_status = 'paid'),
    (select count(*)::integer from booked where payment_status = 'unpaid'),
    (select count(*)::integer from booked where payment_status = 'refunded'),
    (select count(*)::integer from booked where booked_on = p_today),

    case when p_include_revenue
         then (select coalesce(sum(total_amount), 0)::integer from paid)
    end,
    case when p_include_revenue
         then (select coalesce(sum(total_amount), 0)::integer from paid where booked_on = p_today)
    end,
    case when p_include_revenue
         then (select coalesce(sum(total_amount), 0)::integer from booked where payment_status = 'refunded')
    end,

    (select count(*)::integer from public.check_ins),
    (select count(*)::integer from public.check_ins
      where (checked_in_at at time zone p_tz)::date = p_today),

    (select count(*)::integer from public.digital_passes),
    (select count(*)::integer from public.digital_passes where status = 'active' and not checked_in),
    (select count(*)::integer from public.digital_passes where checked_in),

    (select coalesce(sum(number_of_people), 0)::integer from paid),
    (select coalesce(sum(capacity), 0)::integer from upcoming_nights),
    (select people::integer from taken_upcoming),
    (select greatest(
              coalesce((select sum(capacity) from upcoming_nights), 0)
              - (select people from taken_upcoming),
              0
            )::integer),

    (select min(event_date) from tonight_nights),
    (select coalesce(sum(capacity), 0)::integer from tonight_nights),
    (select people::integer from taken_tonight),
    (select greatest(
              coalesce((select sum(capacity) from tonight_nights), 0)
              - (select people from taken_tonight),
              0
            )::integer),

    (select count(*)::integer from public.event_dates),
    (select count(*)::integer from public.event_dates
      where event_date >= p_today and status = 'scheduled'),
    (select count(*)::integer from public.gallery where status = 'published'),
    (select count(*)::integer from public.gallery where status <> 'published'),
    (select count(*)::integer from public.admin_users where is_active),
    (select count(*)::integer from public.admin_users);
$$;

comment on function public.admin_dashboard_stats(date, text, boolean) is
  'The admin dashboard''s headline numbers, counted in the database. Days are the venue''s days (p_tz); money is null when p_include_revenue is false. service_role only.';

-- -----------------------------------------------------------------------------
-- 2. Bookings and revenue, day by day.
--
--    The series always covers every day in the window, including the quiet ones: a
--    chart with gaps in it tells a different story than the data does.
-- -----------------------------------------------------------------------------
create or replace function public.admin_booking_series(
  p_today           date,
  p_days            integer default 14,
  p_tz              text default 'UTC',
  p_include_revenue boolean default true
)
returns table (
  day        date,
  bookings   integer,
  confirmed  integer,
  revenue    integer
)
language sql
stable
security definer
set search_path = public
as $$
  with span as (
    select generate_series(
             p_today - (greatest(1, least(coalesce(p_days, 14), 90)) - 1),
             p_today,
             interval '1 day'
           )::date as day
  )
  select
    s.day,
    count(b.id)::integer as bookings,
    count(b.id) filter (where b.booking_status = 'confirmed')::integer as confirmed,
    case when p_include_revenue
         then coalesce(sum(b.total_amount) filter (where b.payment_status = 'paid'), 0)::integer
         else null
    end as revenue
  from span s
  left join public.bookings b
    on (b.created_at at time zone p_tz)::date = s.day
  group by s.day
  order by s.day;
$$;

comment on function public.admin_booking_series(date, integer, text, boolean) is
  'Bookings (and, when allowed, paid revenue) per day over the last p_days days, in the venue''s timezone, with the empty days included. service_role only.';

-- -----------------------------------------------------------------------------
-- 3. Distribution across pass types.
-- -----------------------------------------------------------------------------
create or replace function public.admin_pass_breakdown(
  p_include_revenue boolean default true
)
returns table (
  pass_category_id uuid,
  pass_name        text,
  pass_composition text,
  price_inr        integer,
  is_active        boolean,
  bookings         integer,
  paid_bookings    integer,
  passes_issued    integer,
  people           integer,
  revenue          integer
)
language sql
stable
security definer
set search_path = public
as $$
  -- Bookings and passes are aggregated in separate subqueries on purpose. Joining
  -- bookings to their passes in one query multiplies each booking by the number of
  -- passes it has, and a category with two two-pass bookings would report four times
  -- the people and the money it actually took.
  select
    p.id,
    p.name,
    p.composition,
    p.price_inr,
    p.is_active,
    b.bookings::integer,
    b.paid_bookings::integer,
    dp.passes_issued::integer,
    b.people::integer,
    case when p_include_revenue then b.revenue::integer end
  from public.pass_categories p
  left join lateral (
    select
      count(*) as bookings,
      count(*) filter (where o.payment_status = 'paid') as paid_bookings,
      coalesce(sum(o.number_of_people) filter (where o.payment_status = 'paid'), 0) as people,
      coalesce(sum(o.total_amount) filter (where o.payment_status = 'paid'), 0) as revenue
    from public.bookings o
    where o.pass_category_id = p.id
  ) b on true
  left join lateral (
    select count(*) as passes_issued
    from public.digital_passes d
    join public.bookings o on o.id = d.booking_id
    where o.pass_category_id = p.id
  ) dp on true
  -- Biggest first: this is a distribution chart, so the reader should not have to sort
  -- it in their head. Ties fall back to the organiser's own ordering.
  order by b.bookings desc, p.sort_order asc;
$$;

comment on function public.admin_pass_breakdown(boolean) is
  'How bookings and passes are distributed across the pass categories, biggest first. Revenue is null when p_include_revenue is false. service_role only.';

-- -----------------------------------------------------------------------------
-- 4. The latest bookings.
-- -----------------------------------------------------------------------------
create or replace function public.admin_recent_bookings(
  p_limit           integer default 8,
  p_include_contact boolean default true
)
returns table (
  booking_uuid      uuid,
  booking_id        text,
  customer_name     text,
  customer_mobile   text,
  customer_email    text,
  event_date        date,
  start_time        time,
  pass_name         text,
  quantity          integer,
  number_of_people  integer,
  total_amount      integer,
  currency          text,
  booking_status    text,
  payment_status    text,
  created_at        timestamptz
)
language sql
stable
security definer
set search_path = public
as $$
  select
    b.id,
    b.booking_id,
    b.customer_name,
    case when p_include_contact then b.customer_mobile end,
    case when p_include_contact then b.customer_email end,
    d.event_date,
    d.start_time,
    p.name,
    b.quantity,
    b.number_of_people,
    case when p_include_contact then b.total_amount end,
    e.currency,
    b.booking_status,
    b.payment_status,
    b.created_at
  from public.bookings b
  join public.event_dates d     on d.id = b.event_date_id
  join public.events e          on e.id = d.event_id
  join public.pass_categories p on p.id = b.pass_category_id
  order by b.created_at desc
  limit greatest(1, least(coalesce(p_limit, 8), 50));
$$;

comment on function public.admin_recent_bookings(integer, boolean) is
  'The most recently created bookings, newest first. Contact details and the amount are null when p_include_contact is false. service_role only.';

-- -----------------------------------------------------------------------------
-- 5. Grants. Every one of these reads across bookings, passes and money: the
--    browser may never call them, whatever key it is holding.
-- -----------------------------------------------------------------------------
revoke execute on function public.admin_dashboard_stats(date, text, boolean) from public, anon, authenticated;
revoke execute on function public.admin_booking_series(date, integer, text, boolean) from public, anon, authenticated;
revoke execute on function public.admin_pass_breakdown(boolean) from public, anon, authenticated;
revoke execute on function public.admin_recent_bookings(integer, boolean) from public, anon, authenticated;

grant execute on function public.admin_dashboard_stats(date, text, boolean) to service_role;
grant execute on function public.admin_booking_series(date, integer, text, boolean) to service_role;
grant execute on function public.admin_pass_breakdown(boolean) to service_role;
grant execute on function public.admin_recent_bookings(integer, boolean) to service_role;


-- ===========================================================================
-- 20260922091000_admin_booking_management.sql
-- ===========================================================================

-- =============================================================================
-- 20260922091000_admin_booking_management.sql
--
-- Step 10 — managing bookings, and the rule about who may say a payment succeeded.
--
--   * `admin_search_bookings()` replaces `admin_lookup_bookings()`. The old function
--     searched three fields with no filters and no paging; this one searches six
--     fields (reference, name, mobile, email, gateway ids, pass id), filters by event
--     date, pass category, payment status, booking status and check-in state, pages,
--     and reports the size of the whole result set. Its matching is a superset of the
--     old one, so nothing that used to be found stops being found.
--   * `admin_booking_detail()` returns one booking completely: the night and venue,
--     the pass category, every pass and its state, every gate entry with the staff
--     member who made it, the gateway ids, and the webhook deliveries received for
--     that order.
--   * `bookings.payment_status` becomes something only a verified gateway event can
--     move (see the guard below). There is no administrative path that sets a booking
--     to paid by hand, and this migration makes that a database fact rather than a
--     convention the next contributor has to notice.
--
-- All of the reads are `service_role` only, like every other admin read.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. The old lookup goes.
--
--    Replaced, not deprecated: leaving both in place would give the admin area two
--    searches with different, drifting rules for "which bookings match this".
-- -----------------------------------------------------------------------------
drop function if exists public.admin_lookup_bookings(text, boolean, integer);

-- -----------------------------------------------------------------------------
-- 2. The booking list.
--
--    One function answers every question the management screen asks: six search
--    fields, five filters, paging and the size of the whole result set, in one round
--    trip. `admin_lookup_bookings` is gone rather than kept alongside — its matching
--    rules were a strict subset of these, and two searches that answer "which
--    bookings" slightly differently is how an admin ends up looking at a list that
--    does not contain the row they are hunting for.
--
--    The contact columns (mobile, email, amounts, gateway ids) come back NULL when
--    `p_include_contact` is false. That is the staff view, and the withholding happens
--    here, in the same statement that reads the columns.
-- -----------------------------------------------------------------------------
create or replace function public.admin_search_bookings(
  p_query            text    default null,
  p_event_date_from  date    default null,
  p_event_date_to    date    default null,
  p_pass_category_id uuid    default null,
  p_payment_status   text    default null,
  p_booking_status   text    default null,
  p_check_in_status  text    default null,
  p_include_contact  boolean default true,
  p_limit            integer default 25,
  p_offset           integer default 0
)
returns table (
  booking_uuid        uuid,
  booking_id          text,
  customer_name       text,
  customer_mobile     text,
  customer_email      text,
  event_name          text,
  event_slug          text,
  event_date          date,
  start_time          time,
  end_time            time,
  pass_name           text,
  pass_composition    text,
  quantity            integer,
  number_of_people    integer,
  total_amount        integer,
  currency            text,
  booking_status      text,
  payment_status      text,
  razorpay_order_id   text,
  razorpay_payment_id text,
  created_at          timestamptz,
  passes_issued       integer,
  passes_checked_in   integer,
  check_in_times      timestamptz[],
  pass_ids            text[],
  total_count         integer
)
language sql
stable
security definer
set search_path = public
as $$
  with params as (
    select
      -- An empty search box is not a search: it means "the list", which is what a
      -- management screen should open on. Long input is truncated rather than
      -- refused: nobody is typing a 64-character booking reference.
      nullif(left(btrim(coalesce(p_query, '')), 64), '')   as q,
      -- The same term with LIKE's own wildcards neutralised, so a search for "50%"
      -- or "a_b" means those characters and not "anything". Without this, "%" would
      -- quietly return every booking in the event.
      replace(
        replace(
          replace(left(btrim(coalesce(p_query, '')), 64), '\', '\\'),
          '%', '\%'
        ),
        '_', '\_'
      )                                                    as q_like,
      -- The digits of the search term, for matching a mobile number however it was
      -- typed — but only when the term *is* a number. Empty string means the mobile
      -- clause is skipped, and that is what keeps two very different searches apart:
      --
      --   * "98123 45678" and "+91 98000 01001" are phone numbers, and the digits are
      --     matched against the mobile column without regard to how they were typed;
      --   * "Bulk Fixture 01" and "Room 101" are names with numbers in them. Their
      --     digits are not a phone number, and matching "01" against every mobile
      --     containing "01" would answer a name search with half the event.
      --
      -- A term with no letters qualifies, and only from four digits up: two digits
      -- appear in most phone numbers, which is the same as matching everything.
      case
        when left(btrim(coalesce(p_query, '')), 64) !~ '[[:alpha:]]'
         and length(regexp_replace(coalesce(p_query, ''), '\D', '', 'g')) >= 4
        then regexp_replace(coalesce(p_query, ''), '\D', '', 'g')
        else ''
      end                                                    as q_digits,
      greatest(1, least(coalesce(p_limit, 25), 100))       as page_size,
      greatest(0, coalesce(p_offset, 0))                   as page_offset,
      -- Only values the schema actually holds become filters. A typo in the query
      -- string narrows nothing; it does not silently return an empty list that looks
      -- like "no such booking".
      case when p_payment_status in ('unpaid', 'created', 'paid', 'failed', 'refunded')
           then p_payment_status end                       as payment_status,
      case when p_booking_status in ('pending', 'confirmed', 'cancelled', 'expired', 'refunded')
           then p_booking_status end                       as booking_status,
      case when p_check_in_status in ('none', 'some', 'all')
           then p_check_in_status end                      as check_in_status
  ),
  pass_state as (
    select
      dp.booking_id                                      as booking_uuid,
      count(*)::integer                                  as issued,
      count(*) filter (where dp.checked_in)::integer      as checked_in,
      array_remove(array_agg(dp.checked_in_at order by dp.pass_number), null) as check_in_times,
      -- Every pass on the booking, in the order they were issued: the numbers a
      -- guest reads out at the gate, and the rows a door list is printed from.
      array_agg(dp.pass_id order by dp.pass_number)        as pass_ids
    from public.digital_passes dp
    group by dp.booking_id
  ),
  matched as (
    select b.id, b.created_at
    from public.bookings b
    join public.event_dates d     on d.id = b.event_date_id
    left join pass_state ps       on ps.booking_uuid = b.id
    cross join params p
    where (
        p.q is null
        or b.booking_id ilike '%' || p.q_like || '%'
        or b.customer_name ilike '%' || p.q_like || '%'
        or b.customer_email ilike '%' || p.q_like || '%'
        -- The gateway ids, so a payment id from a Razorpay receipt finds its booking.
        or b.razorpay_payment_id ilike '%' || p.q_like || '%'
        or b.razorpay_order_id ilike '%' || p.q_like || '%'
        or (
          p.q_digits <> ''
          and regexp_replace(b.customer_mobile, '\D', '', 'g') like '%' || p.q_digits || '%'
        )
        -- A pass id, printed on the guest's ticket.
        or exists (
          select 1 from public.digital_passes dp
          where dp.booking_id = b.id and dp.pass_id ilike '%' || p.q_like || '%'
        )
      )
      and (p_event_date_from is null or d.event_date >= p_event_date_from)
      and (p_event_date_to   is null or d.event_date <= p_event_date_to)
      and (p_pass_category_id is null or b.pass_category_id = p_pass_category_id)
      and (p.payment_status is null or b.payment_status = p.payment_status)
      and (p.booking_status is null or b.booking_status = p.booking_status)
      and (
        p.check_in_status is null
        -- "none" means nobody has been admitted yet: no pass checked in, whether or
        -- not passes were issued (an unpaid booking has none).
        or (p.check_in_status = 'none' and coalesce(ps.checked_in, 0) = 0)
        -- "some" is the interesting one: part of a group is inside.
        or (
          p.check_in_status = 'some'
          and coalesce(ps.checked_in, 0) > 0
          and coalesce(ps.checked_in, 0) < coalesce(ps.issued, 0)
        )
        or (
          p.check_in_status = 'all'
          and coalesce(ps.issued, 0) > 0
          and coalesce(ps.checked_in, 0) = coalesce(ps.issued, 0)
        )
      )
  ),
  counted as (
    -- The size of the whole result set, not of the page: the screen has to say
    -- "showing 1–25 of 240" before the admin scrolls.
    select m.id, m.created_at, count(*) over ()::integer as total_count
    from matched m
  ),
  page as (
    select c.id, c.total_count
    from counted c
    order by c.created_at desc, c.id desc
    limit (select page_size from params)
    offset (select page_offset from params)
  )
  select
    b.id,
    b.booking_id,
    b.customer_name,
    case when p_include_contact then b.customer_mobile end,
    case when p_include_contact then b.customer_email end,
    e.name,
    e.slug,
    d.event_date,
    d.start_time,
    d.end_time,
    p.name,
    p.composition,
    b.quantity,
    b.number_of_people,
    case when p_include_contact then b.total_amount end,
    e.currency,
    b.booking_status,
    b.payment_status,
    case when p_include_contact then b.razorpay_order_id end,
    case when p_include_contact then b.razorpay_payment_id end,
    b.created_at,
    coalesce(ps.issued, 0),
    coalesce(ps.checked_in, 0),
    ps.check_in_times,
    coalesce(ps.pass_ids, '{}'::text[]),
    pg.total_count
  from page pg
  join public.bookings b        on b.id = pg.id
  join public.event_dates d     on d.id = b.event_date_id
  join public.events e          on e.id = d.event_id
  join public.pass_categories p on p.id = b.pass_category_id
  left join pass_state ps       on ps.booking_uuid = b.id
  order by b.created_at desc, b.id desc;
$$;

comment on function public.admin_search_bookings(text, date, date, uuid, text, text, text, boolean, integer, integer) is
  'The admin booking list: search by reference, name, mobile, email, Razorpay payment/order id or pass id, filtered by event date, pass category, payment status, booking status and check-in state, paged, with the total number of matches. Contact details, amounts and gateway ids come back null when p_include_contact is false. service_role only.';

-- -----------------------------------------------------------------------------
-- 3. One booking, completely.
--
--    Everything a support conversation needs, in one row: the booking, the night and
--    venue, the pass category, every pass with its state, every gate entry with who
--    made it, the gateway ids, and the webhook deliveries that were received for this
--    order. The payment events are the point: they are read-only evidence of what
--    Razorpay actually reported, as opposed to what somebody believes happened.
--
--    `p_lookup` accepts the booking reference, a pass id or either gateway id, so a
--    support link can be built from whatever the guest has in front of them.
--
--    The QR token is deliberately not returned. It is the credential that admits one
--    person at the gate, and nothing on this screen needs it: the guest's own pass
--    page is the only thing that shows a pass, and it shows it to the guest.
-- -----------------------------------------------------------------------------
create or replace function public.admin_booking_detail(
  p_lookup          text,
  p_include_contact boolean default true
)
returns table (
  booking_uuid        uuid,
  booking_id          text,
  customer_name       text,
  customer_mobile     text,
  customer_email      text,
  event_name          text,
  event_slug          text,
  venue_name          text,
  venue_address       text,
  city                text,
  event_date          date,
  start_time          time,
  end_time            time,
  pass_name           text,
  pass_composition    text,
  quantity            integer,
  number_of_people    integer,
  subtotal            integer,
  total_amount        integer,
  currency            text,
  booking_status      text,
  payment_status      text,
  razorpay_order_id   text,
  razorpay_payment_id text,
  notes               text,
  created_at          timestamptz,
  updated_at          timestamptz,
  passes              jsonb,
  check_ins           jsonb,
  payment_events      jsonb
)
language sql
stable
security definer
set search_path = public
as $$
  with target as (
    select b.*
    from public.bookings b
    where coalesce(btrim(p_lookup), '') <> ''
      and (
        lower(b.booking_id) = lower(btrim(p_lookup))
        or b.razorpay_payment_id = btrim(p_lookup)
        or b.razorpay_order_id = btrim(p_lookup)
        or exists (
          select 1 from public.digital_passes dp
          where dp.booking_id = b.id and lower(dp.pass_id) = lower(btrim(p_lookup))
        )
      )
    limit 1
  )
  select
    b.id,
    b.booking_id,
    b.customer_name,
    case when p_include_contact then b.customer_mobile end,
    case when p_include_contact then b.customer_email end,
    e.name,
    e.slug,
    e.venue_name,
    e.venue_address,
    e.city,
    d.event_date,
    d.start_time,
    d.end_time,
    p.name,
    p.composition,
    b.quantity,
    b.number_of_people,
    case when p_include_contact then b.subtotal end,
    case when p_include_contact then b.total_amount end,
    e.currency,
    b.booking_status,
    b.payment_status,
    case when p_include_contact then b.razorpay_order_id end,
    case when p_include_contact then b.razorpay_payment_id end,
    case when p_include_contact then b.notes end,
    b.created_at,
    b.updated_at,
    coalesce(
      (
        select jsonb_agg(
                 jsonb_build_object(
                   'pass_id', dp.pass_id,
                   'pass_number', dp.pass_number,
                   'status', dp.status,
                   'checked_in', dp.checked_in,
                   'checked_in_at', dp.checked_in_at,
                   'valid_date', dp.valid_date
                 )
                 order by dp.pass_number
               )
        from public.digital_passes dp
        where dp.booking_id = b.id
      ),
      '[]'::jsonb
    ),
    coalesce(
      (
        select jsonb_agg(
                 jsonb_build_object(
                   'checked_in_at', ci.checked_in_at,
                   'gate', ci.gate,
                   'notes', ci.notes,
                   'staff', coalesce(nullif(btrim(au.full_name), ''), au.email),
                   'pass_id', dp.pass_id
                 )
                 order by ci.checked_in_at
               )
        from public.check_ins ci
        join public.digital_passes dp on dp.id = ci.digital_pass_id
        left join public.admin_users au on au.id = ci.checked_in_by
        where dp.booking_id = b.id
      ),
      '[]'::jsonb
    ),
    case
      when p_include_contact then coalesce(
        (
          select jsonb_agg(
                   jsonb_build_object(
                     'event_id', pe.event_id,
                     'event_type', pe.event_type,
                     'outcome', pe.outcome,
                     'amount_paise', pe.amount_paise,
                     'received_at', pe.received_at,
                     'processed_at', pe.processed_at
                   )
                   order by pe.received_at
                 )
          from public.payment_events pe
          where pe.razorpay_order_id = b.razorpay_order_id
             or (b.razorpay_payment_id is not null and pe.razorpay_payment_id = b.razorpay_payment_id)
        ),
        '[]'::jsonb
      )
    end
  from target b
  join public.event_dates d     on d.id = b.event_date_id
  join public.events e          on e.id = d.event_id
  join public.pass_categories p on p.id = b.pass_category_id;
$$;

comment on function public.admin_booking_detail(text, boolean) is
  'One booking in full — passes, gate entries and the Razorpay events received for its order — found by booking reference, pass id, payment id or order id. Contact details, amounts and gateway ids come back null when p_include_contact is false. service_role only.';

-- -----------------------------------------------------------------------------
-- 4. The payment-status guard.
--
--    `payment_status` describes what the *gateway* did, so the database refuses to
--    let it change unless the statement that changes it carries proof that a verified
--    gateway event is behind it. The three functions that legitimately move it set
--    `app.payment_proof` for the duration of their own transaction (re-created below,
--    bodies otherwise unchanged); everything else — an ad-hoc `update` in the SQL
--    editor, a script, a future "mark as paid" button somebody adds in a hurry —
--    fails with PB007.
--
--    This is the "clearly defined secure administrative process" from the other
--    direction: there is no manual path to paid at all. A payment that Razorpay
--    captured but the site did not record is fixed by re-delivering the gateway's own
--    event (Razorpay dashboard → Webhooks → resend), which lands in
--    `confirm_booking_payment` with a signature-verified payload — never by typing a
--    status into a row.
--
--    Refunds are held to the same rule, because `refund_booking_payment` is the same
--    kind of thing: it is driven by `refund.processed` from the gateway.
-- -----------------------------------------------------------------------------
create or replace function public.guard_booking_payment_status()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
begin
  if new.payment_status is distinct from old.payment_status
     and coalesce(current_setting('app.payment_proof', true), '') <> 'razorpay-verified' then
    raise exception 'payment_status may only change through a verified Razorpay event'
      using errcode = 'PB007',
            hint = 'Re-deliver the gateway event (Razorpay → Webhooks → resend) instead of writing the status by hand.';
  end if;

  return new;
end;
$$;

comment on function public.guard_booking_payment_status() is
  'Refuses any change to bookings.payment_status that does not come from a verified gateway event (set app.payment_proof inside the payment functions).';

drop trigger if exists bookings_guard_payment_status on public.bookings;
create trigger bookings_guard_payment_status
  before update on public.bookings
  for each row execute function public.guard_booking_payment_status();


-- Re-created from 20260922090600_digital_pass.sql with the payment-proof line added at the top of the body; nothing else changed.
create or replace function public.confirm_booking_payment(
  p_razorpay_order_id  text,
  p_razorpay_payment_id text,
  p_amount_paise       integer default null
)
returns table (
  booking_uuid     uuid,
  booking_reference text,
  public_token     uuid,
  booking_status   text,
  payment_status   text,
  quantity         integer,
  number_of_people integer,
  subtotal         integer,
  total_amount     integer,
  event_id         uuid,
  event_date       date,
  start_time       time,
  end_time         time,
  pass_name        text,
  pass_composition text,
  currency         text,
  passes_issued    integer,
  already_confirmed boolean,
  capacity_note    text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking  record;
  v_holder   uuid;
  v_booked   integer;
  v_capacity integer;
  v_note     text;
begin
  -- This function runs because a gateway event was verified (or because the
  -- checkout was confirmed with a valid signature). The token is local to this
  -- transaction and is what the guard trigger looks for.
  perform set_config('app.payment_proof', 'razorpay-verified', true);
  select b.* into v_booking
  from public.bookings b
  where b.razorpay_order_id = p_razorpay_order_id
  for update;

  if not found then
    raise exception 'order_not_found' using errcode = 'PC001';
  end if;

  -- The amount must be what the database says the booking costs. A ₹1 payment
  -- cannot confirm a ₹998 booking.
  if p_amount_paise is not null and p_amount_paise <> v_booking.total_amount * 100 then
    raise exception 'amount_mismatch' using errcode = 'PC002';
  end if;

  -- One payment can only ever belong to one booking.
  select b.id into v_holder
  from public.bookings b
  where b.razorpay_payment_id = p_razorpay_payment_id
    and b.id <> v_booking.id;

  if found then
    raise exception 'payment_already_used' using errcode = 'PC003';
  end if;

  -- Already paid: a duplicate callback gets the same answer, and nothing is
  -- written again (no second set of passes).
  if v_booking.payment_status = 'paid' then
    return query
      select b.id, b.booking_id, b.public_token, b.booking_status, b.payment_status, b.quantity,
             b.number_of_people, b.subtotal, b.total_amount, d.event_id, d.event_date,
             d.start_time, d.end_time, p.name, p.composition, e.currency,
             (select count(*)::integer from public.digital_passes dp where dp.booking_id = b.id),
             true, b.notes
      from public.bookings b
      join public.event_dates d on d.id = b.event_date_id
      join public.pass_categories p on p.id = b.pass_category_id
      join public.events e on e.id = d.event_id
      where b.id = v_booking.id;

    return;
  end if;

  -- From here on the booking is being paid for the first time, so a payment id is
  -- mandatory: an event without one (`order.paid` on its own) is ignored by the
  -- dispatcher and the `payment.captured` delivery does the work instead.
  if p_razorpay_payment_id is null or length(btrim(p_razorpay_payment_id)) = 0 then
    raise exception 'payment_id_required' using errcode = 'PC005';
  end if;

  -- Capacity is checked again, but the customer has already paid: the booking is
  -- confirmed either way and an organiser flag is recorded instead of silently
  -- dropping a paid booking.
  select coalesce(sum(b.number_of_people) filter (where b.payment_status = 'paid'), 0)::integer
    into v_booked
  from public.bookings b
  where b.event_date_id = v_booking.event_date_id
    and b.id <> v_booking.id;

  select d.capacity into v_capacity
  from public.event_dates d
  where d.id = v_booking.event_date_id;

  if v_booked + v_booking.number_of_people > v_capacity then
    v_note := 'capacity exceeded when payment was confirmed — needs organiser review';
  end if;

  update public.bookings b
  set payment_status   = 'paid',
      booking_status   = 'confirmed',
      razorpay_payment_id = p_razorpay_payment_id,
      notes            = coalesce(v_note, b.notes)
  where b.id = v_booking.id;

  -- One scannable pass per purchased pass, issued only now that payment is
  -- verified. Guarded three ways: the replay above returns early, the not-exists
  -- check skips a booking that already has passes, and the unique
  -- (booking_id, pass_number) index makes a duplicate slot impossible.
  insert into public.digital_passes (booking_id, valid_date, pass_number, status)
  select v_booking.id, d.event_date, s.slot, 'active'
  from public.event_dates d
  cross join generate_series(1, v_booking.quantity) as s(slot)
  where d.id = v_booking.event_date_id
    and not exists (select 1 from public.digital_passes dp where dp.booking_id = v_booking.id)
  on conflict (booking_id, pass_number) do nothing;

  return query
    select b.id, b.booking_id, b.public_token, b.booking_status, b.payment_status, b.quantity,
           b.number_of_people, b.subtotal, b.total_amount, d.event_id, d.event_date,
           d.start_time, d.end_time, p.name, p.composition, e.currency,
           (select count(*)::integer from public.digital_passes dp where dp.booking_id = b.id),
           false, b.notes
    from public.bookings b
    join public.event_dates d on d.id = b.event_date_id
    join public.pass_categories p on p.id = b.pass_category_id
    join public.events e on e.id = d.event_id
    where b.id = v_booking.id;
end;
$$;

-- Re-created from 20260922090500_payments.sql with the payment-proof line added at the top of the body; nothing else changed.
create or replace function public.fail_booking_payment(
  p_razorpay_order_id   text,
  p_razorpay_payment_id text default null
)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking record;
begin
  -- This function runs because a gateway event was verified (or because the
  -- checkout was confirmed with a valid signature). The token is local to this
  -- transaction and is what the guard trigger looks for.
  perform set_config('app.payment_proof', 'razorpay-verified', true);
  select b.* into v_booking
  from public.bookings b
  where b.razorpay_order_id = p_razorpay_order_id
  for update;

  if not found then
    return 'not_found';
  end if;

  -- A paid booking is never downgraded by a late failure event.
  if v_booking.payment_status = 'paid' then
    return 'already_paid';
  end if;

  update public.bookings b
  set payment_status = 'failed'
  where b.id = v_booking.id;

  return 'failed';
end;
$$;

-- Re-created from 20260922090500_payments.sql with the payment-proof line added at the top of the body; nothing else changed.
create or replace function public.refund_booking_payment(
  p_razorpay_payment_id text
)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_booking record;
begin
  -- This function runs because a gateway event was verified (or because the
  -- checkout was confirmed with a valid signature). The token is local to this
  -- transaction and is what the guard trigger looks for.
  perform set_config('app.payment_proof', 'razorpay-verified', true);
  select b.* into v_booking
  from public.bookings b
  where b.razorpay_payment_id = p_razorpay_payment_id
  for update;

  if not found then
    return 'not_found';
  end if;

  if v_booking.payment_status = 'refunded' then
    return 'already_refunded';
  end if;

  update public.bookings b
  set payment_status = 'refunded',
      booking_status = 'refunded'
  where b.id = v_booking.id;

  update public.digital_passes dp
  set status = 'cancelled'
  where dp.booking_id = v_booking.id;

  return 'refunded';
end;
$$;

-- -----------------------------------------------------------------------------
-- 5. Grants. The search and the detail read across bookings, passes, check-ins and
--    payment events: no browser session may call them, whatever key it holds.
-- -----------------------------------------------------------------------------
revoke execute on function public.admin_search_bookings(text, date, date, uuid, text, text, text, boolean, integer, integer) from public, anon, authenticated;
revoke execute on function public.admin_booking_detail(text, boolean) from public, anon, authenticated;

grant execute on function public.admin_search_bookings(text, date, date, uuid, text, text, text, boolean, integer, integer) to service_role;
grant execute on function public.admin_booking_detail(text, boolean) to service_role;


-- ===========================================================================
-- 20260922091100_admin_payments_and_passes.sql
-- ===========================================================================

-- =============================================================================
-- 20260922091100_admin_payments_and_passes.sql
--
-- Step 11 (part 1) — the two read-only operations screens: /admin/payments and
-- /admin/passes.
--
-- Both answer a question the bookings list cannot, because both are about
-- *artefacts* rather than about orders:
--
--   payments   what the gateway actually sent us, delivery by delivery, and which
--              rows contradict themselves;
--   passes     every ticket that exists, where it is, and whether it is in.
--
-- Six functions:
--
--   admin_search_pattern(text)            shared: a search term, wildcards escaped
--   admin_search_digits(text)             shared: the term's digits, when it is a
--                                         number and not just a name with digits in it
--   admin_payment_events(...)             one row per gateway delivery, with the
--                                         booking it belongs to
--   admin_payment_attention(...)          bookings whose payment state contradicts
--                                         the rest of the row
--   admin_payment_summary(...)            the counts above the deliveries
--   admin_pass_list(...)                  one row per issued pass, with its booking
--   admin_pass_summary(...)               the counts above the pass list
--
-- Three conventions, all inherited from step 10 because an operator moving between
-- these three screens should not have to learn a second set of rules:
--
--   * **Searching is one function's job.** `admin_search_pattern` escapes LIKE's own
--     wildcards, so a term of `%` finds nothing rather than everything, and
--     `admin_search_digits` decides whether a term is a phone number at all — a name
--     with digits in it ("Gate 4") must not sweep in every mobile containing "4".
--   * **An unknown filter value narrows nothing.** A status the schema does not hold
--     is dropped rather than forwarded, because an empty list that reads as "nothing
--     here" is a worse answer than ignoring a typo.
--   * **Contact details and money are the caller's business.** Every list takes
--     `p_include_contact`, and returns NULL rather than a figure it may not show.
--     Nothing on these screens can change a payment status: the guard trigger from
--     step 10 (`PB007`) refuses that, whichever path is taken.
--
-- All six are `service_role` only, like every other admin read.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. The two search helpers.
--
--    Step 10 inlined these expressions in `admin_search_bookings`. They live as
--    functions here so both of this migration's lists share one definition rather
--    than three copies of the same rule — the rule being: a search term is a term,
--    not a pattern, and its digits are a phone number only when the term is one.
-- -----------------------------------------------------------------------------
create or replace function public.admin_search_pattern(p_query text)
returns text
language sql
immutable
set search_path = public
as $$
  -- The term, trimmed and capped, with LIKE's wildcards neutralised. Backslashes
  -- first, then `%`, then `_`: escaping the escape last would double it.
  select replace(
           replace(
             replace(left(btrim(coalesce(p_query, '')), 64), '\', '\\'),
             '%', '\%'
           ),
           '_', '\_'
         );
$$;

comment on function public.admin_search_pattern(text) is
  'A search term with LIKE wildcards escaped, so a term means the characters it contains. Empty in, empty out.';

create or replace function public.admin_search_digits(p_query text)
returns text
language sql
immutable
set search_path = public
as $$
  -- The digits of the term, but only when the term *is* a number: no letters, and at
  -- least four digits. Two digits appear in most phone numbers (matching everything),
  -- and "Gate 4" is a name — neither should reach the mobile column.
  select case
           when left(btrim(coalesce(p_query, '')), 64) !~ '[[:alpha:]]'
            and length(regexp_replace(coalesce(p_query, ''), '\D', '', 'g')) >= 4
           then regexp_replace(coalesce(p_query, ''), '\D', '', 'g')
           else ''
         end;
$$;

comment on function public.admin_search_digits(text) is
  'The digits of a search term when the term is a phone number (no letters, 4+ digits), otherwise an empty string.';

-- -----------------------------------------------------------------------------
-- 2. The gateway's deliveries.
--
--    One row per event the gateway sent or the checkout confirmed, newest first,
--    matched to the booking it belongs to where one can be identified. An event that
--    matches nothing is still listed: "a delivery arrived that belongs to no booking"
--    is exactly the kind of thing this screen exists to show.
-- -----------------------------------------------------------------------------
create or replace function public.admin_payment_events(
  p_query           text default null,
  p_outcome         text default null,
  p_event_type      text default null,
  p_from            date default null,
  p_to              date default null,
  p_include_contact boolean default true,
  p_limit           integer default 25,
  p_offset          integer default 0
)
returns table (
  event_uuid          uuid,
  event_id            text,
  event_type          text,
  outcome             text,
  razorpay_order_id   text,
  razorpay_payment_id text,
  amount_paise        integer,
  received_at         timestamptz,
  processed_at        timestamptz,
  booking_uuid        uuid,
  booking_id          text,
  customer_name       text,
  customer_mobile     text,
  booking_status      text,
  payment_status      text,
  total_amount        integer,
  currency            text,
  total_count         integer
)
language sql
stable
security definer
set search_path = public
as $$
  with params as (
    select
      nullif(left(btrim(coalesce(p_query, '')), 64), '') as q,
      public.admin_search_pattern(p_query)               as q_like,
      public.admin_search_digits(p_query)                as q_digits,
      greatest(1, least(coalesce(p_limit, 25), 100))     as page_size,
      greatest(0, coalesce(p_offset, 0))                 as page_offset,
      -- Only values the schema holds become filters; anything else narrows nothing.
      case when p_outcome in ('received', 'confirmed', 'already_confirmed', 'failed',
                              'refunded', 'ignored', 'duplicate')
           then p_outcome end                            as outcome,
      case when nullif(btrim(coalesce(p_event_type, '')), '') is not null
           then btrim(p_event_type) end                  as event_type
  ),
  matched as (
    select pe.id, pe.received_at
    from public.payment_events pe
    cross join params p
    where (
        p.q is null
        -- Searched over what the gateway sent and over the booking it points at, so
        -- a support thread can start from whichever id the customer quoted.
        or pe.razorpay_order_id ilike '%' || p.q_like || '%'
        or pe.razorpay_payment_id ilike '%' || p.q_like || '%'
        or pe.event_id ilike '%' || p.q_like || '%'
        or pe.event_type ilike '%' || p.q_like || '%'
        or exists (
          select 1
          from public.bookings b
          where (b.razorpay_order_id = pe.razorpay_order_id
                 or (pe.razorpay_payment_id is not null and b.razorpay_payment_id = pe.razorpay_payment_id))
            and (
              b.booking_id ilike '%' || p.q_like || '%'
              or b.customer_name ilike '%' || p.q_like || '%'
              or b.customer_email ilike '%' || p.q_like || '%'
              or (p.q_digits <> '' and regexp_replace(b.customer_mobile, '\D', '', 'g') like '%' || p.q_digits || '%')
            )
        )
      )
      and (p.outcome is null or pe.outcome = p.outcome)
      and (p.event_type is null or pe.event_type = p.event_type)
      and (p_from is null or (pe.received_at at time zone 'UTC')::date >= p_from)
      and (p_to   is null or (pe.received_at at time zone 'UTC')::date <= p_to)
  ),
  counted as (
    select m.id, m.received_at, count(*) over ()::integer as total_count
    from matched m
  ),
  page as (
    select c.id, c.total_count
    from counted c
    order by c.received_at desc, c.id desc
    limit (select page_size from params)
    offset (select page_offset from params)
  )
  select
    pe.id,
    pe.event_id,
    pe.event_type,
    pe.outcome,
    pe.razorpay_order_id,
    pe.razorpay_payment_id,
    case when p_include_contact then pe.amount_paise end,
    pe.received_at,
    pe.processed_at,
    b.id,
    b.booking_id,
    b.customer_name,
    case when p_include_contact then b.customer_mobile end,
    b.booking_status,
    b.payment_status,
    case when p_include_contact then b.total_amount end,
    e.currency,
    pg.total_count
  from page pg
  join public.payment_events pe on pe.id = pg.id
  -- At most one booking per delivery: an order id is unique, and a payment id is
  -- unique, so the lateral is a lookup rather than a fan-out.
  left join lateral (
    select bk.*
    from public.bookings bk
    where bk.razorpay_order_id = pe.razorpay_order_id
       or (pe.razorpay_payment_id is not null and bk.razorpay_payment_id = pe.razorpay_payment_id)
    order by bk.created_at desc
    limit 1
  ) b on true
  left join public.event_dates d on d.id = b.event_date_id
  left join public.events e      on e.id = d.event_id
  order by pe.received_at desc, pe.id desc;
$$;

comment on function public.admin_payment_events(text, text, text, date, date, boolean, integer, integer) is
  'Every gateway delivery (and every checkout confirmation) as a row, newest first, with the booking it belongs to where one can be identified — including deliveries that match no booking at all. Money and contact details come back null when p_include_contact is false. service_role only.';

-- -----------------------------------------------------------------------------
-- 3. The counts above the deliveries.
--
--    Counted from the gateway's own rows rather than from the bookings, so the figures
--    describe what actually arrived. `captured_paise` and `refunded_paise` are the
--    gateway's amounts, which is the point: they are the one number on this screen that
--    does not come from a figure the site wrote down itself.
-- -----------------------------------------------------------------------------
create or replace function public.admin_payment_summary(
  p_include_contact boolean default true
)
returns table (
  events_total          integer,
  events_confirmed      integer,
  events_failed         integer,
  events_refunded       integer,
  events_ignored        integer,
  events_duplicate      integer,
  orders_awaiting       integer,
  last_received_at      timestamptz,
  last_processed_at     timestamptz,
  captured_paise        bigint,
  refunded_paise        bigint
)
language sql
stable
security definer
set search_path = public
as $$
  with events as (
    select
      count(*)::integer                                        as total,
      count(*) filter (where pe.outcome in ('confirmed', 'already_confirmed'))::integer as confirmed,
      count(*) filter (where pe.outcome = 'failed')::integer     as failed,
      count(*) filter (where pe.outcome = 'refunded')::integer   as refunded,
      count(*) filter (where pe.outcome = 'ignored')::integer    as ignored,
      count(*) filter (where pe.outcome = 'duplicate')::integer  as duplicate,
      max(pe.received_at)                                       as last_received,
      max(pe.processed_at)                                      as last_processed,
      coalesce(sum(pe.amount_paise) filter (where pe.outcome in ('confirmed', 'already_confirmed')), 0)::bigint as captured,
      coalesce(sum(pe.amount_paise) filter (where pe.outcome = 'refunded'), 0)::bigint as refunded_amount
    from public.payment_events pe
  )
  select
    e.total,
    e.confirmed,
    e.failed,
    e.refunded,
    e.ignored,
    e.duplicate,
    -- Money the gateway has an order for and nothing has verified yet: an abandoned
    -- checkout, or a customer who is still on the payment page.
    (select count(*)::integer
       from public.bookings b
      where b.razorpay_order_id is not null
        and b.payment_status in ('unpaid', 'created', 'failed')),
    e.last_received,
    e.last_processed,
    case when p_include_contact then e.captured end,
    case when p_include_contact then e.refunded_amount end
  from events e;
$$;

comment on function public.admin_payment_summary(boolean) is
  'Counts over the gateway deliveries by outcome, the orders the gateway has an order for and nothing has verified, when the last delivery arrived and how much the gateway says was captured and refunded — the last two null when p_include_contact is false. service_role only.';

-- -----------------------------------------------------------------------------
-- 3. The rows that contradict themselves.
--
--    Not a heuristic: every row here is a state the database''s own rules call a
--    contradiction, which is why each one carries the reason and what to do about it.
--    A screen that lists "things that look odd" without saying why is a screen nobody
--    trusts; this one names the broken invariant in the row itself.
-- -----------------------------------------------------------------------------
create or replace function public.admin_payment_attention(
  p_include_contact boolean default true,
  p_limit           integer default 25
)
returns table (
  reason_code        text,
  reason             text,
  action             text,
  booking_uuid       uuid,
  booking_id         text,
  customer_name      text,
  customer_mobile    text,
  booking_status     text,
  payment_status     text,
  total_amount       integer,
  currency           text,
  razorpay_order_id  text,
  razorpay_payment_id text,
  event_date         date,
  passes_issued      integer,
  passes_active      integer,
  event_count        integer,
  created_at         timestamptz,
  total_count        integer
)
language sql
stable
security definer
set search_path = public
as $$
  with candidates as (
    select
      -- Each case is one broken expectation, in the order an operator should care.
      case
        when b.payment_status = 'paid' and coalesce(pst.issued, 0) = 0
          then 'paid-no-pass'
        when b.payment_status = 'paid' and b.booking_status <> 'confirmed'
          then 'paid-not-confirmed'
        when b.payment_status = 'refunded' and coalesce(pst.active, 0) > 0
          then 'refunded-with-active-pass'
        when b.payment_status = 'failed' and coalesce(pst.issued, 0) > 0
          then 'failed-with-pass'
        else 'event-ignored'
      end                                                as reason_code,
      b.*,
      coalesce(pst.issued, 0)                             as passes_issued,
      coalesce(pst.active, 0)                             as passes_active,
      coalesce(ev.n, 0)                                   as event_count
    from public.bookings b
    left join (
      select dp.booking_id,
             count(*)::integer                                   as issued,
             count(*) filter (where dp.status = 'active')::integer as active
      from public.digital_passes dp
      group by dp.booking_id
    ) pst on pst.booking_id = b.id
    left join (
      select pe.razorpay_order_id, count(*)::integer as n
      from public.payment_events pe
      where pe.outcome = 'ignored'
      group by pe.razorpay_order_id
    ) ev on ev.razorpay_order_id = b.razorpay_order_id
    where (b.payment_status = 'paid' and coalesce(pst.issued, 0) = 0)
       or (b.payment_status = 'paid' and b.booking_status <> 'confirmed')
       or (b.payment_status = 'refunded' and coalesce(pst.active, 0) > 0)
       or (b.payment_status = 'failed' and coalesce(pst.issued, 0) > 0)
       -- An event we could not act on: `order.paid` with no payment id, an amount
       -- that did not match, a delivery for an order we do not hold (PC005 and
       -- friends). Recorded rather than dropped, so it can be looked at.
       or (b.payment_status <> 'paid' and b.payment_status <> 'refunded' and coalesce(ev.n, 0) > 0)
  ),
  counted as (
    select c.*, count(*) over ()::integer as total_count from candidates c
  )
  select
    c.reason_code,
    case c.reason_code
      when 'paid-no-pass' then 'Paid, but no pass was ever issued'
      when 'paid-not-confirmed' then 'Paid, but the booking is not marked confirmed'
      when 'refunded-with-active-pass' then 'Refunded, but a pass is still active'
      when 'failed-with-pass' then 'A failed payment that nevertheless holds a pass'
      else 'A gateway event we could not act on'
    end,
    case c.reason_code
      when 'paid-no-pass' then 'Re-deliver the gateway event (Razorpay → Webhooks → resend) so the pass is issued and the guest can be admitted.'
      when 'paid-not-confirmed' then 'Check the booking on /admin/bookings, then re-deliver the gateway event.'
      when 'refunded-with-active-pass' then 'Cancel the pass before the gate opens, or the guest will be admitted on a refunded booking.'
      when 'failed-with-pass' then 'Cancel the pass, and check with the guest — the money did not arrive.'
      else 'Look at the delivery on /admin/payments: it belongs to no booking we hold, or the amount did not match.'
    end,
    c.id,
    c.booking_id,
    c.customer_name,
    case when p_include_contact then c.customer_mobile end,
    c.booking_status,
    c.payment_status,
    case when p_include_contact then c.total_amount end,
    e.currency,
    case when p_include_contact then c.razorpay_order_id end,
    case when p_include_contact then c.razorpay_payment_id end,
    d.event_date,
    c.passes_issued,
    c.passes_active,
    c.event_count,
    c.created_at,
    c.total_count
  from counted c
  join public.event_dates d on d.id = c.event_date_id
  join public.events e      on e.id = d.event_id
  order by c.created_at desc, c.id desc
  limit greatest(1, least(coalesce(p_limit, 25), 100));
$$;

comment on function public.admin_payment_attention(boolean, integer) is
  'Bookings whose payment state contradicts the rest of the row (paid with no pass, refunded with an active pass, a gateway event that could not be acted on), each with the reason and what to do. Contact details and gateway ids come back null when p_include_contact is false. service_role only.';

-- -----------------------------------------------------------------------------
-- 4. Every pass there is.
--
--    One row per issued pass, with its booking, its night and its gate entry. This is
--    the door list: who is expected, which ticket is which, and who is already inside.
--    The QR token is not selected — the credential that admits a guest is not this
--    screen's business, and there is no parameter that would make it so.
--
--    Ordered by when the pass was issued, then by booking and pass number, so the
--    passes of one booking stay together and in order across page boundaries. The
--    ordering is written the same way in the slice and in the final select; a list
--    whose pages are drawn in a different order than they were chosen is a list that
--    can show one pass twice and hide another.
-- -----------------------------------------------------------------------------
create or replace function public.admin_pass_list(
  p_query           text default null,
  p_status          text default null,
  p_check_in        text default null,
  p_event_date_id   uuid default null,
  p_from            date default null,
  p_to              date default null,
  p_include_contact boolean default true,
  p_limit           integer default 25,
  p_offset          integer default 0
)
returns table (
  pass_uuid           uuid,
  pass_id             text,
  pass_number         integer,
  pass_status         text,
  checked_in          boolean,
  checked_in_at       timestamptz,
  valid_date          date,
  gate                text,
  admitted_by         text,
  issued_at           timestamptz,
  booking_uuid        uuid,
  booking_id          text,
  booking_status      text,
  payment_status      text,
  customer_name       text,
  customer_mobile     text,
  pass_name           text,
  quantity            integer,
  number_of_people    integer,
  total_amount        integer,
  currency            text,
  event_name          text,
  start_time          time,
  end_time            time,
  passes_on_booking   integer,
  total_count         integer
)
language sql
stable
security definer
set search_path = public
as $$
  with params as (
    select
      nullif(left(btrim(coalesce(p_query, '')), 64), '') as q,
      public.admin_search_pattern(p_query)               as q_like,
      public.admin_search_digits(p_query)                as q_digits,
      greatest(1, least(coalesce(p_limit, 25), 100))     as page_size,
      greatest(0, coalesce(p_offset, 0))                 as page_offset,
      case when p_status in ('active', 'used', 'cancelled', 'expired')
           then p_status end                             as status,
      case when p_check_in in ('in', 'out') then p_check_in end as check_in,
      -- The night a filter asks for, resolved once. An id that matches no night
      -- resolves to null, and nothing matches a null night — the honest answer.
      (select d.event_date from public.event_dates d where d.id = p_event_date_id) as night
  ),
  matched as (
    select
      dp.id,
      dp.created_at,
      b.booking_id,
      dp.pass_number,
      count(*) over ()::integer as total_count
    from public.digital_passes dp
    join public.bookings b on b.id = dp.booking_id
    cross join params p
    where (
        p.q is null
        or dp.pass_id ilike '%' || p.q_like || '%'
        or b.booking_id ilike '%' || p.q_like || '%'
        or b.customer_name ilike '%' || p.q_like || '%'
        or b.customer_email ilike '%' || p.q_like || '%'
        or (p.q_digits <> '' and regexp_replace(b.customer_mobile, '\D', '', 'g') like '%' || p.q_digits || '%')
      )
      and (p.status is null or dp.status = p.status)
      -- "in" and "out" are about the pass's own flag, not about its status: a pass
      -- cancelled after the guest was admitted is still a pass that let somebody in.
      and (p.check_in is null
           or (p.check_in = 'in' and dp.checked_in)
           or (p.check_in = 'out' and not dp.checked_in))
      and (p.night is null or dp.valid_date = p.night)
      and (p_from is null or dp.valid_date >= p_from)
      and (p_to is null or dp.valid_date <= p_to)
  ),
  page as (
    select m.id, m.booking_id, m.pass_number, m.total_count
    from matched m
    order by m.created_at desc, m.booking_id desc, m.pass_number desc
    limit (select page_size from params)
    offset (select page_offset from params)
  )
  select
    dp.id,
    dp.pass_id,
    dp.pass_number,
    dp.status,
    dp.checked_in,
    dp.checked_in_at,
    dp.valid_date,
    ci.gate,
    coalesce(nullif(btrim(au.full_name), ''), au.email),
    dp.created_at,
    b.id,
    b.booking_id,
    b.booking_status,
    b.payment_status,
    b.customer_name,
    case when p_include_contact then b.customer_mobile end,
    pc.name,
    b.quantity,
    b.number_of_people,
    case when p_include_contact then b.total_amount end,
    e.currency,
    e.name,
    d.start_time,
    d.end_time,
    -- How many passes this booking holds in total: a door needs to know that the
    -- guest in front of them is pass 1 of 4, without opening the booking.
    (select count(*)::integer from public.digital_passes allp where allp.booking_id = b.id),
    pg.total_count
  from page pg
  join public.digital_passes dp on dp.id = pg.id
  join public.bookings b         on b.id = dp.booking_id
  -- The night the booking is for. The pass's own valid_date is the same date by
  -- construction (the payment function copies it), so this is a lookup, not a join
  -- that could drop a pass.
  join public.event_dates d      on d.id = b.event_date_id
  join public.events e           on e.id = d.event_id
  join public.pass_categories pc on pc.id = b.pass_category_id
  left join public.check_ins ci  on ci.digital_pass_id = dp.id
  left join public.admin_users au on au.id = ci.checked_in_by
  order by dp.created_at desc, b.booking_id desc, dp.pass_number desc;
$$;

comment on function public.admin_pass_list(text, text, text, uuid, date, date, boolean, integer, integer) is
  'Every issued pass, newest first: pass id, state, check-in time and gate, the booking and guest it belongs to, the night it is valid for, how many passes that booking holds and who admitted the guest. Contact details and amounts come back null when p_include_contact is false. The QR token is never returned. service_role only.';

-- -----------------------------------------------------------------------------
-- 5. The counts above the pass list.
--
--    Counted in the venue's days, like the dashboard, so "checked in today" means the
--    day it is at the gate.
--
--    Money is counted from the *bookings*, not from the join with passes: a booking
--    with four passes would otherwise be counted four times, and a screen that
--    overstates takings is worse than one that shows none.
-- -----------------------------------------------------------------------------
create or replace function public.admin_pass_summary(
  p_tz              text default 'UTC',
  p_include_contact boolean default true
)
returns table (
  passes_issued        integer,
  passes_active        integer,
  passes_used          integer,
  passes_cancelled     integer,
  passes_expired       integer,
  bookings_with_passes integer,
  checked_in_total     integer,
  checked_in_today     integer,
  last_check_in_at     timestamptz,
  gates_used           integer,
  passes_revenue       integer
)
language sql
stable
security definer
set search_path = public
as $$
  with pass_state as (
    select
      dp.booking_id,
      dp.status,
      dp.checked_in,
      ci.checked_in_at,
      ci.gate
    from public.digital_passes dp
    left join public.check_ins ci on ci.digital_pass_id = dp.id
  ),
  paid_for_passes as (
    -- Every paid booking that is holding at least one pass, counted once each.
    select coalesce(sum(b.total_amount), 0)::integer as revenue
    from public.bookings b
    where b.payment_status = 'paid'
      and exists (select 1 from public.digital_passes dp where dp.booking_id = b.id)
  )
  select
    pc.issued,
    pc.active,
    pc.used,
    pc.cancelled,
    pc.expired,
    pc.bookings,
    pc.checked_in,
    pc.today,
    pc.last_at,
    pc.gates,
    case when p_include_contact then pp.revenue end
  -- One row per counter, and the declared column order is the select order: PostgREST
  -- binds `returns table` by position, so a counter moved here and not there would be
  -- reported under the wrong name.
  from (
    select
      count(*)::integer                                             as issued,
      count(*) filter (where ps.status = 'active')::integer          as active,
      count(*) filter (where ps.status = 'used')::integer            as used,
      count(*) filter (where ps.status = 'cancelled')::integer       as cancelled,
      count(*) filter (where ps.status = 'expired')::integer         as expired,
      count(distinct ps.booking_id)::integer                        as bookings,
      count(*) filter (where ps.checked_in)::integer                 as checked_in,
      count(*) filter (where ps.checked_in_at is not null
                        and (ps.checked_in_at at time zone p_tz)::date
                            = (now() at time zone p_tz)::date)::integer as today,
      max(ps.checked_in_at)                                         as last_at,
      count(distinct ps.gate)::integer                              as gates
    from pass_state ps
  ) pc
  cross join paid_for_passes pp;
$$;

comment on function public.admin_pass_summary(text, boolean) is
  'The counts above the pass list: passes by state, bookings holding passes, check-ins today in the venue''s timezone, the last entry, how many gates have been used, and what the paid bookings behind those passes were worth — counted once per booking, and null when p_include_contact is false. service_role only.';

-- -----------------------------------------------------------------------------
-- 6. Grants. These read across bookings, passes, check-ins and payment events:
--    no browser session may call them, whatever key it holds.
-- -----------------------------------------------------------------------------
revoke execute on function public.admin_search_pattern(text) from public, anon, authenticated;
revoke execute on function public.admin_search_digits(text) from public, anon, authenticated;
revoke execute on function public.admin_payment_events(text, text, text, date, date, boolean, integer, integer) from public, anon, authenticated;
revoke execute on function public.admin_payment_attention(boolean, integer) from public, anon, authenticated;
revoke execute on function public.admin_payment_summary(boolean) from public, anon, authenticated;
revoke execute on function public.admin_pass_list(text, text, text, uuid, date, date, boolean, integer, integer) from public, anon, authenticated;
revoke execute on function public.admin_pass_summary(text, boolean) from public, anon, authenticated;

grant execute on function public.admin_search_pattern(text) to service_role;
grant execute on function public.admin_search_digits(text) to service_role;
grant execute on function public.admin_payment_events(text, text, text, date, date, boolean, integer, integer) to service_role;
grant execute on function public.admin_payment_attention(boolean, integer) to service_role;
grant execute on function public.admin_payment_summary(boolean) to service_role;
grant execute on function public.admin_pass_list(text, text, text, uuid, date, date, boolean, integer, integer) to service_role;
grant execute on function public.admin_pass_summary(text, boolean) to service_role;


-- ===========================================================================
-- 20260922091200_admin_pass_and_date_management.sql
-- ===========================================================================

-- =============================================================================
-- Garba Nights — admin pass and date management
--
-- Two screens, and one idea behind both: the organiser owns what is on sale, and
-- the database owns what that means.
--
--   1. event_dates gains the two things a night needs to be sellable — how many
--      seats are held back from online booking, and whether booking is open —
--      plus guards that make an impossible capacity unrepresentable.
--   2. pass_categories gains min_age, so "age restriction" is a fact on the pass
--      rather than a sentence in a description.
--   3. create_pending_booking and get_event_night_availability are replaced, so
--      the booking path and the public availability figure agree about held
--      seats and closed nights. One capacity rule, in two places that must
--      match, kept in step by being written the same way.
--   4. The admin functions: save/toggle a pass, save a night, set capacity,
--      open and close booking.
--
-- Where the rules live, and why:
--
--   * **Row invariants are constraints and a trigger.** capacity >= 1,
--     capacity_held >= 0, capacity_held <= capacity, min_age in range: true of
--     any row at any time, so the database refuses to hold a row that breaks
--     them, whatever wrote it — this file, a migration, the SQL editor.
--   * **The data-dependent rule is the same trigger, because it must hold for
--     every write.** "Capacity may never drop below the people already paid for
--     the night" needs a count, and a count in a trigger is a query — that is
--     fine. It is written as *never make the shortfall worse* rather than
--     *always be sufficient*, because a night can legitimately end up
--     over-subscribed (a booking that pays after the night filled is honoured
--     with an organiser note, see 20260922090500_payments.sql) and an organiser
--     must still be able to raise the capacity, cancel the night or edit a note
--     on it.
--   * **Concurrency is row locks, not hope.** Every admin write locks the night
--     row `for update` before it counts, exactly as create_pending_booking
--     does, so an admin lowering capacity and a customer paying for the last
--     seat cannot interleave: one of them waits for the other.
--
-- Error codes (the app maps these to a field, not to prose):
--
--   PT001 capacity_below_one        PT007 night_not_found
--   PT002 capacity_held_negative    PT008 night_time_order
--   PT003 capacity_held_above_cap   PT009 night_date_required
--   PT004 capacity_below_taken      PT010 night_status_invalid
--   PT005 night_date_locked         PT011 notes_too_long
--   PT006 night_duplicate
--
--   PC001 pass_name_invalid         PC007 pass_age_invalid
--   PC002 pass_code_invalid         PC008 pass_not_found
--   PC003 pass_code_duplicate       PC009 pass_composition_invalid
--   PC004 pass_price_invalid        PC010 pass_not_configured
--   PC005 pass_people_invalid       PC011 pass_sort_order_invalid
--   PC006 pass_max_per_booking_invalid
-- =============================================================================


-- -----------------------------------------------------------------------------
-- 1. event_dates: seats held back, and whether booking is open
-- -----------------------------------------------------------------------------
alter table public.event_dates
  add column if not exists capacity_held integer not null default 0,
  add column if not exists booking_open  boolean not null default true;

comment on column public.event_dates.capacity_held is
  'Seats withheld from online booking (gate sales, sponsors, crew). Available = capacity - capacity_held - paid people.';
comment on column public.event_dates.booking_open is
  'Whether booking is open on this night. Closing it stops new bookings without cancelling the night.';

-- Constraints rather than defaults alone: the row cannot be made impossible even by
-- a hand-written INSERT that names the columns.
alter table public.event_dates drop constraint if exists event_dates_capacity_held_range;
alter table public.event_dates
  add constraint event_dates_capacity_held_range check (capacity_held >= 0);

alter table public.event_dates drop constraint if exists event_dates_capacity_held_within_capacity;
alter table public.event_dates
  add constraint event_dates_capacity_held_within_capacity check (capacity_held <= capacity);


-- -----------------------------------------------------------------------------
-- 2. pass_categories: age restriction
-- -----------------------------------------------------------------------------
-- 0 means "no restriction", which is what every pass sold today means. An integer
-- rather than free text because "18+" is a rule a door can apply, and a rule the
-- database can check.
alter table public.pass_categories
  add column if not exists min_age integer not null default 0;

comment on column public.pass_categories.min_age is
  'Minimum age in years for this pass; 0 means no age restriction. Shown on the pass card and checked at the door.';

alter table public.pass_categories drop constraint if exists pass_categories_min_age_range;
alter table public.pass_categories
  add constraint pass_categories_min_age_range check (min_age between 0 and 120);


-- -----------------------------------------------------------------------------
-- 3. The guard on a night
--
-- Fires before every INSERT and UPDATE of event_dates — the admin function, a
-- migration, or somebody in the SQL editor. It knows two things: what the row
-- must look like, and what the row must not take away from people who have
-- already paid.
-- -----------------------------------------------------------------------------
create or replace function public.event_dates_guard_capacity()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_paid      integer;
  v_old_room  integer;
  v_new_room  integer;
begin
  -- 1. The row itself. These are also table constraints; they are repeated here so
  -- the app receives an error code it can attach to a field instead of a raw
  -- constraint violation.
  if new.capacity is null or new.capacity < 1 then
    raise exception 'capacity_below_one' using errcode = 'PT001';
  end if;

  if new.capacity_held is null or new.capacity_held < 0 then
    raise exception 'capacity_held_negative' using errcode = 'PT002';
  end if;

  if new.capacity_held > new.capacity then
    raise exception 'capacity_held_above_capacity' using errcode = 'PT003',
      detail = new.capacity::text;
  end if;

  -- 2. The night's own bookings. Counted from paid bookings only, the same rule
  -- the booking path and the public availability figure use: a pending booking
  -- does not hold a seat until the money is verified.
  select coalesce(sum(b.number_of_people), 0)::integer
    into v_paid
  from public.bookings b
  where b.event_date_id = new.id
    and b.payment_status = 'paid';

  if v_paid > 0 then
    -- Room left for the people who have paid, after the seats held back.
    v_new_room := new.capacity - new.capacity_held;

    -- An UPDATE that does not make things worse is always allowed: raising the
    -- capacity, cancelling the night, correcting a time. An INSERT has no old row
    -- and no bookings, so it can only be measured as it stands.
    v_old_room := case when tg_op = 'UPDATE' then old.capacity - old.capacity_held else v_new_room end;

    if v_new_room < v_paid and v_new_room < v_old_room then
      -- detail carries the lowest capacity this night may now have, so the screen
      -- can say "at least 82" rather than "invalid".
      raise exception 'capacity_below_taken' using errcode = 'PT004',
        detail = (v_paid + new.capacity_held)::text;
    end if;
  end if;

  -- 3. A night that has been paid for keeps its date. Passes are issued with the
  -- night's date printed on them and scanned against it, so moving the night would
  -- silently invalidate them; the organiser moves the bookings, not the night.
  if tg_op = 'UPDATE' and new.event_date is distinct from old.event_date and v_paid > 0 then
    raise exception 'night_date_locked' using errcode = 'PT005', detail = v_paid::text;
  end if;

  return new;
end;
$$;

drop trigger if exists event_dates_guard_capacity on public.event_dates;
create trigger event_dates_guard_capacity
  before insert or update on public.event_dates
  for each row execute function public.event_dates_guard_capacity();

comment on function public.event_dates_guard_capacity() is
  'Refuses a night whose capacity is impossible (PT001-PT003) and any edit that would take seats away from people who have already paid (PT004), or move a night that has paid bookings to another date (PT005).';


-- -----------------------------------------------------------------------------
-- 4. The booking path, restated with held seats and closed booking
--
-- create_pending_booking is restated here rather than patched from where it was last
-- defined (20260922090500_payments.sql): it is the one place that decides whether a
-- booking may exist, and it has to read the two new columns. The body below is that
-- definition, verbatim apart from three lines — the columns the night lock fetches,
-- the closed-booking refusal, and the seats held back taken off the available count.
-- Everything else is unchanged: the night row is still locked first, the price still
-- comes from pass_categories, the amount is still never accepted from the caller, and
-- the idempotency and capacity behaviour are exactly as they were.
-- -----------------------------------------------------------------------------
create or replace function public.create_pending_booking(
  p_event_id         uuid,
  p_event_date_id    uuid,
  p_pass_category_id uuid,
  p_customer_name    text,
  p_customer_mobile  text,
  p_customer_email   text,
  p_quantity         integer,
  p_number_of_people integer,
  p_idempotency_key  text default null
)
returns table (
  booking_uuid     uuid,
  booking_reference text,
  public_token     uuid,
  booking_status   text,
  payment_status   text,
  quantity         integer,
  number_of_people integer,
  subtotal         integer,
  total_amount     integer,
  event_id         uuid,
  event_date_id    uuid,
  event_date       date,
  start_time       time,
  end_time         time,
  pass_category_id uuid,
  pass_name        text,
  pass_composition text,
  currency         text,
  razorpay_order_id text,
  created_at       timestamptz,
  was_existing     boolean
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_night       record;
  v_pass        record;
  v_event       record;
  v_existing    record;
  v_booked      integer;
  v_remaining   integer;
  v_required    integer;
  v_booking_id  uuid;
  v_reference   text;
begin
  -- Idempotency: has this attempt already produced a booking?
  if p_idempotency_key is not null and length(btrim(p_idempotency_key)) > 0 then
    select b.id into v_existing
    from public.bookings b
    where b.idempotency_key = btrim(p_idempotency_key);

    if found then
      return query
        select b.id, b.booking_id, b.public_token, b.booking_status, b.payment_status, b.quantity,
               b.number_of_people, b.subtotal, b.total_amount, d.event_id, d.id, d.event_date,
               d.start_time, d.end_time, p.id, p.name, p.composition, e.currency,
               b.razorpay_order_id, b.created_at, true
        from public.bookings b
        join public.event_dates d on d.id = b.event_date_id
        join public.pass_categories p on p.id = b.pass_category_id
        join public.events e on e.id = d.event_id
        where b.id = v_existing.id;

      return;
    end if;
  end if;

  -- Lock the night: concurrent attempts for the same night queue here, so the
  -- capacity read below cannot be stale.
  select d.id, d.event_id, d.event_date, d.status, d.capacity, d.capacity_held,
         d.booking_open, d.start_time, d.end_time
    into v_night
  from public.event_dates d
  where d.id = p_event_date_id
  for update;

  if not found then
    raise exception 'night_not_found' using errcode = 'PB006';
  end if;

  if v_night.event_id <> p_event_id then
    raise exception 'night_not_found' using errcode = 'PB006';
  end if;

  select e.id, e.name, e.status, e.currency into v_event
  from public.events e
  where e.id = p_event_id;

  if not found or v_event.status <> 'published' then
    raise exception 'night_not_bookable' using errcode = 'PB002';
  end if;

  if v_night.status <> 'scheduled' then
    raise exception 'night_not_bookable' using errcode = 'PB002';
  end if;

  -- An organiser can close booking on a night without cancelling it (gate sales
  -- only, a private hire, a capacity recount). Same verdict, same code: from the
  -- booking flow's point of view the night is simply not on sale.
  if v_night.booking_open is not true then
    raise exception 'night_not_bookable' using errcode = 'PB002';
  end if;

  select p.id, p.name, p.composition, p.price_inr, p.number_of_people, p.max_per_booking, p.is_active
    into v_pass
  from public.pass_categories p
  where p.id = p_pass_category_id;

  if not found or v_pass.is_active is not true then
    raise exception 'pass_not_available' using errcode = 'PB003';
  end if;

  if not exists (
    select 1 from public.pass_categories p
    where p.id = p_pass_category_id and p.event_id = p_event_id
  ) then
    raise exception 'pass_not_available' using errcode = 'PB003';
  end if;

  if p_quantity is null or p_quantity < 1 or p_quantity > v_pass.max_per_booking then
    raise exception 'quantity_invalid' using errcode = 'PB004', detail = v_pass.max_per_booking::text;
  end if;

  v_required := p_quantity * v_pass.number_of_people;

  if p_number_of_people is null or p_number_of_people <> v_required then
    raise exception 'people_mismatch' using errcode = 'PB005', detail = v_required::text;
  end if;

  -- Capacity, counted the same way as the public availability function: paid
  -- bookings only, with the seats the organiser has held back removed from what is
  -- on sale. A pending booking does not hold a place until it is paid.
  select coalesce(sum(b.number_of_people) filter (where b.payment_status = 'paid'), 0)::integer
    into v_booked
  from public.bookings b
  where b.event_date_id = p_event_date_id;

  -- Seats an organiser has held back are subtracted before the booking is measured
  -- against what is left: a night with 1,000 seats and 50 held has 950 on sale.
  v_remaining := greatest(v_night.capacity - v_night.capacity_held - v_booked, 0);

  if v_required > v_remaining then
    raise exception 'capacity_unavailable' using errcode = 'PB001', detail = v_remaining::text;
  end if;

  -- Same content, brand-new key inside the double-submit window (a page reload
  -- loses the key): treat it as the same attempt instead of creating a second
  -- booking. Paid or older bookings are never reused.
  select b.id into v_existing
  from public.bookings b
  where b.event_date_id = p_event_date_id
    and b.pass_category_id = p_pass_category_id
    and b.customer_mobile = p_customer_mobile
    and b.quantity = p_quantity
    and b.booking_status = 'pending'
    and b.payment_status = 'unpaid'
    and b.created_at > now() - interval '15 minutes'
  order by b.created_at desc
  limit 1;

  if found then
    return query
      select b.id, b.booking_id, b.public_token, b.booking_status, b.payment_status, b.quantity,
             b.number_of_people, b.subtotal, b.total_amount, d.event_id, d.id, d.event_date,
             d.start_time, d.end_time, p.id, p.name, p.composition, e.currency,
             b.razorpay_order_id, b.created_at, true
      from public.bookings b
      join public.event_dates d on d.id = b.event_date_id
      join public.pass_categories p on p.id = b.pass_category_id
      join public.events e on e.id = d.event_id
      where b.id = v_existing.id;

    return;
  end if;

  -- number_of_people, subtotal and total_amount are deliberately not part of the
  -- INSERT column list: the set_booking_amounts() trigger computes all three from
  -- pass_categories before the row is written.
  insert into public.bookings (
    customer_name, customer_mobile, customer_email,
    event_date_id, pass_category_id,
    quantity, booking_status, payment_status, idempotency_key
  )
  values (
    btrim(p_customer_name), p_customer_mobile, p_customer_email,
    p_event_date_id, p_pass_category_id,
    p_quantity, 'pending', 'unpaid',
    nullif(btrim(coalesce(p_idempotency_key, '')), '')
  )
  returning id, bookings.booking_id into v_booking_id, v_reference;

  return query
    select b.id, b.booking_id, b.public_token, b.booking_status, b.payment_status, b.quantity,
           b.number_of_people, b.subtotal, b.total_amount, d.event_id, d.id, d.event_date,
           d.start_time, d.end_time, p.id, p.name, p.composition, e.currency,
           b.razorpay_order_id, b.created_at, false
    from public.bookings b
    join public.event_dates d on d.id = b.event_date_id
    join public.pass_categories p on p.id = b.pass_category_id
    join public.events e on e.id = d.event_id
    where b.id = v_booking_id;
end;
$$;

comment on function public.create_pending_booking(uuid, uuid, uuid, text, text, text, integer, integer, text) is
  'Creates one pending/unpaid booking atomically: locks the night, re-reads capacity from paid bookings and the seats held back, refuses a night whose booking is closed, reads the price from pass_categories and ignores any client-supplied amount. Service role only — browsers cannot call it.';

revoke all on function public.create_pending_booking(uuid, uuid, uuid, text, text, text, integer, integer, text) from public;
revoke all on function public.create_pending_booking(uuid, uuid, uuid, text, text, text, integer, integer, text) from anon, authenticated;
grant execute on function public.create_pending_booking(uuid, uuid, uuid, text, text, text, integer, integer, text) to service_role;


-- -----------------------------------------------------------------------------
-- 5. Public availability, with the same arithmetic
--
-- The public site must not be able to promise a seat the booking path will refuse,
-- so this function and create_pending_booking compute "available" identically:
-- capacity − held − paid people. The return type gains three columns, so the
-- function is dropped and recreated rather than replaced.
-- -----------------------------------------------------------------------------
drop function if exists public.get_event_night_availability(uuid);

create function public.get_event_night_availability(p_event_id uuid)
returns table (
  event_date_id   uuid,
  event_date      date,
  start_time      time,
  end_time        time,
  night_status    text,
  capacity        integer,
  capacity_held   integer,
  booked_people   integer,
  remaining       integer,
  is_fully_booked boolean,
  is_booking_open boolean,
  is_bookable     boolean
)
language sql
stable
security definer
set search_path = public
as $$
  with night as (
    select
      d.id,
      d.event_date,
      d.start_time,
      d.end_time,
      d.status,
      d.capacity,
      d.capacity_held,
      d.booking_open,
      coalesce(
        sum(b.number_of_people) filter (where b.payment_status = 'paid'),
        0
      )::integer as booked_people
    from public.event_dates d
    left join public.bookings b on b.event_date_id = d.id
    where d.event_id = p_event_id
      and exists (
        select 1 from public.events e
        where e.id = p_event_id and e.status = 'published'
      )
    group by d.id, d.event_date, d.start_time, d.end_time, d.status, d.capacity,
             d.capacity_held, d.booking_open
  )
  select
    n.id,
    n.event_date,
    n.start_time,
    n.end_time,
    n.status,
    n.capacity,
    n.capacity_held,
    n.booked_people,
    greatest(n.capacity - n.capacity_held - n.booked_people, 0),
    (n.status = 'sold_out' or n.booked_people + n.capacity_held >= n.capacity),
    n.booking_open,
    (n.status = 'scheduled'
      and n.booking_open
      and n.booked_people + n.capacity_held < n.capacity)
  from night n
  order by n.event_date;
$$;

comment on function public.get_event_night_availability(uuid) is
  'Published events only. One row per night with capacity, the seats held back from online booking, the paid people, and what is actually left on sale. Counts only — a visitor can never read a booking row.';

revoke execute on function public.get_event_night_availability(uuid) from public;
grant execute on function public.get_event_night_availability(uuid) to anon, authenticated, service_role;


-- The seed's codes are lower case ("girls-2") and an organiser may type "Girls-2";
-- both are one pass, quoted one way at the door. A case-folded unique index makes
-- that a fact rather than a convention, for every writer — this function, a
-- migration, or the SQL editor.
create unique index if not exists pass_categories_event_code_ci_idx
  on public.pass_categories (event_id, upper(code));


-- -----------------------------------------------------------------------------
-- 6. Shared helpers for the two admin save functions
-- -----------------------------------------------------------------------------

-- The event a pass or a night belongs to, when the caller did not name one.
create or replace function public.admin_default_event_id()
returns uuid
language sql
stable
security definer
set search_path = public
as $$
  select e.id
  from public.events e
  order by (e.status = 'published') desc, e.created_at
  limit 1;
$$;

comment on function public.admin_default_event_id() is
  'The event the admin screens operate on: the published one, or the oldest if none is published.';

revoke all on function public.admin_default_event_id() from public;
revoke all on function public.admin_default_event_id() from anon, authenticated;
grant execute on function public.admin_default_event_id() to service_role;


-- -----------------------------------------------------------------------------
-- 7. The pass catalogue
--
-- Everything an organiser needs to run the ticket desk, and the numbers they need
-- to decide with: what is on sale, at what price, for how many people, how many
-- have been sold, and how much they have taken.
-- -----------------------------------------------------------------------------
create or replace function public.admin_pass_catalogue(p_event_id uuid default null)
returns table (
  pass_uuid        uuid,
  code             text,
  name             text,
  composition      text,
  description      text,
  price_inr        integer,
  number_of_people integer,
  max_per_booking  integer,
  min_age          integer,
  is_active        boolean,
  sort_order       integer,
  bookings_count   integer,
  paid_bookings    integer,
  passes_issued    integer,
  people_sold      integer,
  revenue_inr      integer,
  created_at       timestamptz,
  updated_at       timestamptz
)
language sql
stable
security definer
set search_path = public
as $$
  with target as (
    select coalesce(p_event_id, public.admin_default_event_id()) as event_id
  ),
  sold as (
    select
      b.pass_category_id,
      count(*)::integer                                            as bookings_count,
      count(*) filter (where b.payment_status = 'paid')::integer    as paid_bookings,
      coalesce(sum(b.number_of_people) filter (where b.payment_status = 'paid'), 0)::integer as people_sold,
      coalesce(sum(b.total_amount) filter (where b.payment_status = 'paid'), 0)::integer      as revenue_inr
    from public.bookings b
    where b.pass_category_id is not null
    group by b.pass_category_id
  ),
  issued as (
    select b.pass_category_id, count(dp.id)::integer as passes_issued
    from public.bookings b
    join public.digital_passes dp on dp.booking_id = b.id
    where b.payment_status = 'paid'
    group by b.pass_category_id
  )
  select
    p.id,
    p.code,
    p.name,
    p.composition,
    p.description,
    p.price_inr,
    p.number_of_people,
    p.max_per_booking,
    p.min_age,
    p.is_active,
    p.sort_order,
    coalesce(s.bookings_count, 0),
    coalesce(s.paid_bookings, 0),
    coalesce(i.passes_issued, 0),
    coalesce(s.people_sold, 0),
    coalesce(s.revenue_inr, 0),
    p.created_at,
    p.updated_at
  from public.pass_categories p
  cross join target t
  left join sold s on s.pass_category_id = p.id
  left join issued i on i.pass_category_id = p.id
  where p.event_id = t.event_id
  order by p.sort_order, p.price_inr, p.name;
$$;

comment on function public.admin_pass_catalogue(uuid) is
  'Every pass type for an event — on sale or not — with what has been sold on it: bookings, paid bookings, passes issued, people and takings. Read-only; the writes below are narrow functions on purpose.';

revoke all on function public.admin_pass_catalogue(uuid) from public;
revoke all on function public.admin_pass_catalogue(uuid) from anon, authenticated;
grant execute on function public.admin_pass_catalogue(uuid) to service_role;


-- -----------------------------------------------------------------------------
-- 8. Create or edit a pass
--
-- One function for both, because the validation is identical and the only
-- difference is whether the row exists yet. Every rule is checked here, in the
-- order a form reads: name, code, composition, price, people, per-booking limit,
-- age. An invalid value raises with a code the app turns into a message under the
-- field that caused it.
-- -----------------------------------------------------------------------------
create or replace function public.admin_save_pass_category(
  p_id                uuid,
  p_event_id          uuid,
  p_code              text,
  p_name              text,
  p_composition       text,
  p_description       text,
  p_price_inr         integer,
  p_number_of_people  integer,
  p_max_per_booking   integer,
  p_min_age           integer,
  p_sort_order        integer,
  p_is_active         boolean
)
returns table (
  pass_uuid        uuid,
  code             text,
  name             text,
  composition      text,
  description      text,
  price_inr        integer,
  number_of_people integer,
  max_per_booking  integer,
  min_age          integer,
  is_active        boolean,
  sort_order       integer,
  created_at       timestamptz,
  updated_at       timestamptz
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_event_id uuid := coalesce(p_event_id, public.admin_default_event_id());
  v_code     text := btrim(coalesce(p_code, ''));
  v_name     text := btrim(coalesce(p_name, ''));
  v_compose  text := btrim(coalesce(p_composition, ''));
  v_id       uuid := p_id;
  v_age      integer := coalesce(p_min_age, 0);
  v_order    integer := coalesce(p_sort_order, 0);
  v_active   boolean := coalesce(p_is_active, true);
begin
  if v_event_id is null then
    raise exception 'pass_not_configured' using errcode = 'PC010';
  end if;

  if v_name = '' or length(v_name) > 60 then
    raise exception 'pass_name_invalid' using errcode = 'PC001', detail = 'name';
  end if;

  -- The code is the stable, human-quotable handle ("girls-2", "Squad-4"). Spaces and
  -- underscores become dashes so it is one word at the desk, and the organiser's own
  -- capitalisation is kept — "Family Pass" stays "Family-Pass" rather than being
  -- shouted back at them. What is *not* allowed is two codes that differ only by
  -- case: the case-folded unique index added above makes that a fact for every
  -- writer, so "Family-Pass" and "family-pass" cannot become two rows at two prices.
  v_code := replace(replace(v_code, ' ', '-'), '_', '-');

  if v_code !~ '^[A-Za-z0-9-]{2,24}$' then
    raise exception 'pass_code_invalid' using errcode = 'PC002', detail = 'code';
  end if;

  if v_compose = '' or length(v_compose) > 80 then
    raise exception 'pass_composition_invalid' using errcode = 'PC009', detail = 'composition';
  end if;

  -- The price is whole rupees the organiser sets; Razorpay is billed in paise from
  -- it. Refusing 0 is deliberate: a free pass is a marketing decision that needs a
  -- payment method that does not exist here, and a typo would be worse.
  if p_price_inr is null or p_price_inr < 1 or p_price_inr > 500000 then
    raise exception 'pass_price_invalid' using errcode = 'PC004', detail = 'price_inr';
  end if;

  if p_number_of_people is null or p_number_of_people < 1 or p_number_of_people > 50 then
    raise exception 'pass_people_invalid' using errcode = 'PC005', detail = 'number_of_people';
  end if;

  if p_max_per_booking is null or p_max_per_booking < 1 or p_max_per_booking > 100 then
    raise exception 'pass_max_per_booking_invalid' using errcode = 'PC006', detail = 'max_per_booking';
  end if;

  if v_age < 0 or v_age > 120 then
    raise exception 'pass_age_invalid' using errcode = 'PC007', detail = 'min_age';
  end if;

  if v_order < 0 or v_order > 9999 then
    raise exception 'pass_sort_order_invalid' using errcode = 'PC011', detail = 'sort_order';
  end if;

  if v_id is null then
    begin
      insert into public.pass_categories (
        event_id, code, name, composition, description,
        price_inr, number_of_people, max_per_booking, min_age, sort_order, is_active
      )
      values (
        v_event_id, v_code, v_name, v_compose, nullif(btrim(coalesce(p_description, '')), ''),
        p_price_inr, p_number_of_people, p_max_per_booking, v_age, v_order, v_active
      )
      returning id into v_id;
    exception
      when unique_violation then
        raise exception 'pass_code_duplicate' using errcode = 'PC003', detail = 'code';
    end;
  else
    -- The event is not reassignable: a pass that has been sold belongs to the event
    -- it was sold for, and moving it would rewrite history.
    update public.pass_categories p
       set code             = v_code,
           name             = v_name,
           composition      = v_compose,
           description      = nullif(btrim(coalesce(p_description, '')), ''),
           price_inr        = p_price_inr,
           number_of_people = p_number_of_people,
           max_per_booking  = p_max_per_booking,
           min_age          = v_age,
           sort_order       = v_order,
           is_active        = v_active
     where p.id = v_id
       and p.event_id = v_event_id;

    if not found then
      raise exception 'pass_not_found' using errcode = 'PC008';
    end if;
  end if;

  return query
    select c.id, c.code, c.name, c.composition, c.description,
           c.price_inr, c.number_of_people, c.max_per_booking, c.min_age,
           c.is_active, c.sort_order, c.created_at, c.updated_at
    from public.pass_categories c
    where c.id = v_id;
end;
$$;

comment on function public.admin_save_pass_category(uuid, uuid, text, text, text, text, integer, integer, integer, integer, integer, boolean) is
  'Creates (p_id null) or updates one pass type, with every rule in the database rather than the form: name and composition required, code normalised and unique per event, price 1..500000 rupees, people 1..50, at most 100 per booking, age 0..120. Error codes PC001-PC011 name the offending field.';

revoke all on function public.admin_save_pass_category(uuid, uuid, text, text, text, text, integer, integer, integer, integer, integer, boolean) from public;
revoke all on function public.admin_save_pass_category(uuid, uuid, text, text, text, text, integer, integer, integer, integer, integer, boolean) from anon, authenticated;
grant execute on function public.admin_save_pass_category(uuid, uuid, text, text, text, text, integer, integer, integer, integer, integer, boolean) to service_role;


-- -----------------------------------------------------------------------------
-- 9. Enable or disable a pass
--
-- Its own function so the control that takes a pass off sale cannot rewrite the
-- price, the age or the composition on its way past.
-- -----------------------------------------------------------------------------
create or replace function public.admin_set_pass_category_active(
  p_id        uuid,
  p_is_active boolean
)
returns table (
  pass_uuid  uuid,
  code       text,
  name       text,
  is_active  boolean,
  updated_at timestamptz
)
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_id is null or p_is_active is null then
    raise exception 'pass_not_found' using errcode = 'PC008';
  end if;

  update public.pass_categories p
     set is_active = p_is_active
   where p.id = p_id;

  if not found then
    raise exception 'pass_not_found' using errcode = 'PC008';
  end if;

  return query
    select c.id, c.code, c.name, c.is_active, c.updated_at
    from public.pass_categories c
    where c.id = p_id;
end;
$$;

comment on function public.admin_set_pass_category_active(uuid, boolean) is
  'Takes one pass on or off sale. Deliberately narrow: nothing else about the pass is touched, and nothing is deleted — a pass with bookings on it stays as the record of what was sold.';

revoke all on function public.admin_set_pass_category_active(uuid, boolean) from public;
revoke all on function public.admin_set_pass_category_active(uuid, boolean) from anon, authenticated;
grant execute on function public.admin_set_pass_category_active(uuid, boolean) to service_role;


-- -----------------------------------------------------------------------------
-- 10. The nights
--
-- Same shape as the pass catalogue: one read that carries the numbers an organiser
-- decides with, so the screen never has to count anything itself.
-- -----------------------------------------------------------------------------
create or replace function public.admin_event_dates(p_event_id uuid default null)
returns table (
  date_uuid        uuid,
  event_date       date,
  start_time       time,
  end_time         time,
  night_status     text,
  capacity         integer,
  capacity_held    integer,
  booking_open     boolean,
  notes            text,
  booked_people    integer,
  booked_bookings  integer,
  passes_issued    integer,
  seats_on_sale    integer,
  seats_available  integer,
  over_committed   boolean,
  is_full          boolean,
  created_at       timestamptz,
  updated_at       timestamptz
)
language sql
stable
security definer
set search_path = public
as $$
  with target as (
    select coalesce(p_event_id, public.admin_default_event_id()) as event_id
  ),
  taken as (
    select
      b.event_date_id,
      coalesce(sum(b.number_of_people) filter (where b.payment_status = 'paid'), 0)::integer as booked_people,
      count(*) filter (where b.payment_status = 'paid')::integer                              as booked_bookings
    from public.bookings b
    group by b.event_date_id
  ),
  issued as (
    select b.event_date_id, count(dp.id)::integer as passes_issued
    from public.bookings b
    join public.digital_passes dp on dp.booking_id = b.id
    where b.payment_status = 'paid'
    group by b.event_date_id
  )
  select
    d.id,
    d.event_date,
    d.start_time,
    d.end_time,
    d.status,
    d.capacity,
    d.capacity_held,
    d.booking_open,
    d.notes,
    coalesce(t.booked_people, 0),
    coalesce(t.booked_bookings, 0),
    coalesce(i.passes_issued, 0),
    -- What is on sale, and what is left of it. Both are computed here rather than
    -- in the screen: a night's arithmetic is the database's, once.
    greatest(d.capacity - d.capacity_held, 0),
    greatest(d.capacity - d.capacity_held - coalesce(t.booked_people, 0), 0),
    (coalesce(t.booked_people, 0) + d.capacity_held > d.capacity),
    (d.status = 'sold_out' or coalesce(t.booked_people, 0) + d.capacity_held >= d.capacity),
    d.created_at,
    d.updated_at
  from public.event_dates d
  cross join target g
  left join taken t on t.event_date_id = d.id
  left join issued i on i.event_date_id = d.id
  where d.event_id = g.event_id
  order by d.event_date;
$$;

comment on function public.admin_event_dates(uuid) is
  'Every night of an event with what is on sale and what is left: capacity, seats held back, paid people, passes issued, seats available, and whether the night is over-committed or full. Aggregated in SQL so the screen counts nothing.';

revoke all on function public.admin_event_dates(uuid) from public;
revoke all on function public.admin_event_dates(uuid) from anon, authenticated;
grant execute on function public.admin_event_dates(uuid) to service_role;


-- -----------------------------------------------------------------------------
-- 11. Add or edit a night
--
-- The row is locked before anything is counted, so a capacity this function agrees
-- to cannot be made wrong by a payment landing in the next millisecond: the
-- customer's booking is holding the same lock.
-- -----------------------------------------------------------------------------
create or replace function public.admin_save_event_date(
  p_id            uuid,
  p_event_id      uuid,
  p_event_date    date,
  p_start_time    time,
  p_end_time      time,
  p_capacity      integer,
  p_capacity_held integer,
  p_status        text,
  p_booking_open  boolean,
  p_notes         text
)
returns table (
  date_uuid    uuid,
  event_date   date,
  start_time   time,
  end_time     time,
  night_status text,
  capacity     integer,
  capacity_held integer,
  booking_open boolean,
  notes        text,
  booked_people integer,
  seats_available integer,
  updated_at   timestamptz
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_event_id uuid := coalesce(p_event_id, public.admin_default_event_id());
  v_id       uuid := p_id;
  v_status   text := coalesce(nullif(btrim(coalesce(p_status, '')), ''), 'scheduled');
  v_held     integer := coalesce(p_capacity_held, 0);
  v_open     boolean := coalesce(p_booking_open, true);
  v_paid     integer;
begin
  if v_event_id is null then
    raise exception 'night_not_found' using errcode = 'PT007';
  end if;

  if p_event_date is null then
    raise exception 'night_date_required' using errcode = 'PT009', detail = 'event_date';
  end if;

  if p_capacity is null or p_capacity < 1 then
    raise exception 'capacity_below_one' using errcode = 'PT001', detail = 'capacity';
  end if;

  if v_held < 0 then
    raise exception 'capacity_held_negative' using errcode = 'PT002', detail = 'capacity_held';
  end if;

  if v_held > p_capacity then
    raise exception 'capacity_held_above_capacity' using errcode = 'PT003', detail = 'capacity_held';
  end if;

  if v_status not in ('scheduled', 'sold_out', 'cancelled', 'completed') then
    raise exception 'night_status_invalid' using errcode = 'PT010', detail = 'status';
  end if;

  if p_start_time is not null and p_end_time is not null and p_end_time <= p_start_time then
    raise exception 'night_time_order' using errcode = 'PT008', detail = 'end_time';
  end if;

  -- 11.1 An existing night is locked before it is measured, so the count below
  -- cannot be stale.
  if v_id is not null then
    perform 1
      from public.event_dates d
     where d.id = v_id and d.event_id = v_event_id
     for update;

    if not found then
      raise exception 'night_not_found' using errcode = 'PT007';
    end if;
  end if;

  -- 11.2 Capacity may not be lowered below the seats already paid for (plus the
  -- ones held back): that is what would make availability negative. The guard
  -- trigger enforces the same rule for any other writer; this carries the numbers
  -- so the message can say what the floor is.
  select coalesce(sum(b.number_of_people) filter (where b.payment_status = 'paid'), 0)::integer
    into v_paid
  from public.bookings b
  where b.event_date_id = v_id;

  if v_paid + v_held > p_capacity then
    raise exception 'capacity_below_taken' using errcode = 'PT004',
      detail = (v_paid + v_held)::text;
  end if;

  if v_id is null then
    begin
      insert into public.event_dates (
        event_id, event_date, start_time, end_time, capacity, capacity_held,
        status, booking_open, notes
      )
      values (
        v_event_id, p_event_date, p_start_time, p_end_time, p_capacity, v_held,
        v_status, v_open, nullif(btrim(coalesce(p_notes, '')), '')
      )
      returning id into v_id;
    exception
      when unique_violation then
        raise exception 'night_duplicate' using errcode = 'PT006', detail = 'event_date';
    end;
  else
    begin
      update public.event_dates d
         set event_date    = p_event_date,
             start_time    = p_start_time,
             end_time      = p_end_time,
             capacity      = p_capacity,
             capacity_held = v_held,
             status        = v_status,
             booking_open  = v_open,
             notes         = nullif(btrim(coalesce(p_notes, '')), '')
       where d.id = v_id;
    exception
      when unique_violation then
        -- Another night of this event already holds that date.
        raise exception 'night_duplicate' using errcode = 'PT006', detail = 'event_date';
    end;
  end if;

  return query
    select d.id, d.event_date, d.start_time, d.end_time, d.status, d.capacity,
           d.capacity_held, d.booking_open, d.notes,
           coalesce((select sum(b.number_of_people) from public.bookings b
                      where b.event_date_id = d.id and b.payment_status = 'paid'), 0)::integer,
           -- Cast because sum() is bigint and both return columns are integer: without
           -- it Postgres refuses the row at RETURN QUERY time, not at call time.
           (greatest(d.capacity - d.capacity_held
                     - coalesce((select sum(b.number_of_people) from public.bookings b
                                  where b.event_date_id = d.id and b.payment_status = 'paid'), 0), 0))::integer,
           d.updated_at
    from public.event_dates d
    where d.id = v_id;
end;
$$;

comment on function public.admin_save_event_date(uuid, uuid, date, time, time, integer, integer, text, boolean, text) is
  'Creates (p_id null) or edits one night: date, times, capacity, seats held back, status, booking open/closed and notes. Locks the night before counting, refuses capacity below seats paid for (PT004 carries the floor), an impossible held figure (PT002/PT003) or a duplicate date (PT006).';

revoke all on function public.admin_save_event_date(uuid, uuid, date, time, time, integer, integer, text, boolean, text) from public;
revoke all on function public.admin_save_event_date(uuid, uuid, date, time, time, integer, integer, text, boolean, text) from anon, authenticated;
grant execute on function public.admin_save_event_date(uuid, uuid, date, time, time, integer, integer, text, boolean, text) to service_role;


-- -----------------------------------------------------------------------------
-- 12. The two controls an organiser reaches for mid-event
--
-- "The queue is longer than we thought, open another 200 seats" and "we are full,
-- stop selling" happen in the moment, from a phone, while the event is running.
-- They get their own narrow functions so neither can arrive with a whole form
-- attached to it — and so both can take the night lock and refuse to make
-- availability negative, with the floor in the error.
-- -----------------------------------------------------------------------------
create or replace function public.admin_set_event_date_capacity(
  p_id            uuid,
  p_capacity      integer,
  p_capacity_held integer default null
)
returns table (
  date_uuid       uuid,
  capacity        integer,
  capacity_held   integer,
  booked_people   integer,
  seats_available integer,
  updated_at      timestamptz
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_held integer;
  v_paid integer;
begin
  if p_id is null then
    raise exception 'night_not_found' using errcode = 'PT007';
  end if;

  if p_capacity is null or p_capacity < 1 then
    raise exception 'capacity_below_one' using errcode = 'PT001', detail = 'capacity';
  end if;

  -- The night is locked first: whoever else is counting seats for it — a customer
  -- paying for the last one — finishes before this reads.
  perform 1 from public.event_dates d where d.id = p_id for update;

  if not found then
    raise exception 'night_not_found' using errcode = 'PT007';
  end if;

  select d.capacity_held into v_held from public.event_dates d where d.id = p_id;
  v_held := coalesce(p_capacity_held, v_held);

  if v_held < 0 then
    raise exception 'capacity_held_negative' using errcode = 'PT002', detail = 'capacity_held';
  end if;

  if v_held > p_capacity then
    raise exception 'capacity_held_above_capacity' using errcode = 'PT003', detail = 'capacity_held';
  end if;

  select coalesce(sum(b.number_of_people) filter (where b.payment_status = 'paid'), 0)::integer
    into v_paid
  from public.bookings b
  where b.event_date_id = p_id;

  if v_paid + v_held > p_capacity then
    raise exception 'capacity_below_taken' using errcode = 'PT004',
      detail = (v_paid + v_held)::text;
  end if;

  update public.event_dates d
     set capacity = p_capacity,
         capacity_held = v_held
   where d.id = p_id;

  return query
    select d.id, d.capacity, d.capacity_held, v_paid,
           greatest(d.capacity - d.capacity_held - v_paid, 0),
           d.updated_at
    from public.event_dates d
    where d.id = p_id;
end;
$$;

comment on function public.admin_set_event_date_capacity(uuid, integer, integer) is
  'Sets a night''s capacity, and optionally how many seats are held back from online booking. Locks the night, refuses a capacity below seats paid for or held (PT004 carries the lowest allowed figure), so availability can never be made negative.';

revoke all on function public.admin_set_event_date_capacity(uuid, integer, integer) from public;
revoke all on function public.admin_set_event_date_capacity(uuid, integer, integer) from anon, authenticated;
grant execute on function public.admin_set_event_date_capacity(uuid, integer, integer) to service_role;


create or replace function public.admin_set_event_date_booking(
  p_id           uuid,
  p_booking_open boolean
)
returns table (
  date_uuid    uuid,
  booking_open boolean,
  night_status text,
  capacity     integer,
  capacity_held integer,
  booked_people integer,
  seats_available integer,
  updated_at   timestamptz
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_paid integer;
begin
  if p_id is null or p_booking_open is null then
    raise exception 'night_not_found' using errcode = 'PT007';
  end if;

  perform 1 from public.event_dates d where d.id = p_id for update;

  if not found then
    raise exception 'night_not_found' using errcode = 'PT007';
  end if;

  update public.event_dates d
     set booking_open = p_booking_open
   where d.id = p_id;

  select coalesce(sum(b.number_of_people) filter (where b.payment_status = 'paid'), 0)::integer
    into v_paid
  from public.bookings b
  where b.event_date_id = p_id;

  return query
    select d.id, d.booking_open, d.status, d.capacity, d.capacity_held, v_paid,
           greatest(d.capacity - d.capacity_held - v_paid, 0),
           d.updated_at
    from public.event_dates d
    where d.id = p_id;
end;
$$;

comment on function public.admin_set_event_date_booking(uuid, boolean) is
  'Opens or closes booking on one night without touching the night''s status, capacity or dates. Closing it makes create_pending_booking refuse the night (PB002) exactly as a cancelled night would.';

revoke all on function public.admin_set_event_date_booking(uuid, boolean) from public;
revoke all on function public.admin_set_event_date_booking(uuid, boolean) from anon, authenticated;
grant execute on function public.admin_set_event_date_booking(uuid, boolean) to service_role;


-- ===========================================================================
-- 20260922091300_gallery_management.sql
-- ===========================================================================

-- =============================================================================
-- Garba Nights — gallery management
--
-- Gallery files are managed by the server in Vercel Blob; PostgreSQL stores the
-- rows, Blob object keys, URLs and image metadata. Publication controls which
-- rows appear on the public site. Draft files in the public Blob store are
-- unlisted, not private, so do not upload sensitive material.
--
-- The database enforces the rules that must never drift (alt text, dimensions,
-- one row per object and ordering). The app reports the database decision and
-- performs the corresponding Blob operation.
--
-- Object keys are `<event or "festival">/<item uuid>/full.webp` and
-- `…/thumb.webp`: deterministic from the row. `gallery.url` and
-- `gallery.thumbnail_url` remain for externally hosted media.
--
-- Error codes (the app maps these to a field, not to prose):
--
--   PG001 alt_text_required          PG006 gallery_item_not_found
--   PG002 title_too_long             PG007 sort_order_invalid
--   PG003 description_too_long       PG008 status_invalid
--   PG004 album_too_long             PG009 image_dimensions_invalid
--   PG005 storage_path_invalid       PG010 image_size_invalid
--                                    PG011 duplicate_storage_path
-- =============================================================================


-- Gallery file bytes live in Vercel Blob. This schema creates no provider storage
-- objects; the migration only owns the metadata and database-side rules.

-- -----------------------------------------------------------------------------
-- 1. gallery: the facts about a file
--
-- `storage_path` is the object key; `thumbnail_path` is the small version of the
-- same picture; width/height let the grid reserve the right space before the
-- bytes arrive (no layout shift), and byte_size lets the screen say how heavy a
-- row is before somebody downloads it on a phone.
-- -----------------------------------------------------------------------------
alter table public.gallery
  add column if not exists thumbnail_path text,
  add column if not exists width          integer,
  add column if not exists height         integer,
  add column if not exists byte_size      integer;

comment on column public.gallery.storage_path is
  'Vercel Blob object key for the full gallery image: <event or festival>/<item uuid>/full.webp.';
comment on column public.gallery.thumbnail_path is
  'The grid-sized version of the same object (…/thumb.webp). Null for externally hosted media.';
comment on column public.gallery.width is
  'Pixel width of the stored full image, so the page can reserve space before loading it.';
comment on column public.gallery.height is 'Pixel height of the stored full image.';
comment on column public.gallery.byte_size is 'Bytes of the stored full image, as written by the upload.';

alter table public.gallery drop constraint if exists gallery_dimensions_range;
alter table public.gallery
  add constraint gallery_dimensions_range check (
    (width is null or (width between 1 and 20000))
    and (height is null or (height between 1 and 20000))
    and ((width is null) = (height is null))
  );

alter table public.gallery drop constraint if exists gallery_byte_size_range;
alter table public.gallery
  add constraint gallery_byte_size_range check (byte_size is null or (byte_size between 1 and 52428800));

-- One row per object. A second row pointing at the same file is how a delete
-- quietly breaks a picture that was still in use, so it cannot exist.
create unique index if not exists gallery_storage_path_unique
  on public.gallery (storage_path) where storage_path is not null;
create unique index if not exists gallery_thumbnail_path_unique
  on public.gallery (thumbnail_path) where thumbnail_path is not null;


-- -----------------------------------------------------------------------------
-- 2. Reading the gallery, for the screen that manages it
-- -----------------------------------------------------------------------------
create or replace function public.admin_gallery_items(p_event_id uuid default null)
returns table (
  item_id        uuid,
  event_id       uuid,
  album          text,
  title          text,
  description    text,
  alt_text       text,
  media_type     text,
  storage_path   text,
  thumbnail_path text,
  url            text,
  thumbnail_url  text,
  width          integer,
  height         integer,
  byte_size      integer,
  captured_on    date,
  item_status    text,
  sort_order     integer,
  created_at     timestamptz,
  updated_at     timestamptz,
  total_count    integer
)
language sql
stable
security definer
set search_path = public
as $$
  with target as (
    select coalesce(p_event_id, public.admin_default_event_id()) as event_id
  )
  select
    g.id,
    g.event_id,
    g.album,
    g.title,
    g.description,
    g.alt_text,
    g.media_type,
    g.storage_path,
    g.thumbnail_path,
    g.url,
    g.thumbnail_url,
    g.width,
    g.height,
    g.byte_size,
    g.captured_on,
    g.status,
    g.sort_order,
    g.created_at,
    g.updated_at,
    (select count(*)::integer
       from public.gallery g2
      where g2.event_id is not distinct from g.event_id) as total_count
  from public.gallery g
  cross join target t
  where g.event_id is not distinct from t.event_id
     or g.event_id is null
  order by g.sort_order, g.created_at desc, g.id;
$$;

comment on function public.admin_gallery_items(uuid) is
  'Every gallery row of an event — published, draft and archived alike — with the file facts (paths, dimensions, size) the management screen needs. Ordered the way the public grid orders them, so the screen shows the running order an organiser is about to change.';

revoke all on function public.admin_gallery_items(uuid) from public;
revoke all on function public.admin_gallery_items(uuid) from anon, authenticated;
grant execute on function public.admin_gallery_items(uuid) to service_role;


-- -----------------------------------------------------------------------------
-- 3. Sharing the validation between the two write paths
-- -----------------------------------------------------------------------------
create or replace function public.gallery_check_metadata(
  p_title        text,
  p_description  text,
  p_alt_text     text,
  p_album        text,
  p_sort_order   integer
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  -- Alternative text is not optional: it is how the picture exists for anybody
  -- using a screen reader, and an empty one is worse than a missing row.
  if p_alt_text is null or length(btrim(p_alt_text)) = 0 then
    raise exception 'alt_text_required' using errcode = 'PG001', detail = 'alt_text';
  end if;

  if length(btrim(coalesce(p_alt_text, ''))) > 200 then
    raise exception 'alt_text_required' using errcode = 'PG001', detail = 'alt_text';
  end if;

  if length(btrim(coalesce(p_title, ''))) > 120 then
    raise exception 'title_too_long' using errcode = 'PG002', detail = 'title';
  end if;

  if length(btrim(coalesce(p_description, ''))) > 400 then
    raise exception 'description_too_long' using errcode = 'PG003', detail = 'description';
  end if;

  if length(btrim(coalesce(p_album, ''))) > 60 then
    raise exception 'album_too_long' using errcode = 'PG004', detail = 'album';
  end if;

  if p_sort_order is null or p_sort_order < 0 or p_sort_order > 9999 then
    raise exception 'sort_order_invalid' using errcode = 'PG007', detail = 'sort_order';
  end if;
end;
$$;

comment on function public.gallery_check_metadata(text, text, text, text, integer) is
  'The rules both gallery write paths share: alt text present and short, title/description/album within their column limits, order a whole number in range. Raises PG001-PG004 and PG007 with the field in `detail`.';

revoke all on function public.gallery_check_metadata(text, text, text, text, integer) from public;
revoke all on function public.gallery_check_metadata(text, text, text, text, integer) from anon, authenticated;
grant execute on function public.gallery_check_metadata(text, text, text, text, integer) to service_role;


-- -----------------------------------------------------------------------------
-- 4. Adding a row — after the file exists
--
-- The id is supplied by the caller because the object key contains it: the app
-- uploads to `<event>/<id>/full.webp`, so it has to know the id before the row
-- exists. That also makes a retried upload idempotent — the same id cannot be
-- inserted twice, and the second attempt is refused rather than becoming a
-- second picture of the same photo.
-- -----------------------------------------------------------------------------
create or replace function public.admin_add_gallery_item(
  p_id             uuid,
  p_event_id       uuid,
  p_storage_path   text,
  p_thumbnail_path text,
  p_media_type     text,
  p_width          integer,
  p_height         integer,
  p_byte_size      integer,
  p_title          text,
  p_description    text,
  p_alt_text       text,
  p_album          text,
  p_captured_on    date,
  p_sort_order     integer,
  p_status         text
)
returns table (
  item_id      uuid,
  storage_path text,
  item_status  text,
  sort_order   integer,
  updated_at   timestamptz
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_event_id uuid := coalesce(p_event_id, public.admin_default_event_id());
  v_status   text := coalesce(nullif(btrim(coalesce(p_status, '')), ''), 'draft');
  v_media    text := coalesce(nullif(btrim(coalesce(p_media_type, '')), ''), 'image');
begin
  if p_id is null then
    raise exception 'gallery_item_not_found' using errcode = 'PG006';
  end if;

  if v_event_id is null then
    raise exception 'gallery_item_not_found' using errcode = 'PG006';
  end if;

  if v_status not in ('draft', 'published', 'archived') then
    raise exception 'status_invalid' using errcode = 'PG008', detail = 'status';
  end if;

  if v_media not in ('image', 'video') then
    raise exception 'status_invalid' using errcode = 'PG008', detail = 'media_type';
  end if;

  -- An object key is a relative path inside one bucket: no scheme, no leading
  -- slash, no `..`, no control characters. Enforced here because the key is what
  -- the app hands to storage — a key it cannot trust is a key it cannot delete.
  if p_storage_path is null
     or p_storage_path !~ '^[A-Za-z0-9][A-Za-z0-9._/-]{0,200}$'
     or position('..' in p_storage_path) > 0
     or left(p_storage_path, 1) = '/'
     or right(p_storage_path, 1) = '/' then
    raise exception 'storage_path_invalid' using errcode = 'PG005', detail = 'storage_path';
  end if;

  if p_thumbnail_path is not null
     and (p_thumbnail_path !~ '^[A-Za-z0-9][A-Za-z0-9._/-]{0,200}$'
          or position('..' in p_thumbnail_path) > 0) then
    raise exception 'storage_path_invalid' using errcode = 'PG005', detail = 'thumbnail_path';
  end if;

  if (p_width is not null and (p_width < 1 or p_width > 20000))
     or (p_height is not null and (p_height < 1 or p_height > 20000))
     or ((p_width is null) <> (p_height is null)) then
    raise exception 'image_dimensions_invalid' using errcode = 'PG009', detail = 'width';
  end if;

  if p_byte_size is not null and (p_byte_size < 1 or p_byte_size > 52428800) then
    raise exception 'image_size_invalid' using errcode = 'PG010', detail = 'byte_size';
  end if;

  perform public.gallery_check_metadata(p_title, p_description, p_alt_text, p_album, p_sort_order);

  begin
    insert into public.gallery (
      id, event_id, album, title, description, media_type,
      storage_path, thumbnail_path, width, height, byte_size,
      alt_text, captured_on, status, sort_order
    )
    values (
      p_id, v_event_id, nullif(btrim(coalesce(p_album, '')), ''),
      nullif(btrim(coalesce(p_title, '')), ''),
      nullif(btrim(coalesce(p_description, '')), ''),
      v_media, p_storage_path, nullif(btrim(coalesce(p_thumbnail_path, '')), ''),
      p_width, p_height, p_byte_size,
      btrim(p_alt_text), p_captured_on, v_status, p_sort_order
    );
  exception
    when unique_violation then
      raise exception 'duplicate_storage_path' using errcode = 'PG011', detail = 'storage_path';
  end;

  return query
    select g.id, g.storage_path, g.status, g.sort_order, g.updated_at
    from public.gallery g
    where g.id = p_id;
end;
$$;

comment on function public.admin_add_gallery_item(uuid, uuid, text, text, text, integer, integer, integer, text, text, text, text, date, integer, text) is
  'Records one uploaded gallery file. The caller supplies the id (the object key contains it, so a retry cannot create a second row for the same file) and the file facts the upload measured; the metadata rules come from gallery_check_metadata. PG005 refuses a storage key that is not a safe relative path.';

revoke all on function public.admin_add_gallery_item(uuid, uuid, text, text, text, integer, integer, integer, text, text, text, text, date, integer, text) from public;
revoke all on function public.admin_add_gallery_item(uuid, uuid, text, text, text, integer, integer, integer, text, text, text, text, date, integer, text) from anon, authenticated;
grant execute on function public.admin_add_gallery_item(uuid, uuid, text, text, text, integer, integer, integer, text, text, text, text, date, integer, text) to service_role;


-- -----------------------------------------------------------------------------
-- 5. Editing the words, and the running order
-- -----------------------------------------------------------------------------
create or replace function public.admin_update_gallery_item(
  p_id          uuid,
  p_title       text,
  p_description text,
  p_alt_text    text,
  p_album       text,
  p_captured_on date,
  p_sort_order  integer
)
returns table (
  item_id      uuid,
  title        text,
  description  text,
  alt_text     text,
  album        text,
  captured_on  date,
  sort_order   integer,
  updated_at   timestamptz
)
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_id is null then
    raise exception 'gallery_item_not_found' using errcode = 'PG006';
  end if;

  perform public.gallery_check_metadata(p_title, p_description, p_alt_text, p_album, p_sort_order);

  update public.gallery g
     set title       = nullif(btrim(coalesce(p_title, '')), ''),
         description = nullif(btrim(coalesce(p_description, '')), ''),
         alt_text    = btrim(p_alt_text),
         album       = nullif(btrim(coalesce(p_album, '')), ''),
         captured_on = p_captured_on,
         sort_order  = p_sort_order
   where g.id = p_id;

  if not found then
    raise exception 'gallery_item_not_found' using errcode = 'PG006';
  end if;

  return query
    select g.id, g.title, g.description, g.alt_text, g.album, g.captured_on, g.sort_order, g.updated_at
    from public.gallery g
    where g.id = p_id;
end;
$$;

comment on function public.admin_update_gallery_item(uuid, text, text, text, text, date, integer) is
  'Edits the words and the running order of one gallery item: title, description, alternative text, album, the night it was taken and its position. Nothing about the file changes, so a caption can be fixed without touching storage.';

revoke all on function public.admin_update_gallery_item(uuid, text, text, text, text, date, integer) from public;
revoke all on function public.admin_update_gallery_item(uuid, text, text, text, text, date, integer) from anon, authenticated;
grant execute on function public.admin_update_gallery_item(uuid, text, text, text, text, date, integer) to service_role;


/**
 * Moves one item up or down the running order — the control an organiser actually
 * uses, which is why it does not take a number.
 *
 * The move is a *reordering*, not a swap of two numbers, because numbers are not
 * unique in the real world: two photographs uploaded in the same second, a row
 * imported with `sort_order = 0`, a deleted row leaving a gap. The list is
 * therefore read the way the public grid reads it (`sort_order`, then newest
 * first, then id), numbered `0…n-1`, and written back with the moving item and its
 * neighbour exchanged. That normalises any duplicates or gaps as it goes, and it
 * makes "up" mean what it says: the photograph is above its former neighbour.
 *
 * The first item cannot move up and the last cannot move down. That is not an
 * error — it is the end of the list — so `moved` comes back false and the screen
 * says "already first" rather than showing a failure.
 */
create or replace function public.admin_move_gallery_item(p_id uuid, p_direction text)
returns table (
  item_id    uuid,
  sort_order integer,
  moved      boolean
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_item public.gallery%rowtype;
  v_ids  uuid[];
  v_pos  integer;
  v_swap integer;
begin
  if p_id is null then
    raise exception 'gallery_item_not_found' using errcode = 'PG006';
  end if;

  if p_direction not in ('up', 'down') then
    raise exception 'sort_order_invalid' using errcode = 'PG007', detail = 'direction';
  end if;

  select * into v_item from public.gallery g where g.id = p_id;

  if not found then
    raise exception 'gallery_item_not_found' using errcode = 'PG006';
  end if;

  select array_agg(ordered.id order by ordered.position)
    into v_ids
    from (
      select g.id, row_number() over (order by g.sort_order, g.created_at desc, g.id) as position
        from public.gallery g
       where g.event_id is not distinct from v_item.event_id
    ) as ordered;

  v_pos := array_position(v_ids, p_id);

  if p_direction = 'up' then
    v_swap := case when v_pos > 1 then v_pos - 1 else null end;
  else
    v_swap := case when v_pos < coalesce(array_length(v_ids, 1), 1) then v_pos + 1 else null end;
  end if;

  update public.gallery g
     set sort_order = positions.position - 1
    from (
      select numbered.id,
             case
               when numbered.ord = v_pos then coalesce(v_swap, v_pos)
               when numbered.ord = v_swap then v_pos
               else numbered.ord
             end as position
        from unnest(v_ids) with ordinality as numbered(id, ord)
    ) as positions
   where g.id = positions.id
     and g.sort_order is distinct from positions.position - 1;

  return query
    select g.id, g.sort_order, v_swap is not null
    from public.gallery g
    where g.id = p_id;
end;
$$;

comment on function public.admin_move_gallery_item(uuid, text) is
  'Reorders one gallery item one place up or down. The whole list is renumbered 0…n-1 in the order the public grid shows it, with the moving item exchanged with its neighbour, so ties and gaps cannot make a move land in the wrong place. Returns moved = false at the ends of the list rather than raising, because "already first" is an answer, not an error.';

revoke all on function public.admin_move_gallery_item(uuid, text) from public;
revoke all on function public.admin_move_gallery_item(uuid, text) from anon, authenticated;
grant execute on function public.admin_move_gallery_item(uuid, text) to service_role;


-- -----------------------------------------------------------------------------
-- 6. Publishing, unpublishing, deleting
--
-- Publishing changes the database row and the public gallery listing. The app
-- keeps the corresponding Vercel Blob objects in sync with that row.
-- -----------------------------------------------------------------------------
create or replace function public.admin_set_gallery_status(p_id uuid, p_status text)
returns table (
  item_id       uuid,
  item_status   text,
  storage_path  text,
  thumbnail_path text,
  was_public    boolean,
  is_public     boolean
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_item public.gallery%rowtype;
begin
  if p_id is null then
    raise exception 'gallery_item_not_found' using errcode = 'PG006';
  end if;

  if p_status is null or p_status not in ('draft', 'published', 'archived') then
    raise exception 'status_invalid' using errcode = 'PG008', detail = 'status';
  end if;

  select * into v_item from public.gallery g where g.id = p_id for update;

  if not found then
    raise exception 'gallery_item_not_found' using errcode = 'PG006';
  end if;

  update public.gallery g set status = p_status where g.id = p_id;

  return query
    select g.id, g.status, g.storage_path, g.thumbnail_path,
           (v_item.status = 'published'), (g.status = 'published')
    from public.gallery g
    where g.id = p_id;
end;
$$;

comment on function public.admin_set_gallery_status(uuid, text) is
  'Publishes, drafts or archives one gallery item and returns its file keys so the app can keep Vercel Blob in sync. Locks the row so concurrent status changes cannot interleave.';

revoke all on function public.admin_set_gallery_status(uuid, text) from public;
revoke all on function public.admin_set_gallery_status(uuid, text) from anon, authenticated;
grant execute on function public.admin_set_gallery_status(uuid, text) to service_role;


/**
 * Deletes the row and hands back the objects that belonged to it.
 *
 * The row goes first: if the file delete then fails, an orphaned object sits in a
 * bucket costing a few kilobytes and nothing links to it, whereas a row whose
 * file has gone is a broken picture on the public page. The returned paths are
 * what the app deletes, so a row can never be removed without the app being told
 * which files to clean up.
 */
create or replace function public.admin_delete_gallery_item(p_id uuid)
returns table (
  item_id        uuid,
  storage_path   text,
  thumbnail_path text,
  is_public      boolean,
  removed_paths  text[]
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_item public.gallery%rowtype;
begin
  if p_id is null then
    raise exception 'gallery_item_not_found' using errcode = 'PG006';
  end if;

  select * into v_item from public.gallery g where g.id = p_id for update;

  if not found then
    raise exception 'gallery_item_not_found' using errcode = 'PG006';
  end if;

  delete from public.gallery g where g.id = p_id;

  return query
    select v_item.id,
           v_item.storage_path,
           v_item.thumbnail_path,
           (v_item.status = 'published'),
           array_remove(array[v_item.storage_path, v_item.thumbnail_path], null)::text[];
end;
$$;

comment on function public.admin_delete_gallery_item(uuid) is
  'Removes one gallery row and returns its object paths (and whether they were public) so the app can delete the files. The database decides what existed; the app decides what to do with storage.';

revoke all on function public.admin_delete_gallery_item(uuid) from public;
revoke all on function public.admin_delete_gallery_item(uuid) from anon, authenticated;
grant execute on function public.admin_delete_gallery_item(uuid) to service_role;


-- ===========================================================================
-- 20260922091400_contact_and_social_links.sql
-- ===========================================================================

-- =============================================================================
-- Garba Nights — contact details, social links and support hours
--
-- The public site's contact block used to be static configuration: the WhatsApp
-- number, the phone, the email, the address lines and the three social handles were
-- literals in `src/config`, so the same number lived in the footer, the header, the
-- contact page and every \"message us\" button — and changing it meant a deploy.
--
-- This migration moves that data where the rest of the event's facts already live:
-- onto `events`. The site reads it through the same service layer as the venue, the
-- dates and the prices, and every link (WhatsApp, `tel:`, `mailto:`, maps, socials)
-- is derived from the row in one place.
--
-- Column notes:
--
--   * `whatsapp_number` is the number the click-to-chat links use, in international
--     format **without** the plus or any spaces (`919000000000`). It is separate from
--     `contact_phone` because an organiser's WhatsApp Business number is often not the
--     number they take calls on; when it is empty the app falls back to the digits of
--     `contact_phone`, so a deployment that only fills one column still works.
--   * `instagram_url`, `facebook_url`, `youtube_url` are the event's profiles. They
--     must be `https://` and on the platform they claim to be — a link in the wrong
--     column sends guests somewhere the organiser did not intend, which is the kind of
--     mistake a constraint catches and a form does not.
--   * `support_hours` is a short list of lines ("Monday – Saturday · 10:00 AM – 8:00
--     PM"), because the hours really are a list and a single string with newlines in it
--     would have to be parsed back apart by whoever reads it.
--
-- Nothing here is secret: `events` is publicly readable for published rows, and these
-- columns are the ones the site is meant to show.
-- =============================================================================


-- -----------------------------------------------------------------------------
-- 1. The columns
-- -----------------------------------------------------------------------------
alter table public.events
  add column if not exists whatsapp_number text,
  add column if not exists instagram_url   text,
  add column if not exists facebook_url    text,
  add column if not exists youtube_url     text,
  add column if not exists support_hours   text[] not null default '{}';


-- -----------------------------------------------------------------------------
-- 2. What the columns may hold
--
-- Constraints rather than triggers: this is shape, not workflow. Each is dropped and
-- re-added so the migration can be re-run against a database that already has them.
-- -----------------------------------------------------------------------------

-- International format, digits only, no plus, no leading zero: a `wa.me` URL is built
-- by concatenating this, so anything else produces a link that goes nowhere.
alter table public.events drop constraint if exists events_whatsapp_number_format;

alter table public.events add constraint events_whatsapp_number_format
  check (whatsapp_number is null or whatsapp_number ~ '^[1-9][0-9]{9,14}$');

-- One link per platform, https only, and on the platform's own domain.
alter table public.events drop constraint if exists events_social_url_https;

alter table public.events add constraint events_social_url_https
  check (
    (instagram_url is null or instagram_url ~ '^https://([a-z0-9-]+\.)?instagram\.com/')
    and (facebook_url is null or facebook_url ~ '^https://([a-z0-9-]+\.)?(facebook|fb)\.com/')
    and (youtube_url is null or youtube_url ~ '^https://([a-z0-9-]+\.)?(youtube\.com|youtu\.be)/')
  );

-- A support-hours list is a handful of lines, not a document.
alter table public.events drop constraint if exists events_support_hours_size;

alter table public.events add constraint events_support_hours_size
  check (
    array_length(support_hours, 1) is null
    or (array_length(support_hours, 1) between 1 and 6)
  );

comment on column public.events.whatsapp_number is
  'Number the site''s click-to-chat links open, in international format without "+" or spaces (919000000000). Falls back to contact_phone''s digits in the app when empty.';

comment on column public.events.instagram_url is
  'The event''s Instagram profile: https:// and on instagram.com, or null when the event has none.';

comment on column public.events.facebook_url is
  'The event''s Facebook page: https:// and on facebook.com (or fb.com), or null.';

comment on column public.events.youtube_url is
  'The event''s YouTube channel: https:// and on youtube.com (or youtu.be), or null.';

comment on column public.events.support_hours is
  'Up to six lines of opening hours, shown on the contact page and in the footer, e.g. "Monday – Saturday · 10:00 AM – 8:00 PM".';

-- The event row the public site reads is fetched by `created_at` order and limited to
-- one row, which the primary key already serves. No new index is warranted: these
-- columns are read with the row, never filtered on.


-- ===========================================================================
-- 20260922091500_security_hardening.sql
-- ===========================================================================

-- -----------------------------------------------------------------------------
-- 20260922091500_security_hardening
--
-- Row level security for the gate role.
--
-- The original staff policies were written as "an active staff member may work the
-- gate". `admin_users.role = 'staff'` is the role that gets a phone at the door,
-- and a session holding it could, straight through PostgREST with its own token:
--
--   * read every booking, mobile number and email address in the database;
--   * read every digital pass, including its `qr_token` — the credential that
--     admits the holder;
--   * update bookings: `payment_status = 'paid'`, or `booking_status =
--     'cancelled'` on somebody else's booking;
--   * update passes: `checked_in = false, status = 'active'` on a used pass, so the
--     same QR code is admitted a second time, or `valid_date` moved to another
--     night;
--   * insert into `check_ins`, where `check_ins_one_per_pass` turns each row into a
--     denial of service against a real guest, plus a fake entry log.
--
-- None of that is what the gate needs. `pass_entry()` and `check_in_pass()` are
-- SECURITY DEFINER functions called with the service role, and `src/lib/auth/*`
-- checks the role server-side before either is reached. **No application code
-- reads these tables with a user session at all** — the only table a session
-- touches directly is `admin_users`, to resolve the caller's own staff row. These
-- policies are therefore defence in depth, and the narrowest version of them
-- cannot break a working screen.
--
-- What is left for the gate role:
--   check_ins  — SELECT, so a shift can see the night's entries: pass ids, gate,
--                timestamp. No personal data, no credentials.
--   everything else on `bookings` and `digital_passes` — admin and super_admin.
-- -----------------------------------------------------------------------------

drop policy if exists bookings_staff_read on public.bookings;
drop policy if exists bookings_staff_update on public.bookings;

create policy bookings_admin_read on public.bookings
  for select
  to authenticated
  using (public.is_admin());

create policy bookings_admin_update on public.bookings
  for update
  to authenticated
  using (public.is_admin())
  with check (public.is_admin());

comment on policy bookings_admin_read on public.bookings is
  'Guest names, mobile numbers and email addresses are admin work. A scanner session reads a pass through pass_entry(), which returns only the pass in front of it.';

drop policy if exists digital_passes_staff_read on public.digital_passes;
drop policy if exists digital_passes_staff_update on public.digital_passes;

create policy digital_passes_admin_read on public.digital_passes
  for select
  to authenticated
  using (public.is_admin());

create policy digital_passes_admin_update on public.digital_passes
  for update
  to authenticated
  using (public.is_admin())
  with check (public.is_admin());

comment on policy digital_passes_admin_read on public.digital_passes is
  'A pass row carries qr_token, the credential that admits its holder, so reading the table is admin work.';

drop policy if exists check_ins_staff_insert on public.check_ins;

create policy check_ins_admin_insert on public.check_ins
  for insert
  to authenticated
  with check (public.is_admin());

comment on policy check_ins_staff_read on public.check_ins is
  'Any active staff role may read the entry log for the night. The row itself is written by check_in_pass() as the service role, in the same transaction that flips the pass, so INSERT is admin-only here.';


-- ===========================================================================
-- 20260923090000_single_admin.sql
-- ===========================================================================

-- =============================================================================
-- 17 · One admin, no roles — plus the columns the new brief asks for
--
-- Why this exists
--   The application uses Neon through a single trusted server-side connection,
--   and the staff/role model has been replaced by one admin account
--   authenticated by the app itself. In that world the database does not need to
--   know who is asking:
--
--     * there is one admin, so there is no staff table, no roles and no
--       permissions matrix — and no dependency on the legacy auth provider;
--     * the gate verdict (pass_entry) no longer resolves a staff row: the session
--       was already proven before the call, and the audit row records the booking
--       instead of the staff member;
--     * it adds the columns the brief specifies that did not exist yet.
--
-- What survives, deliberately
--   The six public read policies (published events, their nights, active passes,
--   published gallery, highlights, features) stay, and are now the only policies
--   in the database. The app no longer reads through them — it connects as the
--   table owner, which bypasses RLS — but they remain the database-side boundary:
--   anything connecting as `anon` can still read exactly the public surface and
--   nothing else. Everything that protects a pass or a payment (token shape,
--   payment-confirmed, compare-and-swap check-in, unique(digital_pass_id)) is
--   untouched.
--
-- Idempotent: every statement is guarded, so re-running it changes nothing.
-- =============================================================================

-- ---------------------------------------------------------------------------
-- 1 · The columns the brief asks for
-- ---------------------------------------------------------------------------

-- events: bilingual copy, a logo, and the festival window. The banner is the
-- existing `hero_image_url` (mapped as banner_url in Prisma) so there is exactly
-- one banner column, not two that can disagree.
alter table public.events
  add column if not exists name_hindi        text,
  add column if not exists description_hindi text,
  add column if not exists venue_hindi       text,
  add column if not exists logo_url          text,
  add column if not exists start_date        date,
  add column if not exists end_date          date;

comment on column public.events.name_hindi        is 'Hindi name of the festival. Falls back to events.name when empty.';
comment on column public.events.description_hindi is 'Hindi description. Falls back to events.description when empty.';
comment on column public.events.venue_hindi       is 'Hindi venue line. Falls back to events.venue_name when empty.';
comment on column public.events.logo_url          is 'Organiser logo, shown in the header and on the digital pass.';
comment on column public.events.start_date        is 'First night of the festival. Kept in step with event_dates by the admin screens.';
comment on column public.events.end_date          is 'Last night of the festival. Kept in step with event_dates by the admin screens.';

-- pass_categories: Hindi name, its own image, and the brief's `status`. Status is
-- derived from `is_active` — the flag every existing function, the catalogue RPCs
-- and the admin screen already own — so there is one source of truth with two
-- spellings rather than two columns that can disagree.
alter table public.pass_categories
  add column if not exists name_hindi text,
  add column if not exists image_url  text,
  add column if not exists status     text generated always as (
    case when is_active then 'active' else 'inactive' end) stored;

comment on column public.pass_categories.name_hindi is 'Hindi pass name. Falls back to pass_categories.name when empty.';
comment on column public.pass_categories.image_url  is 'Optional image for the pass card.';
comment on column public.pass_categories.status     is 'Derived from is_active: active | inactive. Read-only.';

-- event_dates: the brief's available_capacity, derived so it cannot drift from
-- capacity/capacity_held and cannot go negative. The existing
-- event_dates_guard_capacity trigger is what keeps capacity_held honest.
alter table public.event_dates
  add column if not exists available_capacity integer generated always as (
    greatest(capacity - capacity_held, 0)) stored;

comment on column public.event_dates.available_capacity is 'Derived: greatest(capacity - capacity_held, 0). Read-only.';

-- check_ins: the booking on the audit row (the brief asks for it), a created_at,
-- and no staff id.
alter table public.check_ins
  add column if not exists booking_id uuid references public.bookings (id) on delete cascade,
  add column if not exists created_at timestamptz not null default now();

update public.check_ins c
   set booking_id = p.booking_id
  from public.digital_passes p
 where p.id = c.digital_pass_id
   and c.booking_id is null;

alter table public.check_ins alter column booking_id set not null;
alter table public.check_ins drop column if exists checked_in_by;

create index if not exists check_ins_booking_idx on public.check_ins (booking_id);

comment on column public.check_ins.booking_id is 'The booking this entry belongs to, denormalised from the pass at check-in time.';

-- ---------------------------------------------------------------------------
-- 2 · The role system goes
-- ---------------------------------------------------------------------------
-- Order matters. Policies reference the helper functions; the helper functions
-- read admin_users; check_ins.checked_in_by referenced admin_users too (dropped
-- above). Everything that depends on a role goes before the thing it depends on.

drop policy if exists admin_users_admin_read            on public.admin_users;
drop policy if exists admin_users_super_admin_manage    on public.admin_users;
drop policy if exists bookings_admin_read               on public.bookings;
drop policy if exists bookings_admin_update             on public.bookings;
drop policy if exists check_ins_admin_insert            on public.check_ins;
drop policy if exists check_ins_staff_read              on public.check_ins;
drop policy if exists digital_passes_admin_read         on public.digital_passes;
drop policy if exists digital_passes_admin_update       on public.digital_passes;
drop policy if exists event_dates_admin_manage          on public.event_dates;
drop policy if exists event_dates_authenticated_read    on public.event_dates;
drop policy if exists event_features_admin_manage       on public.event_features;
drop policy if exists event_features_authenticated_read on public.event_features;
drop policy if exists event_highlights_admin_manage     on public.event_highlights;
drop policy if exists event_highlights_authenticated_read on public.event_highlights;
drop policy if exists events_admin_manage               on public.events;
drop policy if exists events_authenticated_read         on public.events;
drop policy if exists gallery_admin_manage              on public.gallery;
drop policy if exists gallery_authenticated_read        on public.gallery;
drop policy if exists pass_categories_admin_manage      on public.pass_categories;
drop policy if exists pass_categories_authenticated_read on public.pass_categories;

drop function if exists public.is_staff(uuid);
drop function if exists public.is_admin(uuid);
drop function if exists public.is_super_admin(uuid);
drop function if exists public.current_staff_role();

-- The allow-list itself. It referenced auth.users, so this also removes the last
-- database object that knew about the previous hosted authentication system.
drop table if exists public.admin_users;

-- ---------------------------------------------------------------------------
-- 3 · The admin read models that joined the staff table
-- ---------------------------------------------------------------------------
-- Three SQL functions read admin_users (to label who admitted a pass, and to
-- count staff on the dashboard). A SQL function body is parsed when it is
-- created, so these must be restated in the same migration that drops the table.
--
-- admin_booking_detail and admin_pass_list also lose their customer_email column
-- here rather than in the next migration: it dies with the same join in the same
-- restatement, and restating a function twice to change it twice would be worse.
--
-- `admitted_by` is kept in the pass list's result shape and returned as null: the
-- staff identity it described no longer exists, and dropping the column would
-- change the function's return type for no benefit.

drop function if exists public.admin_booking_detail(text, boolean);
drop function if exists public.admin_dashboard_stats(date, text, boolean);

CREATE OR REPLACE FUNCTION public.admin_booking_detail(p_lookup text, p_include_contact boolean DEFAULT true)
 RETURNS TABLE(booking_uuid uuid, booking_id text, customer_name text, customer_mobile text, event_name text, event_slug text, venue_name text, venue_address text, city text, event_date date, start_time time without time zone, end_time time without time zone, pass_name text, pass_composition text, quantity integer, number_of_people integer, subtotal integer, total_amount integer, currency text, booking_status text, payment_status text, razorpay_order_id text, razorpay_payment_id text, notes text, created_at timestamp with time zone, updated_at timestamp with time zone, passes jsonb, check_ins jsonb, payment_events jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with target as (
    select b.*
    from public.bookings b
    where coalesce(btrim(p_lookup), '') <> ''
      and (
        lower(b.booking_id) = lower(btrim(p_lookup))
        or b.razorpay_payment_id = btrim(p_lookup)
        or b.razorpay_order_id = btrim(p_lookup)
        or exists (
          select 1 from public.digital_passes dp
          where dp.booking_id = b.id and lower(dp.pass_id) = lower(btrim(p_lookup))
        )
      )
    limit 1
  )
  select
    b.id,
    b.booking_id,
    b.customer_name,
    case when p_include_contact then b.customer_mobile end,
    e.name,
    e.slug,
    e.venue_name,
    e.venue_address,
    e.city,
    d.event_date,
    d.start_time,
    d.end_time,
    p.name,
    p.composition,
    b.quantity,
    b.number_of_people,
    case when p_include_contact then b.subtotal end,
    case when p_include_contact then b.total_amount end,
    e.currency,
    b.booking_status,
    b.payment_status,
    case when p_include_contact then b.razorpay_order_id end,
    case when p_include_contact then b.razorpay_payment_id end,
    case when p_include_contact then b.notes end,
    b.created_at,
    b.updated_at,
    coalesce(
      (
        select jsonb_agg(
                 jsonb_build_object(
                   'pass_id', dp.pass_id,
                   'pass_number', dp.pass_number,
                   'status', dp.status,
                   'checked_in', dp.checked_in,
                   'checked_in_at', dp.checked_in_at,
                   'valid_date', dp.valid_date
                 )
                 order by dp.pass_number
               )
        from public.digital_passes dp
        where dp.booking_id = b.id
      ),
      '[]'::jsonb
    ),
    coalesce(
      (
        select jsonb_agg(
                 jsonb_build_object(
                   'checked_in_at', ci.checked_in_at,
                   'gate', ci.gate,
                   'notes', ci.notes,
                   'pass_id', dp.pass_id
                 )
                 order by ci.checked_in_at
               )
        from public.check_ins ci
        join public.digital_passes dp on dp.id = ci.digital_pass_id
        where dp.booking_id = b.id
      ),
      '[]'::jsonb
    ),
    case
      when p_include_contact then coalesce(
        (
          select jsonb_agg(
                   jsonb_build_object(
                     'event_id', pe.event_id,
                     'event_type', pe.event_type,
                     'outcome', pe.outcome,
                     'amount_paise', pe.amount_paise,
                     'received_at', pe.received_at,
                     'processed_at', pe.processed_at
                   )
                   order by pe.received_at
                 )
          from public.payment_events pe
          where pe.razorpay_order_id = b.razorpay_order_id
             or (b.razorpay_payment_id is not null and pe.razorpay_payment_id = b.razorpay_payment_id)
        ),
        '[]'::jsonb
      )
    end
  from target b
  join public.event_dates d     on d.id = b.event_date_id
  join public.events e          on e.id = d.event_id
  join public.pass_categories p on p.id = b.pass_category_id;
$function$;

CREATE OR REPLACE FUNCTION public.admin_pass_list(p_query text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_check_in text DEFAULT NULL::text, p_event_date_id uuid DEFAULT NULL::uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_include_contact boolean DEFAULT true, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0)
 RETURNS TABLE(pass_uuid uuid, pass_id text, pass_number integer, pass_status text, checked_in boolean, checked_in_at timestamp with time zone, valid_date date, gate text, admitted_by text, issued_at timestamp with time zone, booking_uuid uuid, booking_id text, booking_status text, payment_status text, customer_name text, customer_mobile text, pass_name text, quantity integer, number_of_people integer, total_amount integer, currency text, event_name text, start_time time without time zone, end_time time without time zone, passes_on_booking integer, total_count integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with params as (
    select
      nullif(left(btrim(coalesce(p_query, '')), 64), '') as q,
      public.admin_search_pattern(p_query)               as q_like,
      public.admin_search_digits(p_query)                as q_digits,
      greatest(1, least(coalesce(p_limit, 25), 100))     as page_size,
      greatest(0, coalesce(p_offset, 0))                 as page_offset,
      case when p_status in ('active', 'used', 'cancelled', 'expired')
           then p_status end                             as status,
      case when p_check_in in ('in', 'out') then p_check_in end as check_in,
      -- The night a filter asks for, resolved once. An id that matches no night
      -- resolves to null, and nothing matches a null night — the honest answer.
      (select d.event_date from public.event_dates d where d.id = p_event_date_id) as night
  ),
  matched as (
    select
      dp.id,
      dp.created_at,
      b.booking_id,
      dp.pass_number,
      count(*) over ()::integer as total_count
    from public.digital_passes dp
    join public.bookings b on b.id = dp.booking_id
    cross join params p
    where (
        p.q is null
        or dp.pass_id ilike '%' || p.q_like || '%'
        or b.booking_id ilike '%' || p.q_like || '%'
        or b.customer_name ilike '%' || p.q_like || '%'
        or (p.q_digits <> '' and regexp_replace(b.customer_mobile, '\D', '', 'g') like '%' || p.q_digits || '%')
      )
      and (p.status is null or dp.status = p.status)
      -- "in" and "out" are about the pass's own flag, not about its status: a pass
      -- cancelled after the guest was admitted is still a pass that let somebody in.
      and (p.check_in is null
           or (p.check_in = 'in' and dp.checked_in)
           or (p.check_in = 'out' and not dp.checked_in))
      and (p.night is null or dp.valid_date = p.night)
      and (p_from is null or dp.valid_date >= p_from)
      and (p_to is null or dp.valid_date <= p_to)
  ),
  page as (
    select m.id, m.booking_id, m.pass_number, m.total_count
    from matched m
    order by m.created_at desc, m.booking_id desc, m.pass_number desc
    limit (select page_size from params)
    offset (select page_offset from params)
  )
  select
    dp.id,
    dp.pass_id,
    dp.pass_number,
    dp.status,
    dp.checked_in,
    dp.checked_in_at,
    dp.valid_date,
    ci.gate,
    null::text,
    dp.created_at,
    b.id,
    b.booking_id,
    b.booking_status,
    b.payment_status,
    b.customer_name,
    case when p_include_contact then b.customer_mobile end,
    pc.name,
    b.quantity,
    b.number_of_people,
    case when p_include_contact then b.total_amount end,
    e.currency,
    e.name,
    d.start_time,
    d.end_time,
    -- How many passes this booking holds in total: a door needs to know that the
    -- guest in front of them is pass 1 of 4, without opening the booking.
    (select count(*)::integer from public.digital_passes allp where allp.booking_id = b.id),
    pg.total_count
  from page pg
  join public.digital_passes dp on dp.id = pg.id
  join public.bookings b         on b.id = dp.booking_id
  -- The night the booking is for. The pass's own valid_date is the same date by
  -- construction (the payment function copies it), so this is a lookup, not a join
  -- that could drop a pass.
  join public.event_dates d      on d.id = b.event_date_id
  join public.events e           on e.id = d.event_id
  join public.pass_categories pc on pc.id = b.pass_category_id
  left join public.check_ins ci  on ci.digital_pass_id = dp.id
  order by dp.created_at desc, b.booking_id desc, dp.pass_number desc;
$function$;

CREATE OR REPLACE FUNCTION public.admin_dashboard_stats(p_today date, p_tz text DEFAULT 'UTC'::text, p_include_revenue boolean DEFAULT true)
 RETURNS TABLE(bookings_total integer, bookings_confirmed integer, bookings_paid integer, bookings_pending integer, bookings_refunded integer, bookings_today integer, revenue_total integer, revenue_today integer, revenue_refunded integer, check_ins_total integer, check_ins_today integer, passes_issued integer, passes_active integer, passes_used integer, people_paid integer, capacity_total integer, capacity_taken integer, capacity_available integer, tonight_date date, tonight_capacity integer, tonight_taken integer, tonight_available integer, nights_total integer, nights_upcoming integer, gallery_published integer, gallery_draft integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with booked as (
    select
      b.id,
      b.number_of_people,
      b.total_amount,
      b.booking_status,
      b.payment_status,
      (b.created_at at time zone p_tz)::date as booked_on,
      d.event_date,
      d.status as night_status
      from public.bookings b
      join public.event_dates d on d.id = b.event_date_id
  ),
  paid as (
    select * from booked where payment_status = 'paid'
  ),
  -- Capacity is a property of a *night*, so these are the nights themselves. Summing
  -- capacity over booking rows would count a busy night's capacity once per booking,
  -- which is the kind of wrong number that looks plausible on a dashboard.
  upcoming_nights as (
    select d.id, d.event_date, d.capacity
      from public.event_dates d
     where d.status = 'scheduled'
       and d.event_date >= p_today
  ),
  tonight_nights as (
    select * from upcoming_nights where event_date = p_today
  ),
  taken_upcoming as (
    select coalesce(sum(b.number_of_people), 0) as people
      from public.bookings b
      join public.event_dates d on d.id = b.event_date_id
     where b.payment_status = 'paid'
       and d.status = 'scheduled'
       and d.event_date >= p_today
  ),
  taken_tonight as (
    select coalesce(sum(b.number_of_people), 0) as people
      from public.bookings b
      join public.event_dates d on d.id = b.event_date_id
     where b.payment_status = 'paid'
       and d.status = 'scheduled'
       and d.event_date = p_today
  )
  select
    (select count(*)::integer from booked),
    (select count(*)::integer from booked where booking_status = 'confirmed'),
    (select count(*)::integer from booked where payment_status = 'paid'),
    (select count(*)::integer from booked where payment_status = 'unpaid'),
    (select count(*)::integer from booked where payment_status = 'refunded'),
    (select count(*)::integer from booked where booked_on = p_today),

    case when p_include_revenue
         then (select coalesce(sum(total_amount), 0)::integer from paid)
    end,
    case when p_include_revenue
         then (select coalesce(sum(total_amount), 0)::integer from paid where booked_on = p_today)
    end,
    case when p_include_revenue
         then (select coalesce(sum(total_amount), 0)::integer from booked where payment_status = 'refunded')
    end,

    (select count(*)::integer from public.check_ins),
    (select count(*)::integer from public.check_ins
      where (checked_in_at at time zone p_tz)::date = p_today),

    (select count(*)::integer from public.digital_passes),
    (select count(*)::integer from public.digital_passes where status = 'active' and not checked_in),
    (select count(*)::integer from public.digital_passes where checked_in),

    (select coalesce(sum(number_of_people), 0)::integer from paid),
    (select coalesce(sum(capacity), 0)::integer from upcoming_nights),
    (select people::integer from taken_upcoming),
    (select greatest(
              coalesce((select sum(capacity) from upcoming_nights), 0)
              - (select people from taken_upcoming),
              0
            )::integer),

    (select min(event_date) from tonight_nights),
    (select coalesce(sum(capacity), 0)::integer from tonight_nights),
    (select people::integer from taken_tonight),
    (select greatest(
              coalesce((select sum(capacity) from tonight_nights), 0)
              - (select people from taken_tonight),
              0
            )::integer),

    (select count(*)::integer from public.event_dates),
    (select count(*)::integer from public.event_dates
      where event_date >= p_today and status = 'scheduled'),
    (select count(*)::integer from public.gallery where status = 'published'),
    (select count(*)::integer from public.gallery where status <> 'published');
$function$
;;


revoke all on function public.admin_booking_detail(text, boolean) from public, anon, authenticated;
revoke all on function public.admin_dashboard_stats(date, text, boolean) from public, anon, authenticated;
grant execute on function public.admin_booking_detail(text, boolean) to service_role;
grant execute on function public.admin_dashboard_stats(date, text, boolean) to service_role;

-- ---------------------------------------------------------------------------
-- 4 · The gate verdict, without a staff table
-- ---------------------------------------------------------------------------
-- Dropped in dependency order: the two entry points are SQL functions, so they
-- hold a real dependency on pass_entry.

drop function if exists public.scan_pass(text, date, uuid);
drop function if exists public.check_in_pass(text, date, uuid, text);
drop function if exists public.pass_entry(text, date, uuid, boolean, text);

CREATE OR REPLACE FUNCTION public.pass_entry(p_qr_token text, p_gate_date date, p_commit boolean, p_gate text DEFAULT NULL::text)
 RETURNS TABLE(outcome text, reason text, pass_id text, pass_status text, checked_in boolean, checked_in_at timestamp with time zone, pass_number integer, pass_total integer, customer_name text, pass_name text, pass_composition text, booking_reference text, booking_status text, payment_status text, event_name text, event_date date, start_time time without time zone, end_time time without time zone, venue_name text, venue_address text, city text, gate_date date, staff_name text, check_in_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  -- The single admin's label, recorded on the check-in row. There is no staff table
  -- any more: the admin session is proven at the edge (src/proxy.ts), not in here.
  v_staff_name text;
  v_pass    record;
  v_total   integer;
  v_updated integer;
  v_log_id  uuid;
begin
  -- 0. Nobody to look up. The scanner is the single admin, who was authenticated
  --    before this function was ever reached, so the verdict starts here.
  v_staff_name := 'Admin';

  -- 1. The shape first: a token that is not 64 hex characters cannot exist, so the
  --    lookup is skipped entirely (and a 1 MB "token" never reaches a query).
  if p_qr_token is null or p_qr_token !~ '^[0-9a-f]{64}$' then
    return query select
      'invalid'::text,
      'That code is not a pass for this event.'::text,
      null::text, null::text, null::boolean, null::timestamptz,
      null::integer, null::integer, null::text, null::text, null::text,
      null::text, null::text, null::text, null::text, null::date,
      null::time, null::time, null::text, null::text, null::text,
      p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  -- 2. Pass, booking, night and event, in one read. `for update of dp` locks the
  --    pass row: a second scanner waits here and then sees the committed result,
  --    which is what makes the compare-and-swap below impossible to lose.
  select dp.id,
         dp.pass_id,
         dp.status,
         dp.checked_in,
         dp.checked_in_at,
         dp.valid_date,
         b.event_date_id,
         dp.pass_number,
         b.id as booking_uuid,
         b.booking_id as booking_reference,
         b.booking_status,
         b.payment_status,
         b.customer_name,
         pc.name as pass_name,
         pc.composition as pass_composition,
         e.name as event_name,
         e.venue_name,
         e.venue_address,
         e.city,
         e.status as event_status,
         d.status as night_status,
         d.start_time,
         d.end_time
    into v_pass
  from public.digital_passes dp
  join public.bookings b on b.id = dp.booking_id
  join public.event_dates d on d.id = b.event_date_id
  join public.events e on e.id = d.event_id
  join public.pass_categories pc on pc.id = b.pass_category_id
  where dp.qr_token = p_qr_token
  for update of dp;

  if not found then
    return query select
      'invalid'::text,
      'That code does not match any pass for this event.'::text,
      null::text, null::text, null::boolean, null::timestamptz,
      null::integer, null::integer, null::text, null::text, null::text,
      null::text, null::text, null::text, null::text, null::date,
      null::time, null::time, null::text, null::text, null::text,
      p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  select count(*)::integer
    into v_total
  from public.digital_passes dp
  where dp.booking_id = (select b.id from public.bookings b where b.booking_id = v_pass.booking_reference);

  -- 3. Verdict, worst first. Every branch returns the pass details it has, so the
  --    scanner can show who is standing there even when the answer is no.
  if v_pass.night_status = 'cancelled' or v_pass.event_status <> 'published' then
    return query select 'invalid'::text, 'That night is not taking place.'::text,
      v_pass.pass_id, v_pass.status, v_pass.checked_in, v_pass.checked_in_at,
      v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
      v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
      v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
      v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  if v_pass.status = 'cancelled'
     or v_pass.booking_status in ('refunded', 'cancelled')
     or v_pass.payment_status = 'refunded' then
    return query select 'refunded'::text, 'The booking behind this pass was cancelled or refunded.'::text,
      v_pass.pass_id, v_pass.status, v_pass.checked_in, v_pass.checked_in_at,
      v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
      v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
      v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
      v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  if v_pass.booking_status <> 'confirmed' or v_pass.payment_status <> 'paid' then
    return query select 'payment_not_verified'::text, 'No verified payment is recorded for this booking.'::text,
      v_pass.pass_id, v_pass.status, v_pass.checked_in, v_pass.checked_in_at,
      v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
      v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
      v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
      v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  if v_pass.checked_in or v_pass.status = 'used' then
    return query select 'already_used'::text, 'This pass was already scanned at the gate.'::text,
      v_pass.pass_id, v_pass.status, v_pass.checked_in, v_pass.checked_in_at,
      v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
      v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
      v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
      v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  if v_pass.status = 'expired' or v_pass.valid_date < p_gate_date then
    return query select 'expired'::text, 'This pass was for an earlier night.'::text,
      v_pass.pass_id, v_pass.status, v_pass.checked_in, v_pass.checked_in_at,
      v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
      v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
      v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
      v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  if v_pass.valid_date > p_gate_date then
    return query select 'not_yet_valid'::text, 'This pass is for a later night.'::text,
      v_pass.pass_id, v_pass.status, v_pass.checked_in, v_pass.checked_in_at,
      v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
      v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
      v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
      v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  if v_pass.status <> 'active' then
    return query select 'invalid'::text, 'This pass is no longer usable.'::text,
      v_pass.pass_id, v_pass.status, v_pass.checked_in, v_pass.checked_in_at,
      v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
      v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
      v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
      v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  -- 4. The guest may come in.
  if not p_commit then
    -- Preview only: the scanner shows this, and the button asks for the real thing.
    return query select 'valid'::text, null::text,
      v_pass.pass_id, v_pass.status, v_pass.checked_in, v_pass.checked_in_at,
      v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
      v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
      v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
      v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  -- Compare-and-swap: the row only flips if it is still unused and active. The
  -- `for update` above already serialises competing scanners; this makes the
  -- guarantee independent of lock timing, and a losing caller is told the truth
  -- instead of overwriting the first scan's timestamp.
  update public.digital_passes dp
  set checked_in = true,
      checked_in_at = now(),
      status = 'used'
  where dp.id = v_pass.id
    and dp.checked_in = false
    and dp.status = 'active';

  get diagnostics v_updated = row_count;

  if v_updated = 0 then
    return query select 'already_used'::text, 'This pass was already scanned at the gate.'::text,
      v_pass.pass_id, v_pass.status, true, v_pass.checked_in_at,
      v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
      v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
      v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
      v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, null::uuid;

    return;
  end if;

  -- The audit row. `on conflict do nothing` means the unique constraint on
  -- digital_pass_id ends a race with a duplicate entry rather than an error, and
  -- `notes` keeps which gate (or device label) scanned the pass.
  insert into public.check_ins (digital_pass_id, event_date_id, gate, booking_id, notes)
  values (
    v_pass.id,
    v_pass.event_date_id,
    nullif(btrim(coalesce(p_gate, '')), ''),
    v_pass.booking_uuid,
    'web scanner'
  )
  on conflict (digital_pass_id) do nothing
  returning id into v_log_id;

  return query select 'checked_in'::text, null::text,
    v_pass.pass_id, 'used'::text, true, now(),
    v_pass.pass_number, v_total, v_pass.customer_name, v_pass.pass_name, v_pass.pass_composition,
    v_pass.booking_reference, v_pass.booking_status, v_pass.payment_status,
    v_pass.event_name, v_pass.valid_date, v_pass.start_time, v_pass.end_time,
    v_pass.venue_name, v_pass.venue_address, v_pass.city, p_gate_date, v_staff_name, v_log_id;
end;
$function$;


create or replace function public.scan_pass(
  p_qr_token  text,
  p_gate_date date
)
returns table (
  outcome text, reason text, pass_id text, pass_status text, checked_in boolean,
  checked_in_at timestamptz, pass_number integer, pass_total integer, customer_name text,
  pass_name text, pass_composition text, booking_reference text, booking_status text,
  payment_status text, event_name text, event_date date, start_time time, end_time time,
  venue_name text, venue_address text, city text, gate_date date, staff_name text, check_in_id uuid
)
language sql
security definer
set search_path = public
as $$
  select * from public.pass_entry(p_qr_token, p_gate_date, false, null);
$$;

comment on function public.scan_pass(text, date) is
  'Gate verdict for one QR token, without writing anything. Server-only; the caller is authenticated by the app.';

create or replace function public.check_in_pass(
  p_qr_token  text,
  p_gate_date date,
  p_gate      text default null
)
returns table (
  outcome text, reason text, pass_id text, pass_status text, checked_in boolean,
  checked_in_at timestamptz, pass_number integer, pass_total integer, customer_name text,
  pass_name text, pass_composition text, booking_reference text, booking_status text,
  payment_status text, event_name text, event_date date, start_time time, end_time time,
  venue_name text, venue_address text, city text, gate_date date, staff_name text, check_in_id uuid
)
language sql
security definer
set search_path = public
as $$
  select * from public.pass_entry(p_qr_token, p_gate_date, true, p_gate);
$$;

comment on function public.check_in_pass(text, date, text) is
  'Admits one guest: marks the pass used and writes exactly one check_ins row. Server-only.';

-- Nothing here is reachable from a browser key. service_role is the role the
-- server uses until the Prisma port lands; after that, the table owner.
revoke all on function public.pass_entry(text, date, boolean, text) from public, anon, authenticated, service_role;
revoke all on function public.scan_pass(text, date) from public, anon, authenticated;
revoke all on function public.check_in_pass(text, date, text) from public, anon, authenticated;
grant execute on function public.scan_pass(text, date) to service_role;
grant execute on function public.check_in_pass(text, date, text) to service_role;


-- ===========================================================================
-- 20260923091000_no_customer_email.sql
-- ===========================================================================

-- =============================================================================
-- 18 · No customer email
--
-- The brief removes the customer's email address from the product entirely: the
-- form asks for a name and a mobile number, the pass shows a name and a mobile
-- number, and the database stores a name and a mobile number. The organizer's own
-- contact address (events.contact_email) is a different field and is untouched.
--
-- The column was NOT NULL *and* had a regex CHECK, and it was a parameter of
-- create_pending_booking() and a column of four admin read models — so this
-- migration is the column, the constraint, and the six functions that mentioned
-- it, restated from their live definitions with the email taken out and nothing
-- else changed.
--
-- Idempotent: guards throughout.
-- =============================================================================

-- ---------------------------------------------------------------------------
-- 1 · The column and its constraint
-- ---------------------------------------------------------------------------
-- Dropped by name discovered from the catalog: a table constraint that the column
-- depends on would otherwise block the drop.
do $$
declare c text;
begin
  for c in
    select conname from pg_constraint
     where conrelid = 'public.bookings'::regclass
       and contype = 'c'
       and pg_get_constraintdef(oid) ilike '%customer_email%'
  loop
    execute format('alter table public.bookings drop constraint %I', c);
  end loop;
end $$;

alter table public.bookings drop column if exists customer_email;

-- ---------------------------------------------------------------------------
-- 2 · create_pending_booking, without the email argument
-- ---------------------------------------------------------------------------
-- A new signature, so the old 9-argument version must go explicitly: otherwise
-- `create or replace` would leave it behind as a second overload that callers could
-- still reach with an email argument.

drop function if exists public.create_pending_booking(uuid, uuid, uuid, text, text, text, integer, integer, text);

CREATE OR REPLACE FUNCTION public.create_pending_booking(p_event_id uuid, p_event_date_id uuid, p_pass_category_id uuid, p_customer_name text, p_customer_mobile text, p_quantity integer, p_number_of_people integer, p_idempotency_key text DEFAULT NULL::text)
 RETURNS TABLE(booking_uuid uuid, booking_reference text, public_token uuid, booking_status text, payment_status text, quantity integer, number_of_people integer, subtotal integer, total_amount integer, event_id uuid, event_date_id uuid, event_date date, start_time time without time zone, end_time time without time zone, pass_category_id uuid, pass_name text, pass_composition text, currency text, razorpay_order_id text, created_at timestamp with time zone, was_existing boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_night       record;
  v_pass        record;
  v_event       record;
  v_existing    record;
  v_booked      integer;
  v_remaining   integer;
  v_required    integer;
  v_booking_id  uuid;
  v_reference   text;
begin
  -- Idempotency: has this attempt already produced a booking?
  if p_idempotency_key is not null and length(btrim(p_idempotency_key)) > 0 then
    select b.id into v_existing
    from public.bookings b
    where b.idempotency_key = btrim(p_idempotency_key);

    if found then
      return query
        select b.id, b.booking_id, b.public_token, b.booking_status, b.payment_status, b.quantity,
               b.number_of_people, b.subtotal, b.total_amount, d.event_id, d.id, d.event_date,
               d.start_time, d.end_time, p.id, p.name, p.composition, e.currency,
               b.razorpay_order_id, b.created_at, true
        from public.bookings b
        join public.event_dates d on d.id = b.event_date_id
        join public.pass_categories p on p.id = b.pass_category_id
        join public.events e on e.id = d.event_id
        where b.id = v_existing.id;

      return;
    end if;
  end if;

  -- Lock the night: concurrent attempts for the same night queue here, so the
  -- capacity read below cannot be stale.
  select d.id, d.event_id, d.event_date, d.status, d.capacity, d.capacity_held,
         d.booking_open, d.start_time, d.end_time
    into v_night
  from public.event_dates d
  where d.id = p_event_date_id
  for update;

  if not found then
    raise exception 'night_not_found' using errcode = 'PB006';
  end if;

  if v_night.event_id <> p_event_id then
    raise exception 'night_not_found' using errcode = 'PB006';
  end if;

  select e.id, e.name, e.status, e.currency into v_event
  from public.events e
  where e.id = p_event_id;

  if not found or v_event.status <> 'published' then
    raise exception 'night_not_bookable' using errcode = 'PB002';
  end if;

  if v_night.status <> 'scheduled' then
    raise exception 'night_not_bookable' using errcode = 'PB002';
  end if;

  -- An organiser can close booking on a night without cancelling it (gate sales
  -- only, a private hire, a capacity recount). Same verdict, same code: from the
  -- booking flow's point of view the night is simply not on sale.
  if v_night.booking_open is not true then
    raise exception 'night_not_bookable' using errcode = 'PB002';
  end if;

  select p.id, p.name, p.composition, p.price_inr, p.number_of_people, p.max_per_booking, p.is_active
    into v_pass
  from public.pass_categories p
  where p.id = p_pass_category_id;

  if not found or v_pass.is_active is not true then
    raise exception 'pass_not_available' using errcode = 'PB003';
  end if;

  if not exists (
    select 1 from public.pass_categories p
    where p.id = p_pass_category_id and p.event_id = p_event_id
  ) then
    raise exception 'pass_not_available' using errcode = 'PB003';
  end if;

  if p_quantity is null or p_quantity < 1 or p_quantity > v_pass.max_per_booking then
    raise exception 'quantity_invalid' using errcode = 'PB004', detail = v_pass.max_per_booking::text;
  end if;

  v_required := p_quantity * v_pass.number_of_people;

  if p_number_of_people is null or p_number_of_people <> v_required then
    raise exception 'people_mismatch' using errcode = 'PB005', detail = v_required::text;
  end if;

  -- Capacity, counted the same way as the public availability function: paid
  -- bookings only, with the seats the organiser has held back removed from what is
  -- on sale. A pending booking does not hold a place until it is paid.
  select coalesce(sum(b.number_of_people) filter (where b.payment_status = 'paid'), 0)::integer
    into v_booked
  from public.bookings b
  where b.event_date_id = p_event_date_id;

  -- Seats an organiser has held back are subtracted before the booking is measured
  -- against what is left: a night with 1,000 seats and 50 held has 950 on sale.
  v_remaining := greatest(v_night.capacity - v_night.capacity_held - v_booked, 0);

  if v_required > v_remaining then
    raise exception 'capacity_unavailable' using errcode = 'PB001', detail = v_remaining::text;
  end if;

  -- Same content, brand-new key inside the double-submit window (a page reload
  -- loses the key): treat it as the same attempt instead of creating a second
  -- booking. Paid or older bookings are never reused.
  select b.id into v_existing
  from public.bookings b
  where b.event_date_id = p_event_date_id
    and b.pass_category_id = p_pass_category_id
    and b.customer_mobile = p_customer_mobile
    and b.quantity = p_quantity
    and b.booking_status = 'pending'
    and b.payment_status = 'unpaid'
    and b.created_at > now() - interval '15 minutes'
  order by b.created_at desc
  limit 1;

  if found then
    return query
      select b.id, b.booking_id, b.public_token, b.booking_status, b.payment_status, b.quantity,
             b.number_of_people, b.subtotal, b.total_amount, d.event_id, d.id, d.event_date,
             d.start_time, d.end_time, p.id, p.name, p.composition, e.currency,
             b.razorpay_order_id, b.created_at, true
      from public.bookings b
      join public.event_dates d on d.id = b.event_date_id
      join public.pass_categories p on p.id = b.pass_category_id
      join public.events e on e.id = d.event_id
      where b.id = v_existing.id;

    return;
  end if;

  -- number_of_people, subtotal and total_amount are deliberately not part of the
  -- INSERT column list: the set_booking_amounts() trigger computes all three from
  -- pass_categories before the row is written.
  insert into public.bookings (
    customer_name, customer_mobile,
    event_date_id, pass_category_id,
    quantity, booking_status, payment_status, idempotency_key
  )
  values (
    btrim(p_customer_name), p_customer_mobile,
    p_event_date_id, p_pass_category_id,
    p_quantity, 'pending', 'unpaid',
    nullif(btrim(coalesce(p_idempotency_key, '')), '')
  )
  returning id, bookings.booking_id into v_booking_id, v_reference;

  return query
    select b.id, b.booking_id, b.public_token, b.booking_status, b.payment_status, b.quantity,
           b.number_of_people, b.subtotal, b.total_amount, d.event_id, d.id, d.event_date,
           d.start_time, d.end_time, p.id, p.name, p.composition, e.currency,
           b.razorpay_order_id, b.created_at, false
    from public.bookings b
    join public.event_dates d on d.id = b.event_date_id
    join public.pass_categories p on p.id = b.pass_category_id
    join public.events e on e.id = d.event_id
    where b.id = v_booking_id;
end;
$function$;


revoke all on function public.create_pending_booking(uuid, uuid, uuid, text, text, integer, integer, text) from public, anon, authenticated;
grant execute on function public.create_pending_booking(uuid, uuid, uuid, text, text, integer, integer, text) to service_role;

-- ---------------------------------------------------------------------------
-- 3 · The admin read models
-- ---------------------------------------------------------------------------
-- Three of them return customer_email in their result set, so their return type
-- changes and `create or replace` cannot do it — drop, recreate, re-grant. The
-- other two only searched by it, so they are replaced in place.

drop function if exists public.admin_recent_bookings(integer, boolean);
drop function if exists public.admin_search_bookings(text, date, date, uuid, text, text, text, boolean, integer, integer);

CREATE OR REPLACE FUNCTION public.admin_recent_bookings(p_limit integer DEFAULT 8, p_include_contact boolean DEFAULT true)
 RETURNS TABLE(booking_uuid uuid, booking_id text, customer_name text, customer_mobile text, event_date date, start_time time without time zone, pass_name text, quantity integer, number_of_people integer, total_amount integer, currency text, booking_status text, payment_status text, created_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    b.id,
    b.booking_id,
    b.customer_name,
    case when p_include_contact then b.customer_mobile end,
    d.event_date,
    d.start_time,
    p.name,
    b.quantity,
    b.number_of_people,
    case when p_include_contact then b.total_amount end,
    e.currency,
    b.booking_status,
    b.payment_status,
    b.created_at
  from public.bookings b
  join public.event_dates d     on d.id = b.event_date_id
  join public.events e          on e.id = d.event_id
  join public.pass_categories p on p.id = b.pass_category_id
  order by b.created_at desc
  limit greatest(1, least(coalesce(p_limit, 8), 50));
$function$;

CREATE OR REPLACE FUNCTION public.admin_search_bookings(p_query text DEFAULT NULL::text, p_event_date_from date DEFAULT NULL::date, p_event_date_to date DEFAULT NULL::date, p_pass_category_id uuid DEFAULT NULL::uuid, p_payment_status text DEFAULT NULL::text, p_booking_status text DEFAULT NULL::text, p_check_in_status text DEFAULT NULL::text, p_include_contact boolean DEFAULT true, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0)
 RETURNS TABLE(booking_uuid uuid, booking_id text, customer_name text, customer_mobile text, event_name text, event_slug text, event_date date, start_time time without time zone, end_time time without time zone, pass_name text, pass_composition text, quantity integer, number_of_people integer, total_amount integer, currency text, booking_status text, payment_status text, razorpay_order_id text, razorpay_payment_id text, created_at timestamp with time zone, passes_issued integer, passes_checked_in integer, check_in_times timestamp with time zone[], pass_ids text[], total_count integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with params as (
    select
      -- An empty search box is not a search: it means "the list", which is what a
      -- management screen should open on. Long input is truncated rather than
      -- refused: nobody is typing a 64-character booking reference.
      nullif(left(btrim(coalesce(p_query, '')), 64), '')   as q,
      -- The same term with LIKE's own wildcards neutralised, so a search for "50%"
      -- or "a_b" means those characters and not "anything". Without this, "%" would
      -- quietly return every booking in the event.
      replace(
        replace(
          replace(left(btrim(coalesce(p_query, '')), 64), '\', '\\'),
          '%', '\%'
        ),
        '_', '\_'
      )                                                    as q_like,
      -- The digits of the search term, for matching a mobile number however it was
      -- typed — but only when the term *is* a number. Empty string means the mobile
      -- clause is skipped, and that is what keeps two very different searches apart:
      --
      --   * "98123 45678" and "+91 98000 01001" are phone numbers, and the digits are
      --     matched against the mobile column without regard to how they were typed;
      --   * "Bulk Fixture 01" and "Room 101" are names with numbers in them. Their
      --     digits are not a phone number, and matching "01" against every mobile
      --     containing "01" would answer a name search with half the event.
      --
      -- A term with no letters qualifies, and only from four digits up: two digits
      -- appear in most phone numbers, which is the same as matching everything.
      case
        when left(btrim(coalesce(p_query, '')), 64) !~ '[[:alpha:]]'
         and length(regexp_replace(coalesce(p_query, ''), '\D', '', 'g')) >= 4
        then regexp_replace(coalesce(p_query, ''), '\D', '', 'g')
        else ''
      end                                                    as q_digits,
      greatest(1, least(coalesce(p_limit, 25), 100))       as page_size,
      greatest(0, coalesce(p_offset, 0))                   as page_offset,
      -- Only values the schema actually holds become filters. A typo in the query
      -- string narrows nothing; it does not silently return an empty list that looks
      -- like "no such booking".
      case when p_payment_status in ('unpaid', 'created', 'paid', 'failed', 'refunded')
           then p_payment_status end                       as payment_status,
      case when p_booking_status in ('pending', 'confirmed', 'cancelled', 'expired', 'refunded')
           then p_booking_status end                       as booking_status,
      case when p_check_in_status in ('none', 'some', 'all')
           then p_check_in_status end                      as check_in_status
  ),
  pass_state as (
    select
      dp.booking_id                                      as booking_uuid,
      count(*)::integer                                  as issued,
      count(*) filter (where dp.checked_in)::integer      as checked_in,
      array_remove(array_agg(dp.checked_in_at order by dp.pass_number), null) as check_in_times,
      -- Every pass on the booking, in the order they were issued: the numbers a
      -- guest reads out at the gate, and the rows a door list is printed from.
      array_agg(dp.pass_id order by dp.pass_number)        as pass_ids
    from public.digital_passes dp
    group by dp.booking_id
  ),
  matched as (
    select b.id, b.created_at
    from public.bookings b
    join public.event_dates d     on d.id = b.event_date_id
    left join pass_state ps       on ps.booking_uuid = b.id
    cross join params p
    where (
        p.q is null
        or b.booking_id ilike '%' || p.q_like || '%'
        or b.customer_name ilike '%' || p.q_like || '%'
        -- The gateway ids, so a payment id from a Razorpay receipt finds its booking.
        or b.razorpay_payment_id ilike '%' || p.q_like || '%'
        or b.razorpay_order_id ilike '%' || p.q_like || '%'
        or (
          p.q_digits <> ''
          and regexp_replace(b.customer_mobile, '\D', '', 'g') like '%' || p.q_digits || '%'
        )
        -- A pass id, printed on the guest's ticket.
        or exists (
          select 1 from public.digital_passes dp
          where dp.booking_id = b.id and dp.pass_id ilike '%' || p.q_like || '%'
        )
      )
      and (p_event_date_from is null or d.event_date >= p_event_date_from)
      and (p_event_date_to   is null or d.event_date <= p_event_date_to)
      and (p_pass_category_id is null or b.pass_category_id = p_pass_category_id)
      and (p.payment_status is null or b.payment_status = p.payment_status)
      and (p.booking_status is null or b.booking_status = p.booking_status)
      and (
        p.check_in_status is null
        -- "none" means nobody has been admitted yet: no pass checked in, whether or
        -- not passes were issued (an unpaid booking has none).
        or (p.check_in_status = 'none' and coalesce(ps.checked_in, 0) = 0)
        -- "some" is the interesting one: part of a group is inside.
        or (
          p.check_in_status = 'some'
          and coalesce(ps.checked_in, 0) > 0
          and coalesce(ps.checked_in, 0) < coalesce(ps.issued, 0)
        )
        or (
          p.check_in_status = 'all'
          and coalesce(ps.issued, 0) > 0
          and coalesce(ps.checked_in, 0) = coalesce(ps.issued, 0)
        )
      )
  ),
  counted as (
    -- The size of the whole result set, not of the page: the screen has to say
    -- "showing 1–25 of 240" before the admin scrolls.
    select m.id, m.created_at, count(*) over ()::integer as total_count
    from matched m
  ),
  page as (
    select c.id, c.total_count
    from counted c
    order by c.created_at desc, c.id desc
    limit (select page_size from params)
    offset (select page_offset from params)
  )
  select
    b.id,
    b.booking_id,
    b.customer_name,
    case when p_include_contact then b.customer_mobile end,
    e.name,
    e.slug,
    d.event_date,
    d.start_time,
    d.end_time,
    p.name,
    p.composition,
    b.quantity,
    b.number_of_people,
    case when p_include_contact then b.total_amount end,
    e.currency,
    b.booking_status,
    b.payment_status,
    case when p_include_contact then b.razorpay_order_id end,
    case when p_include_contact then b.razorpay_payment_id end,
    b.created_at,
    coalesce(ps.issued, 0),
    coalesce(ps.checked_in, 0),
    ps.check_in_times,
    coalesce(ps.pass_ids, '{}'::text[]),
    pg.total_count
  from page pg
  join public.bookings b        on b.id = pg.id
  join public.event_dates d     on d.id = b.event_date_id
  join public.events e          on e.id = d.event_id
  join public.pass_categories p on p.id = b.pass_category_id
  left join pass_state ps       on ps.booking_uuid = b.id
  order by b.created_at desc, b.id desc;
$function$;


revoke all on function public.admin_booking_detail(text, boolean) from public, anon, authenticated;
revoke all on function public.admin_recent_bookings(integer, boolean) from public, anon, authenticated;
revoke all on function public.admin_search_bookings(text, date, date, uuid, text, text, text, boolean, integer, integer) from public, anon, authenticated;
grant execute on function public.admin_booking_detail(text, boolean) to service_role;
grant execute on function public.admin_recent_bookings(integer, boolean) to service_role;
grant execute on function public.admin_search_bookings(text, date, date, uuid, text, text, text, boolean, integer, integer) to service_role;

CREATE OR REPLACE FUNCTION public.admin_pass_list(p_query text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_check_in text DEFAULT NULL::text, p_event_date_id uuid DEFAULT NULL::uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_include_contact boolean DEFAULT true, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0)
 RETURNS TABLE(pass_uuid uuid, pass_id text, pass_number integer, pass_status text, checked_in boolean, checked_in_at timestamp with time zone, valid_date date, gate text, admitted_by text, issued_at timestamp with time zone, booking_uuid uuid, booking_id text, booking_status text, payment_status text, customer_name text, customer_mobile text, pass_name text, quantity integer, number_of_people integer, total_amount integer, currency text, event_name text, start_time time without time zone, end_time time without time zone, passes_on_booking integer, total_count integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with params as (
    select
      nullif(left(btrim(coalesce(p_query, '')), 64), '') as q,
      public.admin_search_pattern(p_query)               as q_like,
      public.admin_search_digits(p_query)                as q_digits,
      greatest(1, least(coalesce(p_limit, 25), 100))     as page_size,
      greatest(0, coalesce(p_offset, 0))                 as page_offset,
      case when p_status in ('active', 'used', 'cancelled', 'expired')
           then p_status end                             as status,
      case when p_check_in in ('in', 'out') then p_check_in end as check_in,
      -- The night a filter asks for, resolved once. An id that matches no night
      -- resolves to null, and nothing matches a null night — the honest answer.
      (select d.event_date from public.event_dates d where d.id = p_event_date_id) as night
  ),
  matched as (
    select
      dp.id,
      dp.created_at,
      b.booking_id,
      dp.pass_number,
      count(*) over ()::integer as total_count
    from public.digital_passes dp
    join public.bookings b on b.id = dp.booking_id
    cross join params p
    where (
        p.q is null
        or dp.pass_id ilike '%' || p.q_like || '%'
        or b.booking_id ilike '%' || p.q_like || '%'
        or b.customer_name ilike '%' || p.q_like || '%'
        or (p.q_digits <> '' and regexp_replace(b.customer_mobile, '\D', '', 'g') like '%' || p.q_digits || '%')
      )
      and (p.status is null or dp.status = p.status)
      -- "in" and "out" are about the pass's own flag, not about its status: a pass
      -- cancelled after the guest was admitted is still a pass that let somebody in.
      and (p.check_in is null
           or (p.check_in = 'in' and dp.checked_in)
           or (p.check_in = 'out' and not dp.checked_in))
      and (p.night is null or dp.valid_date = p.night)
      and (p_from is null or dp.valid_date >= p_from)
      and (p_to is null or dp.valid_date <= p_to)
  ),
  page as (
    select m.id, m.booking_id, m.pass_number, m.total_count
    from matched m
    order by m.created_at desc, m.booking_id desc, m.pass_number desc
    limit (select page_size from params)
    offset (select page_offset from params)
  )
  select
    dp.id,
    dp.pass_id,
    dp.pass_number,
    dp.status,
    dp.checked_in,
    dp.checked_in_at,
    dp.valid_date,
    ci.gate,
    null::text,
    dp.created_at,
    b.id,
    b.booking_id,
    b.booking_status,
    b.payment_status,
    b.customer_name,
    case when p_include_contact then b.customer_mobile end,
    pc.name,
    b.quantity,
    b.number_of_people,
    case when p_include_contact then b.total_amount end,
    e.currency,
    e.name,
    d.start_time,
    d.end_time,
    -- How many passes this booking holds in total: a door needs to know that the
    -- guest in front of them is pass 1 of 4, without opening the booking.
    (select count(*)::integer from public.digital_passes allp where allp.booking_id = b.id),
    pg.total_count
  from page pg
  join public.digital_passes dp on dp.id = pg.id
  join public.bookings b         on b.id = dp.booking_id
  -- The night the booking is for. The pass's own valid_date is the same date by
  -- construction (the payment function copies it), so this is a lookup, not a join
  -- that could drop a pass.
  join public.event_dates d      on d.id = b.event_date_id
  join public.events e           on e.id = d.event_id
  join public.pass_categories pc on pc.id = b.pass_category_id
  left join public.check_ins ci  on ci.digital_pass_id = dp.id
  order by dp.created_at desc, b.booking_id desc, dp.pass_number desc;
$function$;

CREATE OR REPLACE FUNCTION public.admin_payment_events(p_query text DEFAULT NULL::text, p_outcome text DEFAULT NULL::text, p_event_type text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_include_contact boolean DEFAULT true, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0)
 RETURNS TABLE(event_uuid uuid, event_id text, event_type text, outcome text, razorpay_order_id text, razorpay_payment_id text, amount_paise integer, received_at timestamp with time zone, processed_at timestamp with time zone, booking_uuid uuid, booking_id text, customer_name text, customer_mobile text, booking_status text, payment_status text, total_amount integer, currency text, total_count integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with params as (
    select
      nullif(left(btrim(coalesce(p_query, '')), 64), '') as q,
      public.admin_search_pattern(p_query)               as q_like,
      public.admin_search_digits(p_query)                as q_digits,
      greatest(1, least(coalesce(p_limit, 25), 100))     as page_size,
      greatest(0, coalesce(p_offset, 0))                 as page_offset,
      -- Only values the schema holds become filters; anything else narrows nothing.
      case when p_outcome in ('received', 'confirmed', 'already_confirmed', 'failed',
                              'refunded', 'ignored', 'duplicate')
           then p_outcome end                            as outcome,
      case when nullif(btrim(coalesce(p_event_type, '')), '') is not null
           then btrim(p_event_type) end                  as event_type
  ),
  matched as (
    select pe.id, pe.received_at
    from public.payment_events pe
    cross join params p
    where (
        p.q is null
        -- Searched over what the gateway sent and over the booking it points at, so
        -- a support thread can start from whichever id the customer quoted.
        or pe.razorpay_order_id ilike '%' || p.q_like || '%'
        or pe.razorpay_payment_id ilike '%' || p.q_like || '%'
        or pe.event_id ilike '%' || p.q_like || '%'
        or pe.event_type ilike '%' || p.q_like || '%'
        or exists (
          select 1
          from public.bookings b
          where (b.razorpay_order_id = pe.razorpay_order_id
                 or (pe.razorpay_payment_id is not null and b.razorpay_payment_id = pe.razorpay_payment_id))
            and (
              b.booking_id ilike '%' || p.q_like || '%'
              or b.customer_name ilike '%' || p.q_like || '%'
              or (p.q_digits <> '' and regexp_replace(b.customer_mobile, '\D', '', 'g') like '%' || p.q_digits || '%')
            )
        )
      )
      and (p.outcome is null or pe.outcome = p.outcome)
      and (p.event_type is null or pe.event_type = p.event_type)
      and (p_from is null or (pe.received_at at time zone 'UTC')::date >= p_from)
      and (p_to   is null or (pe.received_at at time zone 'UTC')::date <= p_to)
  ),
  counted as (
    select m.id, m.received_at, count(*) over ()::integer as total_count
    from matched m
  ),
  page as (
    select c.id, c.total_count
    from counted c
    order by c.received_at desc, c.id desc
    limit (select page_size from params)
    offset (select page_offset from params)
  )
  select
    pe.id,
    pe.event_id,
    pe.event_type,
    pe.outcome,
    pe.razorpay_order_id,
    pe.razorpay_payment_id,
    case when p_include_contact then pe.amount_paise end,
    pe.received_at,
    pe.processed_at,
    b.id,
    b.booking_id,
    b.customer_name,
    case when p_include_contact then b.customer_mobile end,
    b.booking_status,
    b.payment_status,
    case when p_include_contact then b.total_amount end,
    e.currency,
    pg.total_count
  from page pg
  join public.payment_events pe on pe.id = pg.id
  -- At most one booking per delivery: an order id is unique, and a payment id is
  -- unique, so the lateral is a lookup rather than a fan-out.
  left join lateral (
    select bk.*
    from public.bookings bk
    where bk.razorpay_order_id = pe.razorpay_order_id
       or (pe.razorpay_payment_id is not null and bk.razorpay_payment_id = pe.razorpay_payment_id)
    order by bk.created_at desc
    limit 1
  ) b on true
  left join public.event_dates d on d.id = b.event_date_id
  left join public.events e      on e.id = d.event_id
  order by pe.received_at desc, pe.id desc;
$function$;


-- ===========================================================================
-- 20260924090000_database_hero_image.sql
-- ===========================================================================

-- -----------------------------------------------------------------------------
-- Homepage hero artwork: optimized WebP bytes live in Neon, not in Gallery/Blob.
--
-- Gallery media deliberately remains in Vercel Blob. The single homepage hero image
-- is different: it is owned by the event row, saved by Event settings, and streamed
-- from the public hero-image route. The existing hero_image_url stays for legacy
-- installations; new uploads clear it and use hero_image_data instead.
-- -----------------------------------------------------------------------------

alter table public.events
  add column if not exists hero_image_data bytea,
  add column if not exists hero_image_version bigint not null default 0;

do $$
begin
  if not exists (
    select 1
      from pg_constraint
     where conrelid = 'public.events'::regclass
       and conname = 'events_hero_image_data_size'
  ) then
    alter table public.events
      add constraint events_hero_image_data_size
      check (hero_image_data is null or octet_length(hero_image_data) between 1 and 2097152);
  end if;

  if not exists (
    select 1
      from pg_constraint
     where conrelid = 'public.events'::regclass
       and conname = 'events_hero_image_version_nonnegative'
  ) then
    alter table public.events
      add constraint events_hero_image_version_nonnegative
      check (hero_image_version >= 0);
  end if;
end
$$;

comment on column public.events.hero_image_data is
  'Metadata-stripped, optimized WebP bytes for the homepage hero. Separate from gallery media and stored in Neon bytea, never Vercel Blob.';

comment on column public.events.hero_image_version is
  'Incremented when the homepage hero image is replaced or removed, so cached image URLs change with the artwork.';

comment on column public.events.hero_image_url is
  'Legacy external hero URL. New homepage hero uploads use hero_image_data; replacing or removing one clears this URL.';


-- ===========================================================================
-- 20260925090000_editable_site_content.sql
-- ===========================================================================

-- -----------------------------------------------------------------------------
-- Editable site content: public-page copy the organiser can change from admin.
--
-- The About Us text, the gallery heading and the contact-page FAQs have no
-- home of their own in the schema — they are per-event copy, so they live on
-- the event row beside the other public fields. One jsonb column keeps them
-- together and lets later sections extend it without another migration. The
-- shape is validated by the app (never by the browser), and an empty object
-- means "every page falls back to its built-in default copy", so nothing
-- changes visually until the organiser saves something from Event settings.
-- -----------------------------------------------------------------------------

alter table public.events
  add column if not exists site_content jsonb not null default '{}'::jsonb;

do $$
begin
  if not exists (
    select 1
      from pg_constraint
     where conrelid = 'public.events'::regclass
       and conname = 'events_site_content_object'
  ) then
    alter table public.events
      add constraint events_site_content_object
      check (jsonb_typeof(site_content) = 'object');
  end if;
end
$$;

comment on column public.events.site_content is
  'Organiser-edited public copy: About Us title/body/checklist, gallery title/intro and contact-page FAQs. Empty object means the pages use their built-in defaults.';


